19681"] = "Tame Dire Mottled Boar", ["spell:19682"] = "Tame Surf Crawler", ["spell:19683"] = "Tame Armored Scorpid", ["spell:2641"] = "Dismiss Pet", ["spell:5149"] = "Beast Training", ["spell:75"] = "Auto Shot", ["spell:883"] = "Call Pet", ["spell:982"] = "Revive Pet", ["zone:1411"] = "Durotar", ["zone:1412"] = "Mulgore", ["zone:1413"] = "Barrens", ["zone:1454"] = "Orgrimmar", ["zone:1456"] = "Thunder Bluff", ["zone:2521"] = "Zephras Isle" },
			stepCount = 16,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:3171} in {area:362}\",\n\t\tnote = \"At 10 go to {npc:3171}, the hunter trainer inside the barracks in {area:362}. If {npc:3407} in {zone:1454}, {npc:11814} in {area:367} or {npc:3038} in {zone:1456} hands you {quest:6068}, take it and hand it to {npc:3171} for a little experience; it is only a pointer, and you can take the first rod without it.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 6062, title = \"Taming the Beast\", npc = 3171, npcName = \"Thotar\", minLevel = 10, qlvl = 10, crumbs = { 6068, 6069, 6070 }, preTitles = { [6068] = \"The Hunter's Path\", [6069] = \"The Hunter's Path\", [6070] = \"The Hunter's Path\" }, map = 1411, x = 51.82, y = 43.51, z = 11.7, note = \"{npc:3171}: the first {item:15908}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:3099}\",\n\t\tnote = \"Dire Mottled Boars (level 6-7) roam just north and west of {area:362}. How the rod works: target a living beast, use the {item:15908} from inside its range and stand still for the whole channel while the beast hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again from {npc:3171}. The boars charge from 20 yards, so start with the rod, not {spell:75}. The tamed boar becomes your pet for practice. Keep each rod: it goes back to {npc:3171}.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"kill\", quest = 6062, title = \"Taming the Beast\", target = \"Dire Mottled Boar\", npc = 3099, count = 1, oi = 1, text = \"{spell:19681}\", map = 1411, x = 53.43, y = 46.16, z = 14.7, f = \"e\", spotsPacked = \"52.6,46.1,,50,2;51.6,55.6,,76,6;53.9,62.6,37.3,50,1;54.1,68.8,,70,3;51.8,78.1,22.7,50,1;41.8,50.4,68,61,3;45,43.2,35.3,70,4;46,34.9,22,50,1;41.7,32.4,,68,3;38.8,36.8,,50,3;53.6,31.6