			written = { ["At 10 {npc:2128}, the {area:159} mage trainer upstairs in the {area:2119}, sends you to {npc:4568} in the {zone:1458}. Taking it shuts out {quest:1884}; if {quest:1883} (from {zone:1454} or {zone:1456}) is in your log, abandon it first or {npc:2128} cannot give you this one. (A Troll who took this one in {area:159} follows the Balnir steps; an Undead who took {quest:1884} in Sen'jin, the {area:368} steps.)"] = "At 10 Cain Firesong, the Brill mage trainer upstairs in the Gallows' End Tavern, sends you to Anastasia Hartwell in the Undercity. Taking it shuts out Ju-Ju Heaps; if Speak with Un'thuwa (from Orgrimmar or Thunder Bluff) is in your log, abandon it first or Cain cannot give you this one. (A Troll who took this one in Brill follows the Balnir steps; an Undead who took Ju-Ju Heaps in Sen'jin, the Echo Isles steps.)" },
			stepCount = 7,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"Un'thuwa\",\n\t\tnote = \"Un'thuwa, the troll mage trainer, stands in {area:367} on the {zone:1411} coast south of {area:362}. Orcs coming from {zone:1454} can take {quest:1883} from {npc:7311} in the {object:172961} first; it is only a pointer and Un'thuwa gives {quest:1884} without it. Taking it shuts out the {zone:1458}'s {area:165}.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 1884, title = \"Ju-Ju Heaps\", npc = 5880, npcName = \"Un'Thuwa\", minLevel = 10, qlvl = 10, closedBy = { 1882 }, endNpcs = { 5880 }, xp = 850, crumbs = { 1883 }, preTitles = { [1882] = \"The Balnir Farmstead\", [1883] = \"Speak with Un'thuwa\" }, map = 1411, x = 56.22, y = 75.08, z = 21.1, note = \"Un'thuwa\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:2128} ({area:159})\",\n\t\tnote = \"At 10 {npc:2128}, the {area:159} mage trainer upstairs in the {area:2119}, sends you to {npc:4568} in the {zone:1458}. Taking it shuts out {quest:1884}; if {quest:1883} (from {zone:1454} or {zone:1456}) is in your log, abandon it first or {npc:2128} cannot give you this one. (A Troll who took this one in {area:159} follows the Balnir steps; an Undead who took {quest:1884} in Sen'jin, the {area:368} steps.)\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 1881, title = \"Speak with Anastasia\", npc = 2128, npcName = \"Cain Firesong\", minLevel = 10, qlvl = 10, closedBy = { 1882, 1883, 1884 }, endNpcs = { 4568 }, xp = 85, preTitles = { [1882] = \"The Balnir Farmstead\", [1883] = \"Speak with Un'thuwa\", [1884] = \"Ju-Ju Heaps\" }, map = 1420, x = 61.89, y = 52.45, z = 41.2 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {quest:1884}\",\n\t\tnote = \"Wade across the shallows south-east of Sen'jin to the main Echo Isle, where Zalazane (level 10) holds his camp with Hexed and Voodoo Trolls (level 8). The heaps you can click are the skull piles inside the raised huts around his camp, one hut holding two, more in the huts to the north; the skulls lying on the ground outside cannot be clicked. Destroy four. There are seven and each comes back 30 seconds after it is destroyed.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Scourge\" } },\n\t\twhen = { { k = \"onquest\", q = { 1884 } } },\n\t\tgoals = {\n\t\t\t{ t = \"interact\", quest = 1884, title = \"Ju-Ju Heaps\", object = 102986, objName = \"Ju-Ju Heap\", oi = 1, map = 1411, x = 67.81, y = 84.27, f = \"e\", spotsPacked = \"67.03,87.8,8.5,0;67.1,86.42,9.5,0;67.38,82.5,11.8,0;67.79,83.37,10.6,0;68.42,83.31,9.9,0;68.45,82.32,11.2,0;68.53,84.18,12.4,0\", note = \"{object:102986}, four of them\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to Un'thuwa\",\n\t\tnote = \"The orb is an off-hand for a one-hand weapon; the staff is a two-hander.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Scourge\" } },\n\t\twhen = { { k = \"onquest\", q = { 1884 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1884, title = \"Ju-Ju Heaps\", npc = 5880, npcName = \"Un'Thuwa\", map = 1411, x = 56.22, y = 75.08, z = 21.1, note = \"Un'thuwa: {item:7508} or {item:9513}\", rewards = { choices = { { item = 7508, itemName = \"Ley Orb\" }, { item = 9513, itemName = \"Ley Staff\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:4568}\",\n\t\tnote = \"Walk south from {area:159} to the {area:153} and take the lift down into the {zone:1458}. Anastasia stands in the {object:36082}, the north-east ring of the city.\",\n\t\tonly = { races = { \"Scourge\", \"Troll\" } },\n\t\twhen = { { k = \"onquest\", q = { 1881 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1881, title = \"Speak with Anastasia\", npc = 4568, npcName = \"Anastasia Hartwell\", map = 1458, x = 85.04, y = 10.31, z = -47.3, spotsPacked = \"85,10.3,-47.3,15,5\" },\n\t\t\t{ t = \"accept\", quest = 1882, title = \"The Balnir Farmstead\", npc = 4568, npcName = \"Anastasia Hartwell\", minLevel = 10, qlvl = 10, closedBy = { 1884 }, endNpcs = { 4568 }, xp = 850, crumbs = { 1881 }, preTitles = { [1881] = \"Speak with Anastasia\", [1884] = \"Ju-Ju Heaps\" }, map = 1458, x = 85.03, y = 10.48, z = -47.3, spotsPacked = \"85,10.3,-47.3,15,5\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1882}\",\n\t\tnote = \"{quest:1882} lies south-east of {area:159}, south of the road east to the {area:152}. The snapdragons grow in the farm's garden and look more like bushes than flowers; any of them will do and you need no {skill:182}. They come back within seconds.\",\n\t\tonly = { races = { \"Scourge\", \"Troll\" } },\n\t\twhen = { { k = \"onquest\", q = { 1882 } } },\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1882, title = \"The Balnir Farmstead\", item = 7227, itemName = \"Balnir Snapdragons\", count = 1, oi = 1, map = 1420, x = 77.5, y = 61.78, z = 35.7, f = \"e\", spotsPacked = \"77.3,61.68,35.8,0;77.46,62.05,36.1,0;77.73,61.62,35.5,0\", from = \"Balnir Snapdragons\", fromKind = \"object\", fromId = 102985 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to Anastasia\",\n\t\tonly = { races = { \"Scourge\", \"Troll\" } },\n\t\twhen = { { k = \"onquest\", q = { 1882 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1882, title = \"The Balnir Farmstead\", npc = 4568, npcName = \"Anastasia Hartwell\", map = 1458, x = 85.04, y = 10.31, z = -47.3, spotsPacked = \"85,10.3,-47.3,15,5\", note = \"{npc:4568}: {item:7507} or {item:9514}\", rewards = { choices = { { item = 7507, itemName = \"Arcane Orb\" }, { item = 9514, itemName = \"Arcane Staff\" } } } },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

