			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:4568}\",\n\t\tnote = \"{npc:4568} stands in the {zone:1458}'s {object:36082}. Orcs and Trolls use {spell:3563} or take the zeppelin from {zone:1454} to {zone:1420} for her.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 26 },\n\t\t\t{ t = \"accept\", quest = 1943, title = \"Speak with Deino\", npc = 4568, npcName = \"Anastasia Hartwell\", minLevel = 26, qlvl = 26, closedBy = { 1944 }, endNpcs = { 5885 }, xp = 210, preTitles = { [1944] = \"Waters of Xavian\" }, map = 1458, x = 85.04, y = 10.31, z = -47.3, spotsPacked = \"85,10.3,-47.3,15,5\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5885}\",\n\t\tnote = \"Take the zeppelin to {zone:1454} (or use {spell:3567}, which lands you on the upper floor of {object:173161}). {npc:5885} stands with the mage trainers on the lower floor of {object:173161} in the {object:172961}. She hands you {item:7269}.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1943, title = \"Speak with Deino\", npc = 5885, npcName = \"Deino\", map = 1454, x = 38.35, y = 86.05, z = 43, spotsPacked = \"38.3,86.1,43,15,3\" },\n\t\t\t{ t = \"accept\", quest = 1944, title = \"Waters of Xavian\", npc = 5885, npcName = \"Deino\", minLevel = 26, qlvl = 26, crumbs = { 1943 }, preTitles = { [1943] = \"Speak with Deino\" }, map = 1454, x = 38.33, y = 86.04, z = 43, spotsPacked = \"38.3,86.1,43,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {object:174797}\",\n\t\tnote = \"Fly to {area:431} and swim north up the river past the big lake to its far northern end, where the zone text reads {area:429}; satyrs hold the ruins around it and a few river beasts are in the way. Swim right in under the highest waterfall until you touch the rock wall, then use the flask (you can stay in the water). The waterfalls on the western Falfarren fork do not work.\",\n\t\tgoals = {\n\t\t\t{ t = \"use\", quest = 1944, title = \"Waters of Xavian\", item = 7269, itemName = \"Deino's Flask\", oi = 1, map = 1440, x = 76.29, y = 41.49, z = 208.8, f = \"e\", note = \"{item:7269}, under the falls\" },\n\t\t\t{ t = \"collect\", quest = 1944, title = \"Waters of Xavian\", item = 7268, itemName = \"Xavian Water Sample\", count = 1, oi = 1, map = 1440, x = 76.29, y = 41.49, z = 208.8, f = \"e\", from = \"Xavian Waterfall\", fromKind = \"object\", fromId = 174797 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:5885}\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1944, title = \"Waters of Xavian\", npc = 5885, npcName = \"Deino\", map = 1454, x = 38.35, y = 86.05, z = 43, spotsPacked = \"38.3,86.1,43,15,3\" },\n\t\t\t{ t = \"accept\", quest = 1945, title = \"Laughing Sisters\", npc = 5885, npcName = \"Deino\", minLevel = 26, qlvl = 26, pre = { 1944 }, preTitles = { [1944] = \"Waters of Xavian\" }, map = 1454, x = 38.33, y = 86.04, z = 43, spotsPacked = \"38.3,86.1,43,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {quest:1945}\",\n\t\tnote = \"The {quest:1945}, dryads of level 24-25, roam around the {area:426} in central {zone:1440}; every one drops a hair and they come back after 5 minutes. They often resist fire (and some frost and shadow): arcane spells land best. Each runs for help at low health. Keep clear of the guards by the white tower of the retreat, who hit hard.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1945, title = \"Laughing Sisters\", item = 7270, itemName = \"Laughing Sister's Hair\", count = 12, oi = 1, map = 1440, x = 59.87, y = 54.38, z = 158, f = \"e\", spotsPacked = \"59.4,55.4,,39,5;60.3,53.2,,27,2;60.3,55.8,135.7,29,3;58.6,54.7,155.2,16,2;61.2,51.6,,33,4;58.5,57.3,,56,5;61.3,49.7,,26,2,1;58.7,59.7,146.1,15,1,1;62.3,49.7,189,15,1,1\", lvl = 25, from = \"Laughing Sister\", fromKind = \"npc\", fromFaction = \"A\", fromId = 4054, fromNpcs = { { npc = 4054, npcName = \"Laughing Sister\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:3484}\",\n\t\tnote = \"{npc:3484}, a troll tailor, works at the Crossroads. The robe gives intellect, stamina and spirit; the tunic more intellect and stamina but no spirit.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1945, title = \"Laughing Sisters\", npc = 3484, npcName = \"Kil'hala\", map = 1413, x = 52.18, y = 31.75, z = 95.9 },\n\t\t\t{ t = \"accept\", quest = 1946, title = \"Nether-lace Garment\", npc = 3484, npcName = \"Kil'hala\", minLevel = 26, qlvl = 26, pre = { 1945 }, preTitles = { [1945] = \"Laughing Sisters\" }, map = 1413, x = 52.18, y = 31.75, z = 95.9 },\n\t\t\t{ t = \"turnin\", quest = 1946, title = \"Nether-lace Garment\", npc = 3484, npcName = \"Kil'hala\", map = 1413, x = 52.18, y = 31.75, z = 95.9, note = \"{quest:1946}\", rewards = { choices = { { item = 7512, itemName = \"Nether-lace Robe\" }, { item = 9515, itemName = \"Nether-lace Tunic\" } } } },\n\t\t},\n\t},\n}",
