-- Source: forever/class/mage/spellfire-robes.guide
do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/class/mage/spellfire-robes",
			pack = "guides",
			title = "{quest:1962}",
			faction = "Horde",
			classes = { "MAGE" },
			minLevel = 15,
			maxLevel = 18,
			category = "Class",
			folder = "Mage",
			keywords = { "Anastasia Hartwell", "Report to Anastasia", "Investigate the Alchemist Shop", "Gathering Materials", "Josef Gregorian", "Rift Spawn", "Dalaran Mana Gem", "Ambermill", "Silverpine Forest", "Lesser Spellfire Robes", "Mage", "class robe" },
			reward = { { item = 7510, itemName = "Lesser Spellfire Robes" } },
			why = "A robe at 15 for Horde mages, from the {zone:1458} and {zone:1421}.",
			zone = 1458,
			zoneName = "Undercity",
			author = "Polestar",
			version = 1,
			names = { ["area:159"] = "Brill", ["area:2119"] = "Gallows' End Tavern", ["area:228"] = "Sepulcher", ["area:233"] = "Ambermill", ["area:279"] = "Dalaran", ["item:2589"] = "Linen Cloth", ["item:7247"] = "Chest of Containment Coffers", ["item:7292"] = "Filled Containment Coffer", ["item:7293"] = "Dalaran Mana Gem", ["item:7308"] = "Cantation of Manifestation", ["item:7510"] = "Lesser Spellfire Robes", ["npc:11048"] = "Victor Ward", ["npc:11049"] = "Rhiannon Davis", ["npc:1867"] = "Dalaran Apprentice", ["npc:2128"] = "Cain Firesong", ["npc:4568"] = "Anastasia Hartwell", ["npc:4576"] = "Josef Gregorian", ["npc:6492"] = "Rift Spawn", ["npc:7311"] = "Uthel'nay", ["object:172961"] = "Valley of Spirits", ["object:173161"] = "Darkbriar Lodge", ["object:36082"] = "Magic Quarter", ["quest:1962"] = "Spellfire Robes", ["spell:116"] = "Frostbolt", ["spell:122"] = "Frost Nova", ["spell:134"] = "Fire Shield", ["spell:2120"] = "Flamestrike", ["zone:1420"] = "Tirisfal Glades", ["zone:1421"] = "Silverpine Forest", ["zone:1454"] = "Orgrimmar", ["zone:1458"] = "Undercity" },
			written = { ["Back to the {zone:1458}. {npc:4576}, {npc:11048} and {npc:11049} keep the tailor's shop in the {object:36082}. Hand the gems and cloth to {npc:4576} and let the three of them talk for a moment; then {npc:4576} offers {quest:1962}: take it and hand it straight back to him for the robe."] = "Back to the Undercity. Josef Gregorian, Victor Ward and Rhiannon Davis keep the tailor's shop in the Magic Quarter. Hand the gems and cloth to Josef and let the three of them talk for a moment; then Josef offers Spellfire Robes: take it and hand it straight back to him for the robe." },
			stepCount = 7,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:7311} ({zone:1454})\",\n\t\tnote = \"{npc:7311} is one of {zone:1454}'s mage trainers, in {object:173161} in the {object:172961}. Then take the zeppelin to {zone:1420} from the tower outside {zone:1454}'s main gate.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 15 },\n\t\t\t{ t = \"accept\", quest = 1959, title = \"Report to Anastasia\", npc = 7311, npcName = \"Uthel'nay\", minLevel = 15, qlvl = 15, closedBy = { 1960 }, endNpcs = { 4568 }, xp = 110, preTitles = { [1960] = \"Investigate the Alchemist Shop\" }, map = 1454, x = 38.93, y = 86.13, z = 43, spotsPacked = \"38.9,86.1,43,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:2128} ({area:159})\",\n\t\tnote = \"{npc:2128} is the {area:159} mage trainer, upstairs in the {area:2119}: take the stairs inside, the arrow cannot tell the floors apart.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 15 },\n\t\t\t{ t = \"accept\", quest = 1959, title = \"Report to Anastasia\", npc = 2128, npcName = \"Cain Firesong\", minLevel = 15, qlvl = 15, closedBy = { 1960 }, endNpcs = { 4568 }, xp = 110, preTitles = { [1960] = \"Investigate the Alchemist Shop\" }, map = 1420, x = 61.89, y = 52.45, z = 41.2 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:4568}\",\n\t\tnote = \"{npc:4568} stands in the {object:36082}. The {item:7247} and the {item:7308} lie on the ledge behind her (both come back 5 minutes after someone takes them). You hand both in at the end, so keep them.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1959, title = \"Report to Anastasia\", npc = 4568, npcName = \"Anastasia Hartwell\", map = 1458, x = 85.04, y = 10.31, z = -47.3, spotsPacked = \"85,10.3,-47.3,15,5\" },\n\t\t\t{ t = \"accept\", quest = 1960, title = \"Investigate the Alchemist Shop\", npc = 4568, npcName = \"Anastasia Hartwell\", minLevel = 15, qlvl = 16, crumbs = { 1959 }, preTitles = { [1959] = \"Report to Anastasia\" }, map = 1458, x = 85.03, y = 10.48, z = -47.3, spotsPacked = \"85,10.3,-47.3,15,5\" },\n\t\t\t{ t = \"collect\", quest = 1960, title = \"Investigate the Alchemist Shop\", item = 7247, itemName = \"Chest of Containment Coffers\", count = 1, oi = 2, map = 1458, x = 85.02, y = 10.39, z = -46.3, f = \"e\", spotsPacked = \"85.2,10.3,-46.3,15,3\", from = \"Chest of Containment Coffers\", fromKind = \"object\", fromId = 105174 },\n\t\t\t{ t = \"collect\", quest = 1960, title = \"Investigate the Alchemist Shop\", item = 7308, itemName = \"Cantation of Manifestation\", count = 1, oi = 3, map = 1458, x = 85.27, y = 10.32, z = -46.3, f = \"e\", spotsPacked = \"85.5,10.3,-46.3,15,2\", from = \"Cantation of Manifestation\", fromKind = \"object\", fromId = 105175 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The alchemist shop\",\n\t\tnote = \"Algernon's alchemist shop is in the Apothecarium. Stand on the steps or the bridge outside the shop and read the {item:7308}: up to four invisible Rift Spawns (level 16-17) appear and attack at once, and the city guards do not help. Hit one with a single-target spell and back off over the bridge: the others give up and fade, the one you hit follows. Beat it down on the shop's half of the bridge (past halfway the coffer will not work on it) until it stops fighting and sits stunned under a spiral, use the {item:7247} on it, then click the {item:7292} once it appears on the floor (clicking too early wastes a charge). Three are needed.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 16 },\n\t\t\t{ t = \"use\", item = 7308, itemName = \"Cantation of Manifestation\", map = 1458, x = 53.2, y = 74.5, f = \"e\", optional = true },\n\t\t\t{ t = \"kill\", target = \"Rift Spawn\", npc = 6492, map = 1458, x = 53.29, y = 74.56, z = -66, f = \"e\", spotsPacked = \"53,74.7,-66,21,4\", lvl = 17, optional = true, note = \"{npc:6492}, down to the stun\" },\n\t\t\t{ t = \"use\", item = 7247, itemName = \"Chest of Containment Coffers\", map = 1458, x = 53.2, y = 74.5, f = \"e\", optional = true, note = \"{item:7247}, on the stunned {npc:6492}\" },\n\t\t\t{ t = \"collect\", quest = 1960, title = \"Investigate the Alchemist Shop\", item = 7292, itemName = \"Filled Containment Coffer\", count = 3, oi = 1, map = 1458, x = 53.2, y = 74.5, z = -66, f = \"e\", spotsPacked = \"53.35,74.43,-66,0;53.41,70.86,-66,0;53.62,73.13,-66,0;53.69,75.22,-66,0;53.93,72.41,-66,0;54.05,74.09,-66,0\", from = \"Filled Containment Coffer\", fromKind = \"object\", fromId = 103574 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:4568}\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1960, title = \"Investigate the Alchemist Shop\", npc = 4568, npcName = \"Anastasia Hartwell\", map = 1458, x = 84.73, y = 10.44, z = -47.3, spotsPacked = \"85,10.3,-47.3,15,5\" },\n\t\t\t{ t = \"accept\", quest = 1961, title = \"Gathering Materials\", npc = 4568, npcName = \"Anastasia Hartwell\", minLevel = 15, qlvl = 15, pre = { 1960 }, preTitles = { [1960] = \"Investigate the Alchemist Shop\" }, map = 1458, x = 84.73, y = 10.44, z = -47.3, spotsPacked = \"85,10.3,-47.3,15,5\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{area:233}\",\n\t\tnote = \"Leave the {zone:1458} and follow the road south through {zone:1421}. Every {area:279} human drops a {item:7293} four times in five, and {item:2589} too: the easiest are the Dalaran Apprentices (level 13-14, {spell:116}) on the hills south-east of the {area:228}, either side of the road south; deeper in, the walled town of {area:233} in south-east Silverpine has Watchers (18-19, {spell:134} and {spell:2120}) and Wizards (19-20, {spell:122}) that come back every 4 1/2 minutes and run for help at low health, so pull at the edge. Ten {item:2589} also come from any humanoid or the Undercity Auction House.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 17 },\n\t\t\t{ t = \"collect\", quest = 1961, title = \"Gathering Materials\", item = 7293, itemName = \"Dalaran Mana Gem\", count = 6, oi = 2, map = 1421, x = 52.25, y = 64.46, f = 