			maxLevel = 50,
			category = "Class",
			folder = "Mage",
			keywords = { "Teleport", "Portal", "Teleport: Orgrimmar", "Teleport: Undercity", "Teleport: Thunder Bluff", "Portal: Orgrimmar", "Portal: Undercity", "Portal: Thunder Bluff", "Thuul", "Lexington Mortaim", "Birgitte Cranston", "Portal Trainer", "Rune of Teleportation", "Rune of Portals", "reagent vendor", "Mage", "class spell" },
			reward = { { spell = 3567, spellName = "Teleport: Orgrimmar" }, { spell = 3563, spellName = "Teleport: Undercity" }, { spell = 3566, spellName = "Teleport: Thunder Bluff" }, { spell = 11417, spellName = "Portal: Orgrimmar" }, { spell = 11418, spellName = "Portal: Undercity" }, { spell = 11420, spellName = "Portal: Thunder Bluff" } },
			why = "Your city teleports at 20 and 30 and the group portals at 40 and 50, from each city's portal trainer.",
			zone = 1454,
			zoneName = "Orgrimmar",
			author = "Polestar",
			version = 1,
			names = { ["area:1640"] = "Spirit Rise", ["area:2197"] = "Pools of Vision", ["item:17031"] = "Rune of Teleportation", ["item:17032"] = "Rune of Portals", ["npc:2492"] = "Lexington Mortaim", ["npc:4575"] = "Hannah Akeley", ["npc:5957"] = "Birgitte Cranston", ["npc:5958"] = "Thuul", ["object:172961"] = "Valley of Spirits", ["object:173161"] = "Darkbriar Lodge", ["object:36082"] = "Magic Quarter", ["spell:11417"] = "Portal: Orgrimmar", ["spell:11418"] = "Portal: Undercity", ["spell:11420"] = "Portal: Thunder Bluff", ["spell:3563"] = "Teleport: Undercity", ["spell:3566"] = "Teleport: Thunder Bluff", ["spell:3567"] = "Teleport: Orgrimmar", ["zone:1412"] = "Mulgore", ["zone:1420"] = "Tirisfal Glades", ["zone:1454"] = "Orgrimmar", ["zone:1456"] = "Thunder Bluff", ["zone:1458"] = "Undercity" },
			stepCount = 5,
			stepsSrc = "local candidateLists = {\n\t{ { npc = 12795, npcName = \"First Sergeant Hola'mahi\", map = 1454, x = 37.96, y = 64.24, z = 56.2, faction = \"H\" }, { npc = 3323, npcName = \"Horthus\", map = 1454, x = 45.44, y = 56.78, z = 33.4, faction = \"H\" }, { npc = 3335, npcName = \"Hagrus\", map = 1454, x = 45.93, y = 46, z = -15.6, faction = \"H\" }, { npc = 3490, npcName = \"Hula'mahi\", map = 1413, x = 51.35, y = 30.2, z = 95.9, faction = \"H\" }, { npc = 16015, npcName = \"Vi'el\", map = 1452, x = 58.87, y = 78.39, z = 892.4, f = \"e\", faction = \"AH\" }, { npc = 13476, npcName = \"Balai Lok'Wein\", map = 1445, x = 36.41, y = 30.35, z = 34.7, faction = \"H\" }, { npc = 8361, npcName = \"Chepi\", map = 1456, x = 42.33, y = 56.17, faction = \"H\" }, { npc = 4083, npcName = \"Jeeda\", map = 1442, x = 47.55, y = 61.69, z = 114.6, faction = \"H\" }, { npc = 4878, npcName = \"Montarr\", map = 1441, x = 45.1, y = 50.66, z = 89.6, faction = \"H\" }, { npc = 3500, npcName = \"Tarhus\", map = 1444, x = 74.62, y = 44.8, z = 39.2, faction = \"H\" }, { npc = 15175, npcName = \"Khur Hornstriker\", map = 1451, x = 48.67, y = 37, z = 49.5, f = \"e\", faction = \"AH\" }, { npc = 14739, npcName = \"Mystic Yayo'jin\", map = 1425, x = 78.74, y = 78.39, z = 13.1, faction = \"H\" }, { npc = 983, npcName = \"Thultazor\", map = 1435, x = 45.96, y = 52.95, z = 20.5, faction = \"H\" }, { npc = 4562, npcName = \"Thomas Mordan\", map = 1458, x = 69.46, y = 39.28, z = -43, faction = \"H\" }, { npc = 4575, npcName = \"Hannah Akeley\", map = 1458, x = 82.61, y = 15.92, z = -59.3, faction = \"H\" }, { npc = 10364, npcName = \"Yaelika Farclaw\", map = 1459, x = 48.37, y = 80.32, f = \"e\", faction = \"H\" } },\n}\nreturn {\n\t{\n\t\ttitle = \"{spell:3567}\",\n\t\tnote = \"At 20 go to {object:173161} in {zone:1454}'s {object:172961}, where the mage trainers live. {npc:5958}, the portal trainer, stands on the upper floor and teaches {spell:3567} for 20 silver. Every teleport burns one {item:17031} (10 silver at any reagent vendor), so carry a few.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 20 },\n\t\t\t{ t = \"money\", money = 3000 },\n\t\t\t{ t = \"train\", npc = 5958, npcName = \"Thuul\", map = 1454, x = 38.55, y = 85.43, z = 59.1, spotsPacked = \"38.5,85.4,59.1,15,3\", note = \"{npc:5958}: {spell:3567}\" },\n\t\t\t{ t = \"buy\", item = 17031, itemName = \"Rune of Teleportation\", count = 5, note = \"{item:17031}, 10s each\", candidates = candidateLists[1] },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{spell:3563}\",\n\t\tnote = \"Take the zeppelin from the tower outside {zone:1454}'s gate to {zone:1420} and walk into the {zone:1458}. {npc:2492}, the portal trainer, stands in the {object:36082} with the mage trainers: {spell:3563}, 20 silver. {npc:4575} beside him sells the runes.\",\n\t\tgoals = {\n\t\t\t{ t = \"money\", money = 2000 },\n\t\t\t{ t = \"train\", npc = 2492, npcName = \"Lexington Mortaim\", map = 1458, x = 84.07, y = 15.81, z = -46.2, spotsPacked = \"84.1,15.8,-46.2,15,5\", note = \"{npc:2492}: {spell:3563}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{spell:3566}\",\n\t\tnote = \"At 30. {zone:1456} is in {zone:1412}: fly there from {zone:1454} or the Crossroads. {npc:5957}, the portal trainer, stands with the mage trainers in the {area:2197}, the cave under {area:1640}: go down inside, the arrow cannot tell the floors apart. She teaches {spell:3566} for 80 silver.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 30 },\n\t\t\t{ t = \"money\", money = 8000 },\n\t\t\t{ t = \"train\", npc = 5957, npcName = \"Birgitte Cranston\", map = 1456, x = 22.26, y = 16.93, z = 110.8, spotsPacked = \"22.3,16.9,110.8,15,3\", note = \"{npc:5957}: {spell:3566}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Portals to {zone:1454} and the {zone:1458}\",\n\t\tnote = \"At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one {item:17032} (20 silver at any reagent vendor). {npc:5958} in {object:173161} has {spell:11417}; teleport to the {zone:1458} for {npc:2492}'s {spell:11418}.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 40 },\n\t\t\t{ t = \"money\", money = 30000 },\n\t\t\t{ t = \"train\", npc = 5958, npcName = \"Thuul\", map = 1454, x = 38.55, y = 85.43, z = 59.1, spotsPacked = \"38.5,85.4,59.1,15,3\", note = \"{npc:5958}: {spell:11417}\" },\n\t\t\t{ t = \"buy\", item = 17032, itemName = \"Rune of Portals\", count = 5, note = \"{item:17032}, 20s each\", candidates = candidateLists[1] },\n\t\t\t{ t = \"train\", npc = 2492, npcName = \"Lexington Mortaim\", map = 1458, x = 84.07, y = 15.81, z = -46.2, spotsPacked = \"84.1,15.8,-46.2,15,5\", note = \"{npc:2492}, {zone:1458}: {spell:11418}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{spell:11420}\",\n\t\tnote = \"At 50 {npc:5957}, down in the {area:2197} under {area:1640} in {zone:1456}, teaches the last one, {spell:11420}, for 3 gold 20 silver. Use your {spell:3566} to get there.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 50 },\n\t\t\t{ t = \"money\", money = 32000 },\n\t\t\t{ t = \"train\", npc = 5957, npcName = \"Birgitte Cranston\", map = 1456, x = 22.26, y = 16.93, z = 110.8, spotsPacked = \"22.3,16.9,110.8,15,3\", note = \"{npc:5957}: {spell:11420}\" },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

