			version = 1,
			group = true,
			names = { ["area:156"] = "Solliden Farmstead", ["area:1581"] = "The Deadmines", ["area:16602"] = "Bandarion Keep", ["area:17065"] = "Gilneas", ["area:172"] = "Fenris Isle", ["area:20"] = "Moonbrook", ["area:228"] = "Sepulcher", ["area:235"] = "Fenris Keep", ["area:236"] = "Shadowfang Keep", ["area:272"] = "Tarren Mill", ["area:2797"] = "Blackfathom Deeps", ["area:2897"] = "Zoram'gar Outpost", ["area:414"] = "Zoram Strand", ["item:267361"] = "Enchanted Silver Ingot", ["item:267369"] = "Wolfsbane", ["item:267412"] = "Fenris Isle Key", ["item:267454"] = "Trevan's Weapon Notes", ["item:268192"] = "Bundle of Blacksmithing Materials", ["item:268484"] = "Moonsilver Blade", ["item:272448"] = "Purified Kor Gem", ["item:6994"] = "Whitestone Oak Lumber", ["item:6995"] = "Corrupted Kor Gem", ["npc:11870"] = "Archibald", ["npc:1944"] = "Rot Hide Bruiser", ["npc:246378"] = "Danitha Morr", ["npc:248755"] = "Lumina Windsinger", ["npc:248840"] = "Trevan Rol", ["npc:259611"] = "Deathguard Baldren", ["npc:259620"] = "Lumina Windsinger", ["npc:259649"] = "Ulric Frostveil", ["npc:3539"] = "Ott", ["npc:4275"] = "Archmage Arugal", ["npc:641"] = "Goblin Woodcarver", ["object:3202"] = "Grom'gol", ["object:36070"] = "War Quarter", ["object:566037"] = "Charred Remains", ["quest:91862"] = "Lumina Windsinger", ["quest:95034"] = "The Debt", ["quest:95036"] = "A Moon-Kissed Blade", ["quest:95125"] = "Ott's Masterwork", ["quest:95126"] = "The Moonsilver Blade", ["quest:95140"] = "Old Fire-Eye", ["spell:122"] = "Frost Nova", ["spell:202"] = "Two-Handed Swords", ["zone:1413"] = "Barrens", ["zone:1421"] = "Silverpine Forest", ["zone:1424"] = "Hillsbrad Foothills", ["zone:1431"] = "Duskwood", ["zone:1434"] = "Stranglethorn Vale", ["zone:1436"] = "Westfall", ["zone:1440"] = "Ashenvale", ["zone:1454"] = "Orgrimmar", ["zone:1458"] = "Undercity" },
			written = { ["At 20 {npc:259620} asks for a blade that can kill {quest:95140}. Talk to {npc:248840} beside her for his Weapon Notes, which list the parts, and keep them: he wants them back with the parts. Three parts, in any order: two from dungeons (a group of five each) and a gem from elite naga outside a third."] = "At 20 Lumina asks for a blade that can kill Old Fire-Eye. Talk to Trevan Rol beside her for his Weapon Notes, which list the parts, and keep them: he wants them back with the parts. Three parts, in any order: two from dungeons (a group of five each) and a gem from elite naga outside a third.", ["Back to {npc:259620} in the {area:228} with the {item:268484} (the quest asks for it): she takes it and blesses it with the magic of her people into {item:267369}."] = "Back to Lumina in the Sepulcher with the Moonsilver Blade (the quest asks for it): she takes it and blesses it with the magic of her people into Wolfsbane.", ["Back to {npc:259649} at Zoram'gar: he cleanses the gem. Keep the {item:272448} for {npc:248840}."] = "Back to Ulric at Zoram'gar: he cleanses the gem. Keep the Purified Kor Gem for Trevan.", ["Bring the lumber, the ingot and the gem to {npc:248840} in the {area:228}. He gives you a {item:268192} for a smith in {area:272}: keep it in your bags."] = "Bring the lumber, the ingot and the gem to Trevan in the Sepulcher. He gives you a Bundle of Blacksmithing Materials for a smith in Tarren Mill: keep it in your bags.", ["Free {npc:248755}"] = "Free Lumina", ["Hand in the key first: starting the escort before that gives the key quest no credit. Then open the cage: {npc:248755} walks out through the keep and its courtyard while the gnolls attack, then runs for the dock and makes her own way back to the {area:228}. Stay close and keep her alive; if she dies, take the quest again when she is back in her cage."] = "Hand in the key first: starting the escort before that gives the key quest no credit. Then open the cage: Lumina walks out through the keep and its courtyard while the gnolls attack, then runs for the dock and makes her own way back to the Sepulcher. Stay close and keep her alive; if she dies, take the quest again when she is back in her cage.", ["{area:228}"] = "The Sepulcher", ["{npc:259649} waits at {area:2897} on {zone:1440}'s west coast: take the zeppelin from {object:3202} (or the {zone:1458}) to {zone:1454}, then go north through the {zone:1413} into {zone:1440} and west along the road. Andruk, the outpost's wind rider master, saves you the walk next time. Take {npc:259649}'s quest before you hunt the naga: the Kor Gem only drops while you have it."] = "Ulric Frostveil waits at Zoram'gar Outpost on Ashenvale's west coast: take the zeppelin from Grom'gol (or the Undercity) to Orgrimmar, then go north through the Barrens into Ashenvale and west along the road. Andruk, the outpost's wind rider master, saves you the walk next time. Take Ulric's quest before you hunt the naga: the Kor Gem only drops while you have it." },
			stepCount = 19,
			groupQuests = { { quest = 96204, title = "The Windshaper's Wrath", escort = true } },
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:246378}\",\n\t\tnote = \"At 18 {npc:246378}, inside {area:16602} on the bluffs north-west of the {area:156}, sends you south to the {area:228} in {zone:1421}.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 18 },\n\t\t\t{ t = \"accept\", quest = 91858, title = \"Diplomatic Incident\", npc = 246378, npcName = \"Danitha Morr\", minLevel = 18, qlvl = 22, map = 1420, x = 22, y = 44.66, z = 155.7 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{area:228}\",\n\t\tnote = \"{npc:248840} stands in the lower part of the {area:228}, below the surface; {npc:259611} keeps watch near the town's entrance.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 21 },\n\t\t\t{ t = \"turnin\", quest = 91858, title = \"Diplomatic Incident\", npc = 248840, npcName = \"Trevan Rol\", map = 1421, x = 43.29, y = 41.03, z = 104.9 },\n\t\t\t{ t = \"accept\", quest = 91859, title = \"A Curious Pair\", npc = 248840, npcName = \"Trevan Rol\", minLevel = 18, qlvl = 22, pre = { 91858 }, preTitles = { [91858] = \"Diplomatic Incident\" }, map = 1421, x = 43.29, y = 41.03, z = 104.9 },\n\t\t\t{ t = \"turnin\", quest = 91859, title = \"A Curious Pair\", npc = 259611, npcName = \"Deathguard Baldren\", map = 1421, x = 45.69, y = 41.82, z = 128.8 },\n\t\t\t{ t = \"accept\", quest = 91860, title = \"A Grim Fate\", npc = 259611, npcName = \"Deathguard Baldren\", minLevel = 18, qlvl = 22, pre = { 91859 }, preTitles = { [91859] = \"A Curious Pair\" }, map = 1421, x = 45.69, y = 41.82, z = 128.8 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The pyre on {area:172}\",\n\t\tnote = \"{area:172} lies in the lake north-east of the {area:228}. The gnolls' pyre, with the {object:566037}, is on its shore: click the remains to hand in, and click them again for the next quest. The body is a tauren's, not the elf's.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 91860, title = \"A Grim Fate\", object = 566037, objName = \"Charred Remains\", map = 1421, x = 64.89, y = 34.35 },\n\t\t\t{ t = \"accept\", quest = 91861, title = \"Into Fenris Keep\", object = 566037, objName = \"Charred Remains\", minLevel = 18, qlvl = 22, pre = { 91860 }, preTitles = { [91860] = \"A Grim Fate\" }, map = 1421, x = 64.89, y = 34.35, note = \"from the {object:566037}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{area:235}\",\n\t\tnote = \"{quest:91862} is caged in the basement of {area:235}, at the north end of the isle. The Rot Hide gnolls (level 18-19) fill the keep: they pull in big groups across floors and players report very fast respawns, so clear a path and keep moving. Any of them can carry the {item:267412} (often the first kill); the rare {npc:1944} (22) and Snarlmane (23) can too. If her cage is empty, another player is escorting her: wait for her to come back.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 22 },\n\t\t\t{ t = \"turnin\", quest = 91861, title = \"Into Fenris Keep\", npc = 248755, npcName = \"Lumina Windsinger\", map = 1421, x = 65.56, y = 23.46 },\n\t\t\t{ t = \"accept\", quest = 91862, title = \"Lumina Windsinger\", npc = 248755, npcName = \"Lumina Windsinger\", minLevel = 18, qlvl = 22, pre = { 91861 }, preTitles = { [91861] = \"Into Fenris Keep\" }, map = 1421, x = 65.56, y = 23.46 },\n\t\t\t{ t = \"collect\", quest = 91862, title = \"Lumina Windsinger\", item = 267412, itemName = \"Fenris Isle Key\", count = 1, oi = 1, map = 1421, x = 65.57, y = 23.32, z = 61, f = \"e\", spotsPacked = \"65.85,23.87,69.8,28,13\", lvl = 19, note = \"{item:267412}, from the Rot Hide gnolls\", fromNpcs = { { npc = 1942, npcName = \"Rot Hide Savage\" }, { npc = 1943, npcName = \"Raging Rot Hide\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Free {npc:248755}\",\n\t\tnote = \"Hand in the key first: starting the escort before that gives the key quest no credit. Then open the cage: {npc:248755} walks out through the keep and its courtyard while the gnolls attack, then runs for the dock and makes her own way back to the {area:228}. Stay close and keep her alive; if she dies, take the quest again when she is back in her cage.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 21 },\n\t\t\t{ t = \"turnin\", quest = 91862, title = \"Lumina Windsinger\", npc = 248755, npcName = \"Lumina Windsinger\", map = 1421, x = 65.56, y = 23.46 },\n\t\t\t{ t = \"accept\", quest = 96204, title = \"The Windshaper's Wrath\", npc = 248755, npcName = \"Lumina Windsinger\", minLevel = 18, qlvl = 22, pre = { 91862 }, preTitles = { [91862] = \"Lumina Windsinger\" }, map = 1421, x = 65.56, y = 23.46, escort = true },\n\t\t\t{ t = \"complete\", quest = 96204, title = \"The Windshaper's Wrath\", map = 1421, x = 65.7, y = 29.7, f = \"e\", escort = true, objs = { { text = \"Lumina Windsinger\", count = 1 }, { text = \"Escort Lumina Windsinger to safety\", count = 1 } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to the {area:228}\",\n\t\tnote = \"Lumina waits beside {npc:248840} in the {area:228} (a different Lumina from the one you escorted). For {quest:95034}, click through every line of her story.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 23 },\n\t\t\t{ t = \"turnin\", quest = 96204, title = \"The Windshaper's Wrath\", npc = 259620, npcName = \"Lumina Windsinger\", map = 1421, x = 43.31, y = 40.95, z = 105, note = \"{npc:248755}, the {area:228}\" },\n\t\t\t{ t = \"accept\", quest = 95034, title = \"The Debt\", npc = 259620, npcName = \"Lumina Windsinger\", minLevel = 18, qlvl = 24, pre = { 96204 }, preTitles = { [96204] = \"The Windshaper's Wrath\" }, map = 1421, x = 43.31, y = 40.95, z = 105 },\n\t\t\t{ t = \"talk\", quest = 95034, title = \"The Debt\", npc = 259620, npcName = \"Lumina Windsinger\", oi = 1, map = 1421, x = 43.31, y = 40.95, z = 105, note = \"{npc:248755}: hear her story to the end\" },\n\t\t\t{ t = \"turnin\", quest = 95034, title = \"The Debt\", npc = 259620, npcName = \"Lumina Windsinger\", map = 1421, x = 43.31, y = 40.95, z = 105 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:95036}\",\n\t\tnote = \"At 20 {npc:259620} asks for a blade that can kill {quest:95140}. Talk to {npc:248840} beside her for his Weapon Notes, which list the parts, and keep them: he wants them back with the parts. Three parts, in any order: two from dungeons (a group of five each) and a gem from elite naga outside a third.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 24 },\n\t\t\t{ t = \"accept\", quest = 95036, title = \"A Moon-Kissed Blade\", npc = 259620, npcName = \"Lumina Windsinger\", minLevel = 20, qlvl = 25, pre = { 95034 }, preTitles = { [95034] = \"The Debt\" }, map = 1421, x = 43.31, y = 40.95, z = 105 },\n\t\t\t{ t = \"collect\", npc = 248840, npcName = \"Trevan Rol\", item = 267454, itemName = \"Trevan's Weapon Notes\", map = 1421, x = 43.29, y = 41.03, z = 105, note = \"{item:267454}: talk to {npc:248840}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {item:267361}\",\n\t\tnote = \"{area:236} is the dungeon in south Silverpine, for a group of five in the low to mid 20s. The ingot sits on the table next to {npc:4275} at the very end. A friend's cleared instance works: walk in and run to the table.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 25 },\n\t\t\t{ t = \"goto\", text = \"{area:236}\", area = 236, map = 1421, x = 44.8, y = 67.8 },\n\t\t\t{ t = \"collect\", quest = 95036, title = \"A Moon-Kissed Blade\", item = 267361, itemName = \"Enchanted Silver Ingot\", count = 1, oi = 3, map = 1421, x = 44.8, y = 67.8, note = \"{item:267361}, on Arugal's table\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:6994}\",\n\t\tnote = \"{area:1581} lies under {area:20} in {zone:1436}, Alliance land: a group of five at about 17-24. From the {zone:1458} take the zeppelin to {object:3202} in {zone:1434} and go north through {zone:1431} into {zone:1436}. The way in is the {area:20} mine. The Goblin Woodcarvers (elite, level 18-19) in Sneed's mast room drop the lumber every time.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 25 },\n\t\t\t{ t = \"goto\", text = \"{area:1581}, in the {area:20} mine\", map = 1436, x = 42.5, y = 71.7 },\n\t\t\t{ t = \"collect\", quest = 95036, title = \"A Moon-Kissed Blade\", item = 6994, itemName = \"Whitestone Oak Lumber\", count = 1, oi = 2, map = 1436, x = 42.5, y = 71.7, note = \"Goblin Woodcarvers, inside\", group = { kind = \"elite\", lvl = 19, rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:259649}\",\n\t\tnote = \"{npc:259649} waits at {area:2897} on {zone:1440}'s west coast: take the zeppelin from {object:3202} (or the {zone:1458}) to {zone:1454}, then go north through the {zone:1413} into {zone:1440} and west along the road. Andruk, the outpost's wind rider master, saves you the walk next time. Take {npc:259649}'s quest before you hunt the naga: the Kor Gem only drops while you have it.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 24 },\n\t\t\t{ t = \"accept\", quest = 95042, title = \"Seeking the Kor Gem\", npc = 259649, npcName = \"Ulric Frostveil\", minLevel = 20, qlvl = 25, parent = 95036, preTitles = { [95036] = \"A Moon-Kissed Blade\" }, map = 1440, x = 11.84, y = 34.49, z = 3.2, note = \"{npc:259649}, {area:2897}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The north end of the {area:414}\",\n\t\tnote = \"The naga's flooded ruins lie just past the north end of the {area:414}. The arrow cannot find its own way down into them, so it leads you to the water's edge first: from there swim north into the ruins.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 25 },\n\t\t\t{ t = \"goto\", text = \"The north end of the {area:414}\", map = 1440, x = 14.6, y = 13.7, f = \"e\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {item:6995}\",\n\t\tnote = \"The naga stand in the flooded ruins and passages around the {area:2797} entrance, just north of Zoram'gar: you do not need to enter the instance (its first naga drop the gem too). Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24) drop the {item:6995}, one in two. All are elite: grouping up is encouraged. Players solo them one at a time, with difficulty; a group of three makes it easy. They heal themselves, run for help at low health, and the Sea Witches cast {spell:122} up close. Some players report no drop while in a raid group.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 25 },\n\t\t\t{ t = \"collect\", quest = 95042, title = \"Seeking the Kor Gem\", item = 6995, itemName = \"Corrupted Kor Gem\", count = 1, oi = 1, map = 1440, x = 13.55, y = 12.06, z = -9.6, f = \"e\", spotsPacked = \"13.99,9.66,,53,7;16.2,11.3,,58,5;13.6,12.1,-9.6,15,1,1,21;17.7,11.1,-28.8,15,1,1\", lvl = 22, fromNpcs = { { npc = 4802, npcName = \"Blackfathom Tide Priestess\" }, { npc = 4803, npcName = \"Blackfathom Oracle\" } }, group = { kind = \"elite\", lvl = 22, rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {item:272448}\",\n\t\tnote = \"Back to {npc:259649} at Zoram'gar: he cleanses the gem. Keep the {item:272448} for {npc:248840}.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 95042, title = \"Seeking the Kor Gem\", npc = 259649, npcName = \"Ulric Frostveil\", map = 1440, x = 11.84, y = 34.49, z = 3.2, note = \"{npc:259649}: {item:272448}\", rewards = { items = { { item = 272448, itemName = \"Purified Kor Gem\" } } }, repeatable = true },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:248840}\",\n\t\tnote = \"Bring the lumber, the ingot and the gem to {npc:248840} in the {area:228}. He gives you a {item:268192} for a smith in {area:272}: keep it in your bags.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 95036, title = \"A Moon-Kissed Blade\", npc = 248840, npcName = \"Trevan Rol\", map = 1421, x = 43.29, y = 41.03, z = 104.9 },\n\t\t\t{ t = \"accept\", quest = 95111, title = \"An Underrated Talent\", npc = 248840, npcName = \"Trevan Rol\", minLevel = 20, qlvl = 25, pre = { 95036 }, preTitles = { [95036] = \"A Moon-Kissed Blade\" }, map = 1421, x = 43.29, y = 41.03, z = 104.9 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:3539}\",\n\t\tnote = \"{npc:3539}, the weaponsmith, stands just south of {area:272} in {zone:1424}. Accepting {quest:95125} starts the forging: step back and wait near him until he is done.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 95111, title = \"An Underrated Talent\", npc = 3539, npcName = \"Ott\", map = 1424, x = 60.41, y = 26.26, z = 57, spotsPacked = \"60.4,26.3,57,15,2\", note = \"{npc:3539}, {area:272}\" },\n\t\t\t{ t = \"level\", level = 24 },\n\t\t\t{ t = \"accept\", quest = 95125, title = \"Ott's Masterwork\", npc = 3539, npcName = \"Ott\", minLevel = 20, qlvl = 25, pre = { 95111 }, preTitles = { [95111] = \"An Underrated Talent\" }, map = 1424, x = 60.33, y = 26.13, z = 57, spotsPacked = \"60.4,26.3,57,15,2\" },\n\t\t\t{ t = \"complete\", quest = 95125, title = \"Ott's Masterwork\", note = \"Watch {npc:3539} forge the blade\", objs = { { text = \"Watch Ott craft the blade\", count = 1 } } },\n\t\t\t{ t = \"turnin\", quest = 95125, title = \"Ott's Masterwork\", npc = 3539, npcName = \"Ott\", map = 1424, x = 60.33, y = 26.13, z = 57, spotsPacked = \"60.4,26.3,57,15,2\" },\n\t\t\t{ t = \"accept\", quest = 95126, title = \"The Moonsilver Blade\", npc = 3539, npcName = \"Ott\", minLevel = 20, qlvl = 25, pre = { 95125 }, preTitles = { [95125] = \"Ott's Masterwork\" }, map = 1424, x = 60.33, y = 26.13, z = 57, spotsPacked = \"60.4,26.3,57,15,2\", note = \"{npc:3539} gives you {quest:95125}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:95126}\",\n\t\tnote = \"Back to {npc:248840} in the {area:228}'s lower part: he hands you the {item:268484}, a two-handed sword.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 95126, title = \"The Moonsilver Blade\", npc = 248840, npcName = \"Trevan Rol\", map = 1421, x = 43.29, y = 41.03, z = 104.9, note = \"{npc:248840}: {item:268484}\", rewards = { items = { { item = 268484, itemName = \"Moonsilver Blade\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{spell:202}\",\n\t\tnote = \"The blade is a two-handed sword, and you need the skill to hit a level 25 elite with it. {npc:11870}, the weapon master in the {zone:1458}'s {object:36070}, teaches {spell:202} for a small fee; then swing it on easy mobs until the skill is near its cap (five points per level).\",\n\t\tgoals = {\n\t\t\t{ t = \"train\", npc = 11870, npcName = \"Archibald\", map = 1458, x = 57.15, y = 32.54, z = -62.1, spotsPacked = \"57.2,32.5,-62.1,15,7\", optional = true, note = \"{npc:11870}, {object:36070}: {spell:202}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:95140}\",\n\t\tnote = \"Equip the {item:268484}. {quest:95140}, the great worgen, roams the woods south of the {area:228} toward the gates of {area:17065}. He is elite (level 25): the guide waits for level 25 first, and grouping up is encouraged; players have killed him from 22 up, one needed a second, another soloed him at 25. A purple shield guards him until your first swing with the blade lands: a message tells you it broke.\",\n\t\tgoals = {\n\t\t\t{ t = \"accept\", quest = 95140, title = \"Old Fire-Eye\", npc = 259620, npcName = \"Lumina Windsinger\", minLevel = 20, qlvl = 26, pre = { 95126 }, preTitles = { [95126] = \"The Moonsilver Blade\" }, map = 1421, x = 43.31, y = 40.95, z = 105, note = \"{npc:259620}, the {area:228}\" },\n\t\t\t{ t = \"level\", level = 25 },\n\t\t\t{ t = \"kill\", quest = 95140, title = \"Old Fire-Eye\", target = \"Old Fire-Eye\", npc = 259897, count = 1, oi = 1, map = 1421, x = 49.67, y = 87.97, f = \"e\", spotsPacked = \"49.67,87.97,,42\", note = \"{quest:95140}, with the {item:268484} equipped\", group = { kind = \"elite\", lvl = 25, rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:267369}\",\n\t\tnote = \"Back to {npc:259620} in the {area:228} with the {item:268484} (the quest asks for it): she takes it and blesses it with the magic of her people into {item:267369}.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 95140, title = \"Old Fire-Eye\", npc = 259620, npcName = \"Lumina Windsinger\", map = 1421, x = 43.31, y = 40.95, z = 105, note = \"{npc:259620}: {item:267369}\", rewards = { items = { { item = 267369, itemName = \"Wolfsbane\" } } } },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

-- Source: forever/class/paladin/tyrs-watch.guide
do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/class/paladin/tyrs-watch",
			pack = "guides",
			title = "Tyr's Watch and {spell:7328} (Forsaken)",
