			written = { ["At 4 {npc:244808} sends you after a {npc:246143} who fled into the hills west of the church, just south of the bat cave. Talk to her to offer aid: she turns on you, and you have to put her down (level 3, easy)."] = "At 4 Aramis sends you after a Frightened Paladin who fled into the hills west of the church, just south of the bat cave. Talk to her to offer aid: she turns on you, and you have to put her down (level 3, easy).", ["Back to {area:16602}, across the whole glades: Billmuth downstairs takes the plans, then {npc:246378}, back upstairs in the keep, teaches you {spell:7328}."] = "Back to Bandarion Keep, across the whole glades: Billmuth downstairs takes the plans, then Danitha, back upstairs in the keep, teaches you Redemption.", ["Back to {area:16602}. {npc:246378} gives you the {item:6866}; {npc:257655} waits downstairs in the keep. If you lose the symbol, {npc:246378} gives you another."] = "Back to Bandarion Keep. Danitha gives you the Symbol of Life; Deathguard Billmuth waits downstairs in the keep. If you lose the symbol, Danitha gives you another.", ["{npc:246349} gives you a weapon, then sends you round the keep to speak with four of its people: {npc:246389} just south of the gate, {npc:246394}, the lookout, who walks the road south-east of the keep, then {npc:246393} and {npc:246378} inside the keep. Pick the conversation option with each."] = "Breton gives you a weapon, then sends you round the keep to speak with four of its people: Hilda the Breaker just south of the gate, Ander Solliden, the lookout, who walks the road south-east of the keep, then Jorin Croge and Danitha Morr inside the keep. Pick the conversation option with each.", ["{npc:246378} hands you {npc:259431}'s head for Sylvanas: keep it in your bags, it is what you hand in."] = "Danitha hands you Rudolph Gelhardt's head for Sylvanas: keep it in your bags, it is what you hand in.", ["{npc:246378} offers the first Lesson in Divinity at level 12. Bring 10 {item:2589} if you have it: the {zone:1458} asks for it next."] = "Danitha offers the first Lesson in Divinity at level 12. Bring 10 Linen Cloth if you have it: the Undercity asks for it next.", ["{npc:246389} and {npc:259190} wait at the forest's edge south of the gate."] = "Hilda and Ephram wait at the forest's edge south of the gate.", ["{npc:246389}'s bones"] = "Hilda's bones", ["{npc:257648} needs 10 {item:2589}. Humanoids drop it: the Scarlet Zealots and Friars of the glades about three kills in ten. The Undercity Auction House sells it too."] = "Tanis needs 10 Linen Cloth. Humanoids drop it: the Scarlet Zealots and Friars of the glades about three kills in ten. The Undercity Auction House sells it too.", ["{npc:259190} waits at the forest's edge south of the gate, a few steps west of {npc:246389}."] = "Ephram waits at the forest's edge south of the gate, a few steps west of Hilda.", ["{npc:259190}'s crystal"] = "Ephram's crystal" },
			stepCount = 23,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:244808}\",\n\t\tnote = \"{npc:1569} gives you a {item:282423} after {quest:364}: read it, then bring it to {npc:244808} by the church. He asks you to heal five {npc:259377} lying around {area:154}. {spell:635} hurts a Forsaken paladin a little each time: watch your health.\",\n\t\twhen = { { k = \"level\", op = \"<\", n = 9 } },\n\t\tgoals = {\n\t\t\t{ t = \"accept\", quest = 98601, title = \"A Difficult Path\", npc = 1569, npcName = \"Shadow Priest Sarvis\", minLevel = 1, qlvl = 1, pre = { 364 }, preTitles = { [364] = \"The Mindless Ones\" }, map = 1420, x = 30.79, y = 66.21, z = 97.8 },\n\t\t\t{ t = \"turnin\", quest = 98601, title = \"A Difficult Path\", npc = 244808, npcName = \"Aramis Hammerhand\", map = 1420, x = 30.99, y = 66.33, z = 97 },\n\t\t\t{ t = \"level\", level = 2 },\n\t\t\t{ t = \"accept\", quest = 90902, title = \"Rediscovering the Light\", npc = 244808, npcName = \"Aramis Hammerhand\", minLevel = 2, qlvl = 2, pre = { 364 }, preTitles = { [364] = \"The Mindless Ones\" }, map = 1420, x = 30.99, y = 66.33, z = 97 },\n\t\t\t{ t = \"complete\", quest = 90902, title = \"Rediscovering the Light\", map = 1420, x = 31.6, y = 65.8, f = \"e\", note = \"Heal 5 {npc:259377} with {spell:635}\", objs = { { text = \"Heal 5 Injured Deathguard\", count = 1 } } },\n\t\t\t{ t = \"turnin\", quest = 90902, title = \"Rediscovering the Light\", npc = 244808, npcName = \"Aramis Hammerhand\", map = 1420, x = 30.99, y = 66.33, z = 97 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:91208}\",\n\t\tnote = \"At 4 {npc:244808} sends you after a {npc:246143} who fled into the hills west of the church, just south of the bat cave. Talk to her to offer aid: she turns on you, and you have to put her down (level 3, easy).\",\n\t\twhen = { { k = \"level\", op = \"<\", n = 9 } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 4 },\n\t\t\t{ t = \"accept\", quest = 91208, title = \"Coming to Terms\", npc = 244808, npcName = \"Aramis Hammerhand\", minLevel = 4, qlvl = 4, pre = { 90902 }, preTitles = { [90902] = \"Rediscovering the Light\" }, map = 1420, x = 30.99, y = 66.33, z = 97 },\n\t\t\t{ t = \"accept\", quest = 91209, title = \"Continue Your Training\", npc = 244808, npcName = \"Aramis Hammerhand\", minLevel = 4, qlvl = 4, pre = { 90902 }, preTitles = { [90902] = \"Rediscovering the Light\" }, map = 1420, x = 30.99, y = 66.33, z = 97 },\n\t\t\t{ t = \"kill\", quest = 91208, title = \"Coming to Terms\", target = \"Frightened Paladin\", npc = 246143, count = 1, oi = 1, map = 1420, x = 27.66, y = 63.88, z = 118.8, note = \"Talk to the {npc:246143}, then defeat her\" },\n\t\t\t{ t = \"turnin\", quest = 91208, title = \"Coming to Terms\", npc = 244808, npcName = \"Aramis Hammerhand\", map = 1420, x = 30.99, y = 66.33, z = 97 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:246152}\",\n\t\tnote = \"Follow the road east out of {area:154} to {area:159}. {npc:246152}, the paladin trainer, stands in town; she trains you from here on.\",\n\t\twhen = { { k = \"level\", op = \"<\", n = 9 } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 91209, title = \"Continue Your Training\", npc = 246152, npcName = \"Shari Stilwell\", map = 1420, x = 60.15, y = 52.6, z = 35.2, note = \"{npc:246152}, {area:159}\" },\n\t\t\t{ t = \"train\", class = true, zone = 1420, candidates = { { npc = 246152, npcName = \"Shari Stilwell\", map = 1420, x = 60.15, y = 52.6, z = 35.2, faction = \"H\", classes = { \"PALADIN\" } }, { npc = 260093, npcName = \"Garen Largo\", map = 1458, x = 47.36, y = 15.24, z = -57.1, faction = \"H\", classes = { \"PALADIN\" } }, { npc = 244808, npcName = \"Aramis Hammerhand\", map = 1420, x = 30.99, y = 66.33, z = 97, faction = \"H\", classes = { \"PALADIN\" } }, { npc = 246389, npcName = \"Hilda the Breaker\", map = 1420, x = 21.84, y = 47.15, z = 134.5, faction = \"H\", classes = { \"PALADIN\" } }, { npc = 246344, npcName = \"Alodan the Hopeful\", map = 1456, x = 25.08, y = 14.54, z = 97.4, faction = \"H\", classes = { \"PALADIN\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:91282}\",\n\t\tnote = \"At 8 {npc:246152} in {area:159} sends you to the order's keep on the west coast. {quest:91317} in {area:16881} and the crypt under it hit hard at 8-9: come at 10 or later.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 8 },\n\t\t\t{ t = \"accept\", quest = 91282, title = \"A Second Home\", npc = 246152, npcName = \"Shari Stilwell\", minLevel = 8, qlvl = 11, map = 1420, x = 60.15, y = 52.6, z = 35.2, note = \"{npc:246152}, {area:159}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{area:16602}\",\n\t\tnote = \"{area:16602} stands on the bluffs north-west of the {area:156} (the road west starts near 29,46). {npc:246349} waits at the gate. {npc:246389}, the keep's trainer, and {npc:259190}, its stable master, stand at the forest's edge just south of him. They only have work for you from level 10 and after {quest:96896} from Leonid at the keep, the end of {npc:267009}'s chain that starts south-east of {area:159}; take their quests when you see them.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 11 },\n\t\t\t{ t = \"turnin\", quest = 91282, title = \"A Second Home\", npc = 246349, npcName = \"Breton Samuels\", map = 1420, x = 21.8, y = 45.37, z = 136.9 },\n\t\t\t{ t = \"accept\", quest = 91285, title = \"Murlocs at the Gates\", npc = 246349, npcName = \"Breton Samuels\", minLevel = 7, qlvl = 11, map = 1420, x = 21.8, y = 45.37, z = 136.9 },\n\t\t\t{ t = \"accept\", quest = 99152, title = \"As Above, So Below\", npc = 246389, npcName = \"Hilda the Breaker\", minLevel = 10, qlvl = 12, pre = { 96896 }, preTitles = { [96896] = \"A Righteous Cause\" }, map = 1420, x = 21.84, y = 47.15, z = 134.5, optional = true, note = \"{npc:246389}: {quest:99152}\" },\n\t\t\t{ t = \"accept\", quest = 99153, title = \"The One That Got Away\", npc = 259190, npcName = \"Ephram Barbaro\", minLevel = 10, qlvl = 12, pre = { 96896 }, preTitles = { [96896] = \"A Righteous Cause\" }, map = 1420, x = 20.11, y 