			stepCount = 8,
			stepsSrc = "local candidateRecords = {\n\t{ npc = 3706, npcName = \"Tai'jin\", map = 1411, x = 54.17, y = 42.97, z = 10.6, faction = \"H\", classes = { \"PRIEST\" } },\n\t{ npc = 3707, npcName = \"Ken'jai\", map = 1411, x = 42.36, y = 68.84, z = 38.3, faction = \"H\", classes = { \"PRIEST\" } },\n\t{ npc = 3044, npcName = \"Miles Welsh\", map = 1456, x = 25.41, y = 15.63, z = 97.9, faction = \"H\", classes = { \"PRIEST\" } },\n\t{ npc = 2123, npcName = \"Dark Cleric Duesten\", map = 1420, x = 31.03, y = 66.11, z = 97, faction = \"H\", classes = { \"PRIEST\" } },\n\t{ npc = 2129, npcName = \"Dark Cleric Beryl\", map = 1420, x = 61.57, y = 52.07, z = 41.2, faction = \"H\", classes = { \"PRIEST\" } },\n}\nreturn {\n\t{\n\t\ttitle = \"{quest:5649}\",\n\t\tnote = \"At 5, {npc:3707}, the priest trainer in the Den in the middle of the {area:363}, sends you to {npc:3706} in {area:362}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank.\",\n\t\tonly = { races = { \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 5 },\n\t\t\t{ t = \"accept\", quest = 5649, title = \"In Favor of Spirituality\", npc = 3707, npcName = \"Ken'jai\", minLevel = 5, qlvl = 4, closedBy = { 5648 }, endNpcs = { 3706 }, xp = 90, preTitles = { [5648] = \"Garments of Spirituality\" }, map = 1411, x = 42.36, y = 68.84, z = 38.3 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:3706}\",\n\t\tnote = \"Follow the road out of the {area:363} north-east to {area:362}. {npc:3706} is inside the barracks, the first building on the right as you come into town.\",\n\t\tonly = { races = { \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 5649, title = \"In Favor of Spirituality\", npc = 3706, npcName = \"Tai'jin\", map = 1411, x = 54.17, y = 42.97, z = 10.6 },\n\t\t\t{ t = \"accept\", quest = 5648, title = \"Garments of Spirituality\", npc = 3706, npcName = \"Tai'jin\", minLevel = 5, qlvl = 4, crumbs = { 5649 }, preTitles = { [5649] = \"In Favor of Spirituality\" }, map = 1411, x = 54.17, y = 42.97, z = 10.6 },\n\t\t\t{ t = \"train\", class = true, zone = 1411, note = \"{spell:613} (Rank 2), if {npc:3707} did not teach it yet\", candidates = { candidateRecords[1], candidateRecords[2], { npc = 6014, npcName = \"X'yera\", map = 1454, x = 36.01, y = 87.73, z = 61.4, f = \"e\", faction = \"H\", classes = { \"PRIEST\" } }, candidateRecords[3], candidateRecords[4], candidateRecords[5], { npc = 4606, npcName = \"Aelthalyste\", map = 1458, x = 49.03, y = 18.27, z = -57.1, faction = \"H\", classes = { \"PRIEST\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:12430}\",\n\t\tnote = \"{npc:12430} kneels behind a group of rocks just off the road, a short walk south of {area:362}. Cast {spell:613} (Rank 2) on her first, then {spell:1243}. Rank 1 of {spell:613} does not count; drag Rank 2 onto your bar from the spellbook. She leaves once both land and is back in about 5 minutes.\",\n\t\tonly = { races = { \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"kill\", quest = 5648, title = \"Garments of Spirituality\", target = \"Grunt Kor'ja\", npc = 12430, count = 1, oi = 1, text = \"Heal and fortify {npc:12430}\", map = 1411, x = 53.1, y = 46.46, z = 14.5, f = \"e\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:3706}\",\n\t\tnote = \"Back in the {area:362} barracks: {npc:3706} gives you the {item:16606}.\",\n\t\tonly = { races = { \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 5648, title = \"Garments of Spirituality\", npc = 3706, npcName = \"Tai'jin\", map = 1411, x = 54.17, y = 42.97, z = 10.6, rewards = { items = { { item = 16606, itemName = \"Juju Hex Robes\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:5651}\",\n\t\tnote = \"At 5, {npc:2123}, the priest trainer in the chapel of {area:154}, sends you to {npc:2129} in {area:159}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 5 },\n\t\t\t{ t = \"accept\", quest = 5651, title = \"In Favor of Darkness\", npc = 2123, npcName = \"Dark Cleric Duesten\", minLevel = 5, qlvl = 4, closedBy = { 5650 }, endNpcs = { 2129 }, xp = 90, preTitles = { [5650] = \"Garments of Darkness\" }, map = 1420, x = 31.03, y = 66.11, z = 97 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:2129}\",\n\t\tnote = \"Follow the road east out of {area:154} to {area:159}. {npc:2129} is upstairs in the inn, {area:2119}.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 5651, title = \"In Favor of Darkness\", npc = 2129, npcName = \"Dark Cleric Beryl\", map = 1420, x = 61.57, y = 52.07, z = 41.2 },\n\t\t\t{ t = \"accept\", quest = 5650, title = \"Garments of Darkness\", npc = 2129, npcName = \"Dark Cleric Beryl\", minLevel = 5, qlvl = 4, crumbs = { 5651 }, preTitles = { [5651] = \"In Favor of Darkness\" }, map = 1420, x = 61.57, y = 52.07, z = 41.2 },\n\t\t\t{ t = \"train\", class = true, zone = 1420, note = \"{spell:613} (Rank 2), if Duesten did not teach it yet\", candidates = { candidateRecords[5], { npc = 4607, npcName = \"Father Lankester\", map = 1458, x = 49.56, y = 15.82, z = -57.1, faction = \"H\", classes = { \"PRIEST\" } }, candidateRecords[4], candidateRecords[1], candidateRecords[2], { npc = 5994, npcName = \"Zayus\", map = 1454, x = 35.72, y = 86.9, z = 61.4, f = \"e\", faction = \"H\", classes = { \"PRIEST\" } }, candidateRecords[3] } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:12428}\",\n\t\tnote = \"{npc:12428} kneels, half-dead, beside the north gate of {area:159}'s graveyard, a short walk north of the inn. Cast {spell:613} (Rank 2) on him first, then {spell:1243}: Fortitude first does not count, nor does Rank 1 of {spell:613}. If an addon gets in the way, cast both from the spellbook.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"kill\", quest = 5650, title = \"Garments of Darkness\", target = \"Deathguard Kel\", npc = 12428, count = 1, oi = 1, text = \"Heal and fortify {npc:12428}\", map = 1420, x = 59.18, y = 46.5, z = 33.4, f = \"e\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:2129}\",\n\t\tnote = \"Back upstairs in the {area:159} inn: Beryl gives you the {item:16607}.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 5650, title = \"Garments of Darkness\", npc = 2129, npcName = \"Dark Cleric Beryl\", map = 1420, x = 61.57, y = 52.07, z = 41.2, rewards = { items = { { item = 16607, itemName = \"Acolyte's Sacrificial Robes\" } } } },\n\t\t},\n\t},\n}",
		})
