			stepsSrc = "return {\n\t{\n\t\ttitle = \"{spell:2652}: {npc:3706}\",\n\t\tnote = \"At 10 in {zone:1411}, {npc:3706}, the priest trainer inside the barracks of {area:362}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}.\",\n\t\twhen = { { k = \"zone\", name = \"Durotar\", area = 14 }, { k = \"onquest\", neg = true, q = { 5658, 5660, 5661, 5662, 5663 } } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"talk\", npc = 3706, npcName = \"Tai'jin\", map = 1411, x = 54.17, y = 42.97, z = 10.6, note = \"{npc:3706}: take his {spell:2652} letter\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{spell:2652}: {npc:6018}\",\n\t\tnote = \"At 10 in {zone:1454}, {npc:6018} in the {object:172961} hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}. The zeppelin to {zone:1420} leaves from the tower outside {zone:1454}'s front gate.\",\n\t\twhen = { { k = \"zone\", name = \"Orgrimmar\", area = 1637 }, { k = \"onquest\", neg = true, q = { 5658, 5660, 5661, 5662, 5663 } } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"talk\", npc = 6018, npcName = \"Ur'kyo\", map = 1454, x = 35.53, y = 87.55, z = 44.1, spotsPacked = \"35.5,87.6,44.1,15,2\", note = \"{npc:6018}: take his {spell:2652} letter\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{spell:2652}: {npc:11407}\",\n\t\tnote = \"At 10 in {zone:1412}, {npc:11407}, just south-west of {area:222}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}.\",\n\t\twhen = { { k = \"zone\", name = \"Mulgore\", area = 215 }, { k = \"onquest\", neg = true, q = { 5658, 5660, 5661, 5662, 5663 } } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"talk\", npc = 11407, npcName = \"Var'jun\", map = 1412, x = 46.2, y = 62.27, z = -9.3, note = \"{npc:11407}: take the {spell:2652} letter\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{spell:2652}: {npc:3044}\",\n\t\tnote = \"At 10 in {zone:1456}, {npc:3044}, the priest trainer in the cave under {area:1640}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}.\",\n\t\twhen = { { k = \"zone\", name = \"Thunder Bluff\", area = 1638 }, { k = \"onquest\", neg = true, q = { 5658, 5660, 5661, 5662, 5663 } } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"talk\", npc = 3044, npcName = \"Miles Welsh\", map = 1456, x = 25.45, y = 15.39, z = 97.9, spotsPacked = \"25.4,15.4,97.9,15,2\", note = \"{npc:3044}: take his {spell:2652} letter\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:5658}: {npc:4606}\",\n\t\tnote = \"At 10, go to {npc:4606}, the priest trainer in the {zone:1458}'s {object:36070}: she gives {quest:5658} and takes it back at once. No letter needed. From {area:159}, follow the road south to the ruined city of Lordaeron; the {zone:1458}'s lifts are at the back of the throne room. {quest:5658} strikes the next melee attacker for Shadow damage and lowers its melee attack power for 2 minutes.\",\n\t\twhen = { { k = \"onquest\", neg = true, q = { 5658, 5660, 5661, 5662, 5663 } } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 5658, title = \"Touch of Weakness\", npc = 4606, npcName = \"Aelthalyste\", minLevel = 10, qlvl = 10, closedBy = { 5659, 5660, 5661, 5662, 5663 }, endNpcs = { 4606 }, preTitles = { [5659] = \"Touch of Weakness\", [5660] = \"Touch of Weakness\", [5661] = \"Touch of Weakness\", [5662] = \"Touch of Weakness\", [5663] = \"Touch of Weakness\" }, map = 1458, x = 49.08, y = 18.34, z = -57.1, spotsPacked = \"49.1,18.3,-57.1,15,4\" },\n\t\t\t{ t = \"turnin\", quest = 5658, title = \"Touch of Weakness\", npc = 4606, npcName = \"Aelthalyste\", map = 1458, x = 49.03, y = 18.27, z = -57.1, spotsPacked = \"49.1,18.3,-57.1,15,4\", note = \"{npc:4606}: {quest:5658}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:5660}: {npc:3706}'s letter\",\n\t\tnote = \"Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: the zeppelin from the tower outside {zone:1454} lands in {zone:1420}, a short walk from the {zone:1458}.\",\n\t\twhen = { { k = \"onquest\", q = { 5660 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 5660, title = \"Touch of Weakness\", npc = 4606, npcName = \"Aelthalyste\", map = 1458, x = 49.03, y = 18.27, z = -57.1, spotsPacked = \"49.1,18.3,-57.1,15,4\", note = \"{npc:4606}: {quest:5660}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:5661}: {npc:11407}'s letter\",\n\t\tnote = \"Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: travel to {zone:1454} and take the zeppelin to {zone:1420}.\",\n\t\twhen = { { k = \"onquest\", q = { 5661 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 5661, title = \"Touch of Weakness\", npc = 4606, npcName = \"Aelthalyste\", map = 1458, x = 49.03, y = 18.27, z = -57.1, spotsPacked = \"49.1,18.3,-57.1,15,4\", note = \"{npc:4606}: {quest:5661}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:5662}: {npc:6018}'s letter\",\n\t\tnote = \"Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: the zeppelin from the tower outside {zone:1454} lands in {zone:1420}.\",\n\t\twhen = { { k = \"onquest\", q = { 5662 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 5662, title = \"Touch of Weakness\", npc = 4606, npcName = \"Aelthalyste\", map = 1458, x = 49.03, y = 18.27, z = -57.1, spotsPacked = \"49.1,18.3,-57.1,15,4\", note = \"{npc:4606}: {quest:5662}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:5663}: {npc:3044}'s letter\",\n\t\tnote = \"Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: travel to {zone:1454} and take the zeppelin to {zone:1420}.\",\n\t\twhen = { { k = \"onquest\", q = { 5663 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 5663, title = \"Touch of Weakness\", npc = 4606, npcName = \"Aelthalyste\", map = 1458, x = 49.03, y = 18.27, z = -57.1, spotsPacked = \"49.1,18.3,-57.1,15,4\", note = \"{npc:4606}: {quest:5663}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:5644}: {npc:6018}\",\n\t\tnote = \"At 20 in {zone:1454}, {npc:6018} in the {object:1729