			written = { ["{npc:6467} and {npc:2425}"] = "Mennet and Varimathras", ["{npc:6467} sends the ledger on to {npc:2425}, the big demon in the middle of the Hall of the Dark Lady in the {object:36126}, past its elite guards; the way in is the passage off the Apothecarium. If you lose the ledger, take another from {npc:6522}'s bookshelf."] = "Mennet sends the ledger on to Varimathras, the big demon in the middle of the Hall of the Dark Lady in the Royal Quarter, past its elite guards; the way in is the passage off the Apothecarium. If you lose the ledger, take another from Andron's bookshelf." },
			stepCount = 12,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{quest:1859}\",\n\t\tnote = \"At 10 {npc:3170}, the rogue trainer in {area:362}, sends you to {quest:1859} in {zone:1454}. It is only a pointer: an Orc already in {zone:1454} can skip it and take {quest:1963} from {quest:1859} straight away.\",\n\t\tonly = { races = { \"Orc\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 1859, title = \"Therzok\", npc = 3170, npcName = \"Kaplak\", minLevel = 10, qlvl = 10, closedBy = { 1963, 1885 }, endNpcs = { 6446 }, xp = 210, preTitles = { [1885] = \"Mennet Carkad\", [1963] = \"The Shattered Hand\" }, map = 1411, x = 51.89, y = 43.73, z = 17.6 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1963}\",\n\t\tnote = \"{quest:1859} stands in the {object:172960}, the canyon under the {object:172982}. Trolls: take {quest:1963} from him at 10.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 12 },\n\t\t\t{ t = \"turnin\", quest = 1859, title = \"Therzok\", npc = 6446, npcName = \"Therzok\", map = 1454, x = 42.8, y = 53.43, z = 8, only = { races = { \"Orc\" } } },\n\t\t\t{ t = \"accept\", quest = 1963, title = \"The Shattered Hand\", npc = 6446, npcName = \"Therzok\", minLevel = 10, qlvl = 13, crumbs = { 1859 }, preTitles = { [1859] = \"Therzok\" }, map = 1454, x = 42.8, y = 53.43, z = 8 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6494}\",\n\t\tnote = \"{npc:6494} (level 13, not elite) is a troll pirate on the {area:391} south of {area:392}: he walks the fenced hill path between the lower pirate camp by the beached ship and the upper camp by a big tree. Fight him at the foot of the hill, away from the camps. He always drops his satchel and is back 4 1/2 minutes after a death; one satchel per kill, so two rogues need two kills. Hand the satchel in unopened: picking its lock now destroys it and you must kill him again.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 12 },\n\t\t\t{ t = \"collect\", quest = 1963, title = \"The Shattered Hand\", item = 7209, itemName = \"Tazan's Satchel\", count = 1, oi = 1, map = 1413, x = 63.11, y = 44.29, f = \"e\", note = \"{item:7209}: {npc:6494}\", from = \"Tazan\", fromKind = \"npc\", fromId = 6494, fromNpcs = { { npc = 6494, npcName = \"Tazan\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:6446}\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 12 },\n\t\t\t{ t = \"turnin\", quest = 1963, title = \"The Shattered Hand\", npc = 6446, npcName = \"Therzok\", map = 1454, x = 42.8, y = 53.43, z = 8, note = \"{npc:6446}, {object:172960}\" },\n\t\t\t{ t = \"accept\", quest = 1858, title = \"The Shattered Hand\", npc = 6446, npcName = \"Therzok\", minLevel = 10, qlvl = 13, pre = { 1963 }, preTitles = { [1963] = \"The Shattered Hand\" }, map = 1454, x = 42.8, y = 53.43, z = 8 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:7208}\",\n\t\tnote = \"{quest:1859} hands the satchel back: now open it. {npc:6466} (level 12) kneels by the innkeeper in the inn in the {object:172982}; stealth up and pick his pocket for {item:7208} (do not kill him: the key almost never drops). Players often kill him, so you may wait up to 5 minutes for him. Then use the key on {item:7209} in your bags. If you have trained {spell:1804}, you can pick the satchel's lock instead.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 12 },\n\t\t\t{ t = \"collect\", item = 7208, itemName = \"Tazan's Key\", count = 1, text = \"Pick Pocket Gamon for {item:7208}\", map = 1454, x = 54, y = 68.03, z = 15.5, f = \"e\", from = \"Gamon\", fromKind = \"npc\", fromId = 6466, fromNpcs = { { npc = 6466, npcName = \"Gamon\" } } },\n\t\t\t{ t = \"use\", quest = 1858, title = \"The Shattered Hand\", item = 7209, itemName = \"Tazan's Satchel\", oi = 1, map = 1454, x = 54, y = 68, f = \"e\", note = \"{item:7209}, once you have the key\" },\n\t\t\t{ t = \"collect\", quest = 1858, title = \"The Shattered Hand\", item = 7295, itemName = \"Tazan's Logbook\", count = 1, oi = 1, map = 1454, x = 54, y = 68, f = \"e\", note = \"{item:7295}, from the satchel\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6446}'s reward\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1858, title = \"The Shattered Hand\", npc = 6446, npcName = \"Therzok\", map = 1454, x = 42.8, y = 53.43, z = 8, note = \"{npc:6446}, {object:172960}\", rewards = { items = { { item = 7298, itemName = \"Blade of Cunning\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1885}\",\n\t\tnote = \"At 10 {npc:2130}, the rogue trainer upstairs in the {area:2119} in {area:159}, sends you to {quest:1885} in the {zone:1458}.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 1885, title = \"Mennet Carkad\", npc = 2130, npcName = \"Marion Call\", minLevel = 10, qlvl = 10, closedBy = { 1886, 1859 }, endNpcs = { 6467 }, xp = 210, preTitles = { [1859] = \"Therzok\", [1886] = \"The Deathstalkers\" }, map = 1420, x = 61.69, y = 52.01, z = 41.2 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {object:36073}\",\n\t\tnote = \"{quest:1885} stands in the {object:36073}.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 12 },\n\t\t\t{ t = \"turnin\", quest = 1885, title = \"Mennet Carkad\", npc = 6467, npcName = \"Mennet Carkad\", map = 1458, x = 83.26, y = 68.93, z = -62.2, spotsPacked = \"83.3,68.9,-62.2,15,6\" },\n\t\t\t{ t = \"accept\", quest = 1886, title = \"The Deathstalkers\", npc = 6467, npcName = \"Mennet Carkad\", minLevel = 10, qlvl = 13, crumbs = { 1885 }, preTitles = { [1885] = \"Mennet Carkad\" }, map = 1458, x = 83.2, y = 69.03, z = -62.2, spotsPacked = \"83.3,68.9,-62.2,15,6\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6497}\",\n\t\tnote = \"{npc:6497} (level 13) walks the road between the {area:228} and the {zone:1458}, north of the {area:228}. He looks like a friendly traveller with no quest mark. Talk to him and pick both of his answers: he turns hostile. Kill him for the letter (it always drops). Fight him away from guards, who can take the kill and leave no loot; only one rogue per kill gets the letter. He is back 5 minutes after a death.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 12 },\n\t\t\t{ t = \"collect\", quest = 1886, title = \"The Deathstalkers\", item = 7231, itemName = \"Astor's Letter of Introduction\", count = 1, oi = 1, map = 1421, x = 51.23, y = 28.41, spotsPacked = \"50.6,25.6,,73,3;53.1,20.2,,51,2;56.5,13.9,,51,2;49.7,33.1,,51,1;50.8,36.5,,51,2;47.9,39.4,,51,3\", spread = true, lvl = 13, note = \"{item:7231}: {npc:6497}\", from = \"Astor Hadren\", fromKind = \"npc\", fromFaction = \"H\", fromId = 6497, fromNpcs = { { npc = 6497, npcName = \"Astor Hadren\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:6467}\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1886, title = \"The Deathstalkers\", npc = 6467, npcName = \"Mennet Carkad\", map = 1458, x = 83.26, y = 68.93, z = -62.2, spotsPacked = \"83.3,68.9,-62.2,15,6\", note = \"{npc:6467}, {object:36073}\" },\n\t\t\t{ t = \"accept\", quest = 1898, title = \"The Deathstalkers\", npc = 6467, npcName = \"Mennet Carkad\", minLevel = 10, qlvl = 13, pre = { 1886 }, preTitles = { [1886] = \"The Deathstalkers\" }, map = 1458, x = 83.2, y = 69.03, z = -62.2, spotsPacked = \"83.3,68.9,-62.2,15,6\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6522}\",\n\t\tnote = \"{npc:6522} is in the Apothecarium, in its biggest room, where two huge guards watch a small bridge. His ledger is on the bookshelf in the back room behind him, not the shelf on the wall next to him.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 12 },\n\t\t\t{ t = \"turnin\", quest = 1898, title = \"The Deathstalkers\", npc = 6522, npcName = \"Andron Gant\", map = 1458, x = 55.16, y = 76.18, z = -66, spotsPacked = \"54.8,76,-66,15,4\" },\n\t\t\t{ t = \"accept\", quest = 1899, title = \"The Deathstalkers\", npc = 6522, npcName = \"Andron Gant\", minLevel = 10, qlvl = 13, pre = { 1898 }, preTitles = { [1898] = \"The Deathstalkers\" }, map = 1458, x = 55.16, y = 76.18, z = -66, spotsPacked = \"54.8,76,-66,15,4\" },\n\t\t\t{ t = \"collect\", quest = 1899, title = \"The Deathstalkers\", item = 7294, itemName = \"Andron's Ledger\", count = 1, oi = 1, map = 1458, x = 55.15, y = 76.49, z = -66, f = \"e\", spotsPacked = \"55.3,76.6,-66,15,2\", note = \"{item:7294}: {object:103600}\", from = \"Andron's Bookshelf\", fromKind = \"object\", fromId = 103600 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6467} and {npc:2425}\",\n\t\tnote = \"{npc:6467} sends the ledger on to {npc:2425}, the big demon in the middle of the Hall of the Dark Lady in the {object:36126}, past its elite guards; the way in is the passage off the Apothecarium. If you lose the ledger, take another from {npc:6522}'s bookshelf.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1899, title = \"The Deathstalkers\", npc = 6467, npcName = \"Mennet Carkad\", map = 1458, x = 82.98, y = 69.27, z = -62.2, spotsPacked = \"83.3,68.9,-62.2,15,6\", note = \"{npc:6467}, {object:36073}\" },\n\t\t\t{ t = \"accept\", quest = 1978, title = \"The Deathstalkers\", npc = 6467, npcName = \"Mennet Carkad\", minLevel = 10, qlvl = 13, pre = { 1899 }, preTitles = { [1899] = \"The Deathstalkers\" }, map = 1458, x = 82.98, y = 69.27, z = -62.2, spotsPacked = \"83.3,68.9,-62.2,15,6\" },\n\t\t\t{ t = \"turnin\", quest = 1978, title = \"The Deathstalkers\", npc = 2425, npcName = \"Varimathras\", map = 1458, x = 56.57, y = 91.7, z = -60, spotsPacked = \"56.2,92.2,-60,15,13\", note = \"{npc:2425}, {object:36126}\", rewards = { items = { { item = 7298, itemName = \"Blade of Cunning\" } } } },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

