	local function register()
		Polestar.RegisterGuide({
			id = "forever/class/rogue/plundering-the-plunderers",
			pack = "guides",
			title = "{quest:2381}",
			faction = "Horde",
			classes = { "ROGUE" },
			minLevel = 16,
			maxLevel = 20,
			category = "Class",
			folder = "Rogue",
			keywords = { "Plundering the Plunderers", "Find the Shattered Hand", "To Orgrimmar!", "Shenthul", "Zando'zan", "Wrenix of Ratchet", "Wrenix the Wretched", "Gizmotronic Apparatus", "E.C.A.C.", "Thieves' Tools", "Southsea Treasure", "Polly", "Jewel of the Southsea", "Tide Razor", "Buccaneer's Strongbox", "Thistle Tea", "Fenwick Thatros", "Tools of the Trade", "Ambermill Strongbox", "Dalaran Status Report", "Mennet Carkad", "Rogue", "lockpicking quest" },
			reward = { { item = 7676, itemName = "Thistle Tea" } },
