			zone = 1454,
			zoneName = "Orgrimmar",
			author = "Polestar",
			version = 1,
			names = { ["area:1338"] = "Lordamere Lake", ["area:228"] = "Sepulcher", ["area:233"] = "Ambermill", ["area:362"] = "Razor Hill", ["area:392"] = "Ratchet", ["item:5060"] = "Thieves' Tools", ["item:7306"] = "Fenwick's Head", ["item:7309"] = "Dalaran Status Report", ["item:7676"] = "Thistle Tea", ["item:7968"] = "Southsea Treasure", ["item:7970"] = "E.C.A.C.", ["npc:3170"] = "Kaplak", ["npc:3401"] = "Shenthul", ["npc:6467"] = "Mennet Carkad", ["npc:6566"] = "Estelle Gendry", ["npc:7161"] = "Wrenix the Wretched", ["npc:7166"] = "Wrenix's Gizmotronic Apparatus", ["npc:7168"] = "Polly", ["object:103815"] = "Ambermill Strongbox", ["object:123462"] = "The Jewel of the Southsea", ["object:172960"] = "Cleft of Shadow", ["object:172982"] = "Valley of Strength", ["object:36073"] = "Rogues' Quarter", ["quest:1998"] = "Fenwick Thatros", ["quest:2378"] = "Find the Shattered Hand", ["quest:2379"] = "Zando'zan", ["quest:2380"] = "To Orgrimmar!", ["quest:2381"] = "Plundering the Plunderers", ["spell:1804"] = "Pick Lock", ["zone:1411"] = "Durotar", ["zone:1413"] = "Barrens", ["zone:1421"] = "Silverpine Forest", ["zone:1454"] = "Orgrimmar", ["zone:1458"] = "Undercity" },
			written = { ["Back to {npc:6467}"] = "Back to Mennet", ["Back to {npc:7161}"] = "Back to Wrenix", ["Fly or walk to {area:392} on the {zone:1413} coast. {npc:7161} stands in a small shed near the bank, up the hill to the left before the docks. His Gizmotronic Apparatus beside him hands out what the job needs: take an {item:7970} and {item:5060} ({spell:1804} does not work without the tools in your bags)."] = "Fly or walk to Ratchet on the Barrens coast. Wrenix stands in a small shed near the bank, up the hill to the left before the docks. His Gizmotronic Apparatus beside him hands out what the job needs: take an E.C.A.C. and Thieves' Tools (Pick Lock does not work without the tools in your bags)." },
			stepCount = 10,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{quest:2380}\",\n\t\tnote = \"At 16 {npc:3170}, the rogue trainer in {area:362}, sends you to {npc:3401} in {zone:1454}.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 16 },\n\t\t\t{ t = \"accept\", quest = 2380, title = \"To Orgrimmar!\", npc = 3170, npcName = \"Kaplak\", minLevel = 16, qlvl = 16, closedBy = { 2378 }, endNpcs = { 3401 }, xp = 120, preTitles = { [2378] = \"Find the Shattered Hand\" }, map = 1411, x = 51.89, y = 43.73, z = 17.6 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:2378}\",\n\t\tnote = \"At 16 {npc:6467} in the {object:36073} sends you to {npc:3401} in {zone:1454}. Take {quest:1998} from him too; it is done in {zone:1421} at the end of this guide.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 16 },\n\t\t\t{ t = \"accept\", quest = 2378, title = \"Find the Shattered Hand\", npc = 6467, npcName = \"Mennet Carkad\", minLevel = 16, qlvl = 16, closedBy = { 2380 }, endNpcs = { 3401 }, xp = 120, preTitles = { [2380] = \"To Orgrimmar!\" }, map = 1458, x = 83.26, y = 68.93, z = -62.2, spotsPacked = \"83.3,68.9,-62.2,15,6\" },\n\t\t\t{ t = \"accept\", quest = 1998, title = \"Fenwick Thatros\", npc = 6467, npcName = \"Mennet Carkad\", minLevel = 16, qlvl = 16, map = 1458, x = 83.2, y = 69.03, z = -62.2, spotsPacked = \"83.3,68.9,-62.2,15,6\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:3401} and {quest:2379}\",\n\t\tnote = \"Undead take the zeppelin from the towers outside the {zone:1458} to {zone:1411}. {npc:3401} and {quest:2379} stand in the {object:172960}, the canyon under the {object:172982}. Train {spell:1804} from {npc:3401} (or any rogue trainer) now if you lack it: this job is a lockpicking test.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2380, title = \"To Orgrimmar!\", npc = 3401, npcName = \"Shenthul\", map = 1454, x = 43.04, y = 53.52, z = 7.8, spotsPacked = \"43,53.5,7.8,15,3\", only = { races = { \"Orc\", \"Troll\", \"Skyborne\" } } },\n\t\t\t{ t = \"turnin\", quest = 2378, title = \"Find the Shattered Hand\", npc = 3401, npcName = \"Shenthul\", map = 1454, x = 43.02, y = 53.32, z = 7.8, spotsPacked = \"43,53.5,7.8,15,3\", only = { races = { \"Scourge\" } } },\n\t\t\t{ t = \"accept\", quest = 2379, title = \"Zando'zan\", npc = 3401, npcName = \"Shenthul\", minLevel = 16, qlvl = 16, map = 1454, x = 43.02, y = 53.32, z = 7.8, spotsPacked = \"43,53.5,7.8,15,3\" },\n\t\t\t{ t = \"turnin\", quest = 2379, title = \"Zando'zan\", npc = 3402, npcName = \"Zando'zan\", map = 1454, x = 43, y = 52.94, z = 7.6, spotsPacked = \"42.9,53.1,7.6,15,2\" },\n\t\t\t{ t = \"accept\", quest = 2382, title = \"Wrenix of Ratchet\", npc = 3402, npcName = \"Zando'zan\", minLevel = 16, qlvl = 16, pre = { 2379 }, preTitles = { [2379] = \"Zando'zan\" }, map = 1454, x = 43, y = 52.94, z = 7.6, spotsPacked = \"42.9,53.1,7.6,15,2\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:7161}\",\n\t\tnote = \"Fly or walk to {area:392} on the {zone:1413} coast. {npc:7161} stands in a small shed near the bank, up the hill to the left before the docks. His Gizmotronic Apparatus beside him hands out what the job needs: take an {item:7970} and {item:5060} ({spell:1804} does not work without the tools in your bags).\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 17 },\n\t\t\t{ t = \"getfp\", npc = 16227, npcName = \"Bragok\", location = \"Ratchet\", node = 80, area = 392, map = 1413, x = 63.04, y = 37.13, z = 11.8, optional = true },\n\t\t\t{ t = \"turnin\", quest = 2382, title = \"Wrenix of Ratchet\", npc = 7161, npcName = \"Wrenix the Wretched\", map = 1413, x = 63.03, y = 36.35, z = 18 },\n\t\t\t{ t = \"accept\", quest = 2381, title = \"Plundering the Plunderers\", npc = 7161, npcName = \"Wrenix the Wretched\", minLevel = 16, qlvl = 18, pre = { 2382 }, preTitles = { [2382] = \"Wrenix of Ratchet\" }, map = 1413, x = 63.03, y = 36.35, z = 18 },\n\t\t\t{ t = \"buy\", npc = 7166, npcName = \"Wrenix's Gizmotronic Apparatus\", item = 7970, itemName = \"E.C.A.C.\", count = 1, map = 1413, x = 63.08, y = 36.34, z = 17.5, note = \"{item:7970}: {npc:7166}\" },\n\t\t\t{ t = \"buy\", npc = 7166, npcName = \"Wrenix's Gizmotronic Apparatus\", item = 5060, itemName = \"Thieves' Tools\", count = 1, map = 1413, x = 63.08, y = 36.34, z = 17.5 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:7968}\",\n\t\tnote = \"Follow the coast south from {area:392} to the first beached pirate ship, the Tide Razor, and climb aboard up its bow. On the middle deck the Buccaneer's Strongboxes come back fast: pick them until your Lockpicking is about 30 (a few are trapped with a frost nova or turn you into a rat; picking still works as a rat). Keep picking while they still give skill: the poisons job at 20 ends at a lockbox that needs about 75, and these boxes are the closest practice. Then go down to the bottom hold and pick the lock of {object:123462}: it is empty, but opening it calls a giant level 50 {npc:7168} into the next room. Stay stealthed, put the {item:7970} on your action bar, target {npc:7168} and use it: the parrot shrinks to level 18. Kill it for the {item:7968}.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 18 },\n\t\t\t{ t = \"collect\", quest = 2381, title = \"Plundering the Plunderers\", item = 7968, itemName = \"Southsea Treasure\", count = 1, oi = 1, map = 1413, x = 64.78, y = 45.5, f = \"e\", note = \"{item:7968}: {npc:7168}, after the {item:7970}\", from = \"Polly\", fromKind = \"npc\", fromId = 7168, fromNpcs = { { npc = 7168, npcName = \"Polly\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:7161}\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2381, title = \"Plundering the Plunderers\", npc = 7161, npcName = \"Wrenix the Wretched\", map = 1413, x = 63.03, y = 36.35, z = 18, note = \"{npc:7161}: ten {item:7676}\", rewards = { items = { { item = 7676, itemName = \"Thistle Tea\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1998}\",\n\t\tnote = \"Take the zeppelin from {zone:1454} to the {zone:1458} and head south into Silverpine. {quest:1998} (level 16) stands alone on the old ferry dock on {area:1338}, north-east of the {area:228}. His Uppercut knocks you back, so do not fight him at the dock's edge. He always drops his head and is back 4 1/2 minutes after a death.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1998, title = \"Fenwick Thatros\", item = 7306, itemName = \"Fenwick's Head\", count = 1, oi = 1, map = 1421, x = 59.58, y = 33.94, z = 34.8, f = \"e\", note = \"{item:7306}: {quest:1998}\", from = \"Fenwick Thatros\", fromKind = \"npc\", fromId = 6570, fromNpcs = { { npc = 6570, npcName = \"Fenwick Thatros\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6467}\",\n\t\tnote = \"If you have no {item:5060} left, ask {npc:6566}, the outfitter in the {object:36073}.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 19 },\n\t\t\t{ t = \"turnin\", quest = 1998, title = \"Fenwick Thatros\", npc = 6467, npcName = \"Mennet Carkad\", map = 1458, x = 83.26, y = 68.93, z = -62.2, spotsPacked = \"83.3,68.9,-62.2,15,6\", note = \"{npc:6467}, {object:36073}\" },\n\t\t\t{ t = \"accept\", quest = 1999, title = \"Tools of the Trade\", npc = 6467, npcName = \"Mennet Carkad\", minLevel = 16, qlvl = 20, pre = { 1998 }, preTitles = { [1998] = \"Fenwick Thatros\" }, map = 1458, x = 83.2, y = 69.03, z = -62.2, spotsPacked = \"83.3,68.9,-62.2,15,6\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{area:233}\",\n\t\tnote = \"The Kirin Tor keep their reports in walled {area:233}, in south-east Silverpine. Facing the town hall, take the building on the right: the {object:103815} is in a corner room upstairs (any Lockpicking opens it; the {item:5060} must be in your bags). Three casters of level 19-20 guard that floor and see through stealth, one walking in and out of the strongbox room: time it or fight them one at a time.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 20 },\n\t\t\t{ t = \"collect\", quest = 1999, title = \"Tools of the Trade\", item = 7309, itemName = \"Dalaran Status Report\", count = 1, oi = 1, map = 1421, x = 63.71, y = 65.24, z = 69.5, f = \"e\", note = \"{item:7309}: {object:103815}\", from = \"Ambermill Strongbox\", fromKind = \"object\", fromId = 103815 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:6467}\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1999, title = \"Tools of the Trade\", npc = 6467, npcName = \"Mennet Carkad\", map = 1458, x = 83.26, y = 68.93, z = -62.2, spotsPacked = \"83.3,68.9,-62.2,15,6\", note = \"{npc:6467}, {object:36073}\" },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

-- Source: forever/class/rogue/poisons-horde.guide
do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/class/rogue/poisons-horde",
			pack = "guides",
			title = "Poisons (Horde)",
