			reward = { { spell = 2842, spellName = "Poisons" }, { item = 18160, itemName = "Recipe: Thistle Tea" }, { item = 8066, itemName = "Fizzule's Whistle" }, { item = 8095, itemName = "Hinott's Oil" } },
			why = "Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it.",
			zone = 1454,
			zoneName = "Orgrimmar",
			author = "Polestar",
			version = 1,
			group = true,
			names = { ["area:263"] = "Cleft", ["area:272"] = "Tarren Mill", ["area:287"] = "Hillsbrad", ["area:382"] = "Sludge Fen", ["area:392"] = "Ratchet", ["item:18160"] = "Recipe: Thistle Tea", ["item:2928"] = "Dust of Decay", ["item:3371"] = "Empty Vial", ["item:5060"] = "Thieves' Tools", ["item:7676"] = "Thistle Tea", ["item:8051"] = "Flare Gun", ["item:8066"] = "Fizzule's Whistle", ["item:8072"] = "Silixiz's Tower Key", ["item:8073"] = "Cache of Zanzil's Altered Mixture", ["item:8074"] = "Gallywix's Head", ["item:8095"] = "Hinott's Oil", ["npc:2216"] = "Apothecary Lydon", ["npc:2391"] = "Serge Hinott", ["npc:3401"] = "Shenthul", ["npc:7233"] = "Taskmaster Fizzule", ["npc:7287"] = "Foreman Silixiz", ["npc:7288"] = "Grand Foreman Puzik Gallywix", ["npc:7310"] = "Mutated Venture Co. Drone", ["object:129127"] = "Gallywix's Lockbox", ["object:172960"] = "Cleft of Shadow", ["object:172982"] = "Valley of Strength", ["quest:2458"] = "Deep Cover", ["quest:2460"] = "The Shattered Salute", ["spell:1776"] = "Gouge", ["spell:1804"] = "Pick Lock", ["spell:1943"] = "Rupture", ["spell:2098"] = "Eviscerate", ["spell:5277"] = "Evasion", ["spell:8681"] = "Instant Poison", ["spell:921"] = "Pick Pocket", ["spell:9810"] = "Touch of Zanzil", ["zone:1421"] = "Silverpine Forest", ["zone:1454"] = "Orgrimmar", ["zone:1458"] = "Undercity" },
			stepCount = 7,
			groupQuests = { { quest = 2478, title = "Mission: Possible But Not Probable" } },
			stepsSrc = "return {\n\t{\n\t\ttitle = \"Lockpicking practice\",\n\t\tnote = \"{object:129127} at the end of the tower job needs Lockpicking of about 70-75. Train {spell:1804} from Gest or {npc:3401} in the {object:172960} if you lack it, carry {item:5060}, and pick the Buccaneer's Strongboxes on the middle deck of the Tide Razor, the beached pirate ship south of {area:392}: they come back fast. Your cap rises 5 per level.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 20 },\n\t\t\t{ t = \"goto\", text = \"Tide Razor\", map = 1413, x = 64.4, y = 45.4, f = \"e\" },\n\t\t\t{ t = \"task\", text = \"Lockpicking about 75: pick the Buccaneer's Strongboxes on the Tide Razor\", optional = true },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:2460}\",\n\t\tnote = \"{npc:3401} stands in the {object:172960}, the canyon under the {object:172982}. Take the quest and wait: he speaks three lines and salutes you. After his third line, target him and type /salute. If it does not count, abandon the quest and take it again. The tower job ahead is built around Ambush, which needs a dagger: if you have none, Kareth, the blade merchant in the {object:172960}, sells a Jambiya.\",\n\t\tgoals = {\n\t\t\t{ t = \"accept\", quest = 2460, title = \"The Shattered Salute\", npc = 3401, npcName = \"Shenthul\", minLevel = 20, qlvl = 20, map = 1454, x = 43.04, y = 53.52, z = 7.8, spotsPacked = \"43,53.5,7.8,15,3\" },\n\t\t\t{ t = \"complete\", quest = 2460, title = \"The Shattered Salute\", map = 1454, x = 43.05, y = 53.74, f = \"e\", note = \"/salute {npc:3401}\", objs = { { text = \"Shenthul\", count = 1 } } },\n\t\t\t{ t = \"turnin\", quest = 2460, title = \"The Shattered Salute\", npc = 3401, npcName = \"Shenthul\", map = 1454, x = 42.9, y = 53.64, z = 7.8, spotsPacked = \"43,53.5,7.8,15,3\" },\n\t\t\t{ t = \"accept\", quest = 2458, title = \"Deep Cover\", npc = 3401, npcName = \"Shenthul\", minLevel = 20, qlvl = 20, pre = { 2460 }, preTitles = { [2460] = \"The Shattered Salute\" }, map = 1454, x = 42.9, y = 53.64, z = 7.8, spotsPacked = \"43,53.5,7.8,15,3\", note = \"{quest:2458}: keep the {item:8051}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:7233}\",\n\t\tnote = \"Fly to the Crossroads and head north to the Venture Co. tower above the {area:382}. Fizzule stands under a tree east of the tower, outside it, and is hostile until signalled. Target him from about 50 yards and fire the {item:8051} twice, then walk up in front of him and /salute. In any other order he attacks. Lost the {item:8051}? Abandon and retake from {npc:3401}.\",\n\t\tgoals = {\n\t\t\t{ t = \"use\", item = 8051, itemName = \"Flare Gun\", map = 1413, x = 55.4, y = 5.6, f = \"e\", note = \"{item:8051}, twice, at Fizzule\", fromNpcs = { { npc = 7233, npcName = \"Taskmaster Fizzule\" } } },\n\t\t\t{ t = \"turnin\", quest = 2458, title = \"Deep Cover\", npc = 7233, npcName = \"Taskmaster Fizzule\", map = 1413, x = 55.41, y = 5.42, z = 91.8, note = \"{npc:7233}: {item:8066}\", rewards = { items = { { item = 8066, itemName = \"Fizzule's Whistle\" } } } },\n\t\t\t{ t = \"accept\", quest = 2478, title = \"Mission: Possible But Not Probable\", npc = 7233, npcName = \"Taskmaster Fizzule\", minLevel = 20, qlvl = 24, pre = { 2458 }, preTitles = { [2458] = \"Deep Cover\" }, map = 1413, x = 55.41, y = 5.42, z = 91.8 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The Venture Co. tower, with a group\",\n\t\tnote = \"{npc:7288} on the top floor is a level 23 elite: easier at 23 or with a friend. Keep {item:8066} in your bags and use it on him every time you come near, or he turns hostile. First Pick Pocket Silixiz's Tower Key from {npc:7287} (level 22), who walks by the tower: stealth up behind him (killing him does not give it). Then clear the tower floor by floor (everything comes back after 4 1/2 minutes): Mutated Venture Co. Drones (25) on the ground floor, Patrollers on the second, Lookouts on the open third, Gallywix on top, back 10 minutes after a kill. Pick {object:129127} beside him for the cache: it poisons you with the {spell:9810}, which weakens your stealth and agility until {npc:2391} cures it.\",\n\t\twhen = { { k = \"group\", q = 2478 } },\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 2478, title = \"Mission: Possible But Not Probable\", item = 8072, itemName = \"Silixiz's Tower Key\", count = 1, oi = 5, text = \"Pick Pocket Foreman Silixiz for {item:8072}\", map = 1413, x = 54.8, y = 5.97, z = 91.8, f = \"e\", from = \"Foreman Silixiz\", fromKind = \"npc\", fromId = 7287, fromNpcs = { { npc = 7287, npcName = \"Foreman Silixiz\" } } },\n\t\t\t{ t = \"kill\", quest = 2478, title = \"Mission: Possible But Not Probable\", target = \"Mutated Venture Co. Drone\", npc = 7310, count = 2, oi = 1, map = 1413, x = 54.7, y = 5.7, z = 93.3, f = \"e\" },\n\t\t\t{ t = \"kill\", quest = 2478, title = \"Mission: Possible But Not Probable\", target = \"Venture Co. Patroller\", npc = 7308, count = 2, oi = 3, map = 1413, x = 54.66, y = 5.68, z = 107.1, f = \"e\" },\n\t\t\t{ t = \"kill\", quest = 2478, title = \"Mission: Possible But Not Probable\", target = \"Venture Co. Lookout\", npc = 7307, count = 2, oi = 2, map = 1413, x = 54.64, y = 5.77, z = 120.7, f = \"e\" },\n\t\t\t{ t = \"collect\", quest = 2478, title = \"Mission: Possible But Not Probable\", item = 8074, itemName = \"Gallywix's Head\", count = 1, oi = 4, map = 1413, x = 54.75, y = 5.59, z = 141.8, f = \"e\", note = \"{item:8074}: {npc:7288} (elite)\", from = \"Grand Foreman Puzik Gallywix\", fromKind = \"npc\", fromRank = 1, fromId = 7288, fromNpcs = { { npc = 7288, npcName = \"Grand Foreman Puzik Gallywix\" } }, group = { kind = \"elite\", lvl = 23, rank = 1 } },\n\t\t\t{ t = \"collect\", quest = 2478, title = \"Mission: Possible But Not Probable\", item = 8073, itemName = \"Cache of Zanzil's Altered Mixture\", count = 1, oi = 6, map = 1413, x = 54.76, y = 5.56, z = 141.8, f = \"e\", note = \"{item:8073}: {object:129127}\", from = \"Gallywix's Lockbox\", fromKind = \"object\", fromId = 129127, group = { kind = \"elite\", lvl = 23, near = true, rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The Venture Co. tower, solo\",\n\t\tnote = \"Keep {item:8066} in your bags and use it on him every time you come near, or he turns hostile. {npc:7287} (level 22) walks by the tower: hug the wall, stealth up behind him and {spell:921} the key. Killing him does not give it; if his pockets are empty, kill him and wait 4 1/2 minutes for him to come back. Inside, floor by floor (everything comes back after 4 1/2 minutes): the Mutated Venture Co. Drones (level 25) on the ground floor die to one Ambush with a dagger; the Patrollers on the second floor take half their health from a one-point {spell:1943}; the Lookouts on the open third floor from a one-point {spell:2098}. {npc:7288} waits on the top floor: a level 23 elite, back 10 minutes after a kill. Open with Ambush (about half his health), then {spell:1776}, {spell:5277}, a healing potion and {item:7676}; a friend makes it easy. One head per kill. Then pick {object:129127} beside him for the cache: it poisons you with the {spell:9810}, which weakens your stealth and agility until {npc:2391} cures it.\",\n\t\twhen = { { k = \"group\", neg = true, q = 2478 } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 25 },\n\t\t\t{ t = \"collect\", quest = 2478, title = \"Mission: Possible But Not Probable\", item = 8072, itemName = \"Silixiz's Tower Key\", count = 1, oi = 5, text = \"Pick Pocket Foreman Silixiz for {item:8072}\", map = 1413, x = 54.8, y = 5.97, z = 91.8, f = \"e\", from = \"Foreman Silixiz\", fromKind = \"npc\", fromId = 7287, fromNpcs = { { npc = 7287, npcName = \"Foreman Silixiz\" } } },\n\t\t\t{ t = \"kill\", quest = 2478, title = \"Mission: Possible But Not Probable\", target = \"Mutated Venture Co. Drone\", npc = 7310, count = 2, oi = 1, map = 1413, x = 54.7, y = 5.7, z = 93.3, f = \"e\" },\n\t\t\t{ t = \"kill\", quest = 2478, title = \"Mission: Possible But Not Probable\", target = \"Venture Co. Patroller\", npc = 7308, count = 2, oi = 3, map = 1413, x = 54.66, y = 5.68, z = 107.1, f = \"e\" },\n\t\t\t{ t = \"kill\", quest = 2478, title = \"Mission: Possible But Not Probable\", target = \"Venture Co. Lookout\", npc = 7307, count = 2, oi = 2, map = 1413, x = 54.64, y = 5.77, z = 120.7, f = \"e\" },\n\t\t\t{ t = \"collect\", quest = 2478, title = \"Mission: Possible But Not Probable\", item = 8074, itemName = \"Gallywix's Head\", count = 1, oi = 4, map = 1413, x = 54.75, y = 5.59, z = 141.8, f = \"e\", note = \"{item:8074}: {npc:7288} (elite)\", from = \"Grand Foreman Puzik Gallywix\", fromKind = \"npc\", fromRank = 1, fromId = 7288, fromNpcs = { { npc = 7288, npcName = \"Grand Foreman Puzik Gallywix\" } }, group = { kind = \"elite\", lvl = 23, rank = 1 } },\n\t\t\t{ t = \"collect\", quest = 2478, title = \"Mission: Possible But Not Probable\", item = 8073, itemName = \"Cache of Zanzil's Altered Mixture\", count = 1, oi = 6, map = 1413, x = 54.76, y = 5.56, z = 141.8, f = \"e\", note = \"{item:8073}: {object:129127}\", from = \"Gallywix's Lockbox\", fromKind = \"object\", fromId = 129127, group = { kind = \"elite\", lvl = 23, near = true, rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:3401}\",\n\t\tnote = \"Fly back to {zone:1454} ({area:392} or the Crossroads; dying at the tower and taking the spirit healer's way back to the Crossroads is quicker). Keep {item:8072} afterwards. Before you leave the {area:263}, buy {item:2928} and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of {spell:8681} takes one of each.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2478, title = \"Mission: Possible But Not Probable\", npc = 3401, npcName = \"Shenthul\", map = 1454, x = 43.04, y = 53.52, z = 7.8, spotsPacked = \"43,53.5,7.8,15,3\", note = \"{npc:3401}: {item:18160}\", rewards = { items = { { item = 18160, itemName = \"Recipe: Thistle Tea\" } } } },\n\t\t\t{ t = \"accept\", quest = 2479, title = \"Hinott's Assistance\", npc = 3401, npcName = \"Shenthul\", minLevel = 20, qlvl = 26, pre = { 2478 }, preTitles = { [2478] = \"Mission: Possible But Not Probable\" }, map = 1454, x = 43.02, y = 53.32, z = 7.8, spotsPacked = \"43,53.5,7.8,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:2391}\",\n\t\tnote = \"Take the zeppelin from {zone:1454} to the {zone:1458} and follow the road south through {zone:1421} into {area:287}, to {area:272}. {npc:2391} works in the building next to the flight path, beside {npc:2216}, a wagon outside. If you lost the Sample of Zanzil's Mixture, abandon and retake from {npc:3401}. Stay beside him for about a minute while he brews the cure; if it never finishes, abandon and retake from him. Then open Poisons from your spellbook to make {spell:8681} from Rekkul's dust and vials, and use it on your weapon.\",\n\t\tgoals = {\n\t\t\t{ t = \"getfp\", npc = 2389, npcName = \"Zarise\", location = \"Tarren Mill\", node = 13, area = 272, map = 1424, x = 60.1, y = 18.54, z = 58.9, spotsPacked = \"60.1,18.5,58.9,15,2\", optional = true },\n\t\t\t{ t = \"turnin\", quest = 2479, title = \"Hinott's Assistance\", npc = 2391, npcName = \"Serge Hinott\", map = 1424, x = 61.47, y = 19.15, z = 57.6 },\n\t\t\t{ t = \"accept\", quest = 2480, title = \"Hinott's Assistance\", npc = 2391, npcName = \"Serge Hinott\", minLevel = 20, qlvl = 20, pre = { 2479 }, preTitles = { [2479] = \"Hinott's Assistance\" }, map = 1424, x = 61.47, y = 19.15, z = 57.6 },\n\t\t\t{ t = \"complete\", quest = 2480, title = \"Hinott's Assistance\", note = \"Wait for the cure\", objs = { { text = \"Cure Completed\", count = 1 } } },\n\t\t\t{ t = \"turnin\", quest = 2480, title = \"Hinott's Assistance\", npc = 2391, npcName = \"Serge Hinott\", map = 1424, x = 61.47, y = 19.15, z = 57.6, note = \"{npc:2391}: Poisons\", rewards = { items = { { item = 8095, itemName = \"Hinott's Oil\" } } } },\n\t\t\t{ t = \"use\", item = 8095, itemName = \"Hinott's Oil\", map = 1424, x = 61.63, y = 19.19, f = \"e\", optional = true, note = \"{item:8095}: clears the {spell:9810}\" },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

-- Source: forever/class/shaman/call-of-air-horde.guide
do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/class/shaman/call-of-air-horde",
			pack = "guides",
			title = "{quest:1531} and the Tempest's Weapons (Horde)",
			faction = "Horde",
			classes = { "SHAMAN" },
			minLevel = 30,
			maxLevel = 40,
			category = "Class",
			folder = "Shaman",
			keywords = { "Air Totem", "Elemental Aid", "Eyes on the Sky", "Storm", "Earth", "and Fire", "Heed My Call", "The Tempest's Weapons", "Prate Cloudseer", "Rau Cliffrunner", "Bath'rah the Windwatcher", "Alaana Stormwalker", "Razorfen Kraul", "Charlga Razorflank", "Twisted Totem", "Corrupted Totems", "Ravaging Tempest", "Eye of the Tempest", "Lightning's Grasp", "Tidebringer's Claw", "Rage of the Storm", "Elementalist's Guard", "Skyborne", "Shaman", "class quest", "totem", "weapon" },
			collects = { 5178 },
			reward = { { item = 5178, itemName = "Air Totem" }, { item = 280607, itemName = "Lightning's Grasp", choice = true }, { item = 280605, itemName = "Tidebringer's Claw", choice = true }, { item = 280604, itemName = "Rage of the Storm", choice = true }, { item = 280696, itemName = "Elementalist's Guard" } },
			why = "The {item:5178} that lets you place air totems, then a weapon of your choice at 40.",
			zone = 1454,
			zoneName = "Orgrimmar",
			author = "Polestar",
			version = 1,
			group = true,
			names = { ["area:1640"] = "Spirit Rise", ["area:1717"] = "Razorfen Kraul", ["area:2408"] = "Shadowprey Village", ["area:272"] = "Tarren Mill", ["area:338"] = "Angor Fortress", ["area:484"] = "Freewind Post", ["area:496"] = "Brackenwall Village", ["area:75"] = "Stonard", ["item:212792"] = "Eye of the Tempest", ["item:268582"] = "Corrupted Totems", ["item:274044"] = "Twisted Fire Totem", ["item:274045"] = "Twisted Earth Totem", ["item:274046"] = "Twisted Water Totem", ["item:274047"] = "Twisted Air Totem", ["item:274463"] = "Tattered Note", ["item:280604"] = "Rage of the Storm", ["item:280605"] = "Tidebringer's Claw", ["item:280607"] = "Lightning's Grasp", ["item:280696"] = "Elementalist's Guard", ["item:5178"] = "Air Totem", ["npc:216474"] = "Ravaging Tempest", ["npc:256028"] = "The Lost One", ["npc:259119"] = "Alaana Stormwalker", ["npc:3560"] = "Healing Ward", ["npc:4421"] = "Charlga Razorflank", ["npc:4722"] = "Rau Cliffrunner", ["npc:5879"] = "Fire Nova Totem", ["npc:5892"] = "Searn Firewarder", ["npc:5905"] = "Prate Cloudseer", ["npc:5906"] = "Xanis Flameweaver", ["npc:6176"] = "Bath'rah the Windwatcher", ["object:172957"] = "Valley of Wisdom", ["quest:1531"] = "Call of Air", ["quest:1532"] = "Call of Air", ["quest:96136"] = "Call of Air", ["spell:10596"] = "Nature Resistance", ["spell:139"] = "Renew", ["spell:8292"] = "Chain Bolt", ["spell:9654"] = "Jumping Lightning", ["zone:1412"] = "Mulgore", ["zone:1413"] = "Barrens", ["zone:1416"] = "Alterac Mountains", ["zone:1418"] = "Badlands", ["zone:1435"] = "Swamp of Sorrows", ["zone:1441"] = "Thousand Needles", ["zone:1443"] = "Desolace", ["zone:1445"] = "Dustwallow Marsh", ["zone:1454"] = "Orgrimmar", ["zone:1456"] = "Thunder Bluff" },
			written = { ["At 30 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the Air Totem Prate gives. Already carry {npc:5892}'s {quest:1532} from {zone:1454}? It goes to {npc:5905} too: skip {npc:5906}."] = "At 30 Xanis Flameweaver, a shaman trainer on Spirit Rise in Thunder Bluff, sends you to Prate Cloudseer in Thousand Needles. Your level 30 air totems (Grounding, Nature Resistance) need the Air Totem Prate gives. Already carry Searn Firewarder's Call of Air from Orgrimmar? It goes to Prate too: skip Xanis.", ["{npc:5905} hands you the {item:268582}. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it."] = "Prate hands you the Corrupted Totems. Place the Corrupted Totems at the steam pools north-west of Freewind Post to call the corrupted elementals and then the Ravaging Tempest; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The Eye of the Tempest drops about every other kill, and every group member can loot it.", ["{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}; the {item:280696} shield comes with it."] = "Bath'rah camps in the ruins in the east of Alterac Mountains: from Tarren Mill follow the river east of town north into the hills. Pick your weapon: Lightning's Grasp, Tidebringer's Claw or Rage of the Storm; the Elementalist's Guard shield comes with it." },
			stepCount = 19,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:5892}\",\n\t\tnote = \"At 30 {npc:5892} in the {object:172957} sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} she gives.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 30 },\n\t\t\t{ t = \"accept\", quest = 1531, title = \"Call of Air\", npc = 5892, npcName = \"Searn Firewarder\", minLevel = 30, qlvl = 30, closedBy = { 1532, 96136 }, endNpcs = { 5905 }, xp = 2450, preTitles = { [1532] = \"Call of Air\", [96136] = \"Call of Air\" }, map = 1454, x = 38.03, y = 37.55, z = 42.2, spotsPacked = \"38,37.6,42.2,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:259119}\",\n\t\tnote = \"At 30 Skyborne shamans get their own {quest:96136}. {npc:259119} waits where the airship from Zephras Isle lands, in northern {zone:1412} beside {zone:1456}. Your level 30 air totems need the Air Totem Prate Cloudseer gives. If she has nothing for you, head up to {npc:5906} in {zone:1456} (next step): the trainers' {quest:96136} is open to Skyborne and gives the same totem.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 30 },\n\t\t\t{ t = \"accept\", quest = 96136, title = \"Call of Air\", npc = 259119, npcName = \"Alaana Stormwalker\", minLevel = 30, qlvl = 35, closedBy = { 1531, 1532 }, endNpcs = { 5905 }, xp = 2750, preTitles = { [1531] = \"Call of Air\", [1532] = \"Call of Air\" }, map = 1412, x = 33.3, y = 22.47, z = 187.2, optional = true },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5906}\",\n\t\tnote = \"At 30 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the Air Totem Prate gives. Already carry {npc:5892}'s {quest:1532} from {zone:1454}? It goes to {npc:5905} too: skip {npc:5906}.\",\n\t\tonly = { races = { \"Tauren\", \"Skyborne\" } },\n\t\twhen = { { k = \"onquest\", neg = true, q = { 96136 } }, { k = \"onquest\", neg = true, q = { 1531 } } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 30 },\n\t\t\t{ t = \"accept\", quest = 1532, title = \"Call of Air\", npc = 5906, npcName = \"Xanis Flameweaver\", minLevel = 30, qlvl = 30, closedBy = { 1531, 96136 }, endNpcs = { 5905 }, xp = 2450, preTitles = { [1531] = \"Call of Air\", [96136] = \"Call of Air\" }, map = 1456, x = 25.2, y = 21.01, z = 138.1, spotsPacked = \"25.2,21,138.1,15,2\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5905}\",\n\t\tnote = \"Fly to {area:484}. {npc:5905} stands on a ledge above a cave mouth in the canyon wall north-east of the post, not inside the cave: climb the slope beside it. She also gives you an hour of faster attacks and running.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 43 },\n\t\t\t{ t = \"goto\", text = \"{npc:5905}\", map = 1441, x = 53.5, y = 42.6, z = -7.4, f = \"e\" },\n\t\t},\n\t},\n\t{\n\t\twhen = { { k = \"onquest\", q = { 1531 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1531, title = \"Call of Air\", npc = 5905, npcName = \"Prate Cloudseer\", map = 1441, x = 53.52, y = 42.66, z = -7.4, note = \"{npc:5905}: your {item:5178}\", rewards = { items = { { item = 5178, itemName = \"Air Totem\" } } } },\n\t\t},\n\t},\n\t{\n\t\twhen = { { k = \"onquest\", q = { 1532 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1532, title = \"Call of Air\", npc = 5905, npcName = \"Prate Cloudseer\", map = 1441, x = 53.52, y = 42.66, z = -7.4, note = \"{npc:5905}: your {item:5178}\", rewards = { items = { { item = 5178, itemName = \"Air Totem\" } } } },\n\t\t},\n\t},\n\t{\n\t\twhen = { { k = \"onquest\", q = { 96136 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 96136, title = \"Call of Air\", npc = 5905, npcName = \"Prate Cloudseer\", map = 1441, x = 53.52, y = 42.66, z = -7.4, note = \"{npc:5905}: your {item:5178}\", rewards = { items = { { item = 5178, itemName = \"Air Totem\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5905}\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 43 },\n\t\t\t{ t = \"accept\", quest = 79360, title = \"Elemental Aid\", npc = 5905, npcName = \"Prate Cloudseer\", minLevel = 30, qlvl = 33, pre = { 1531, 1532, 96136 }, preTitles = { [1531] = \"Call of Air\", [1532] = \"Call of Air\", [96136] = \"Call of Air\" }, map = 1441, x = 53.52, y = 42.66, z = -7.4 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:4421}\",\n\t\tnote = \"{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 33 },\n\t\t\t{ t = \"collect\", quest = 79360, title = \"Elemental Aid\", item = 274463, itemName = \"Tattered Note\", count = 1, oi = 1, map = 1413, x = 42.9, y = 90.2, note = \"{item:274463}, from {npc:4421}\", group = { kind = \"elite\", lvl = 33, rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:4722}\",\n\t\tnote = \"{npc:4722} stands at {area:484}.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 42 },\n\t\t\t{ t = \"turnin\", quest = 79360, title = \"Elemental Aid\", npc = 4722, npcName = \"Rau Cliffrunner\", map = 1441, x = 46.06, y = 51.6, z = 89.4 },\n\t\t\t{ t = \"accept\", quest = 79364, title = \"Eyes on the Sky\", npc = 4722, npcName = \"Rau Cliffrunner\", minLevel = 30, qlvl = 33, pre = { 79360 }, closedBy = { 98338 }, endNpcs = { 5905, 6176 }, xp = 270, preTitles = { [79360] = \"Elemental Aid\", [98338] = \"REUSE ME\" }, map = 1441, x = 46.06, y = 51.6, z = 89.4 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5905}\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 43 },\n\t\t\t{ t = \"turnin\", quest = 79364, title = \"Eyes on the Sky\", npc = 5905, npcName = \"Prate Cloudseer\", map = 1441, x = 53.52, y = 42.66, z = -7.4 },\n\t\t\t{ t = \"accept\", quest = 79361, title = \"Storm, Earth, and Fire\", npc = 5905, npcName = \"Prate Cloudseer\", minLevel = 30, qlvl = 43, pre = { 79364 }, preTitles = { [79364] = \"Eyes on the Sky\" }, map = 1441, x = 53.52, y = 42.66, z = -7.4 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Twisted Air Totems\",\n\t\tnote = \"Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 43 },\n\t\t\t{ t = \"collect\", quest = 79361, title = \"Storm, Earth, and Fire\", item = 274047, itemName = \"Twisted Air Totem\", count = 5, oi = 4, map = 1443, x = 28.83, y = 59.44, f = \"e\", spotsPacked = \"31.13,60.55,,71;29.9,67.08,,31;36.17,61.17,,49;39.72,61.24,,15;28.88,58.04,119.7,0,,1,40;28.77,60.84,131.1,0,,1,40\", from = \"Maraudine Marauder\", fromKind = \"npc\", fromId = 4659, fromNpcs = { { npc = 4659, npcName = \"Maraudine Marauder\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Twisted Water Totems\",\n\t\tnote = \"Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 42 },\n\t\t\t{ t = \"collect\", quest = 79361, title = \"Storm, Earth, and Fire\", item = 274046, itemName = \"Twisted Water Totem\", count = 5, oi = 1, map = 1445, x = 56.97, y = 21.79, f = \"e\", spotsPacked = \"56.97,21.79,,34;57.7,15.9,6.5,85,9,1,37;54.5,15,-6.1,53,5,1,37;62.4,18.6,,53,6,1,38;57.6,10.9,,49,9,1,38;63.4,27.6,,49,5,1,38;59.4,10.2,,40,7,1,38;64.8,26.7,,40,2,1,38;58.7,9.1,,50,11,1,38;64.5,28.6,,40,2,1,38;59.8,7.7,,40,4,1,38;63,7.5,3.4,64,18,1,38\", from = \"Mirefin Coastrunner\", fromKind = \"npc\", fromId = 4362, fromNpcs = { { npc = 4362, npcName = \"Mirefin Coastrunner\" }, { npc = 4361, npcName = \"Mirefin Muckdweller\" }, { npc = 4360, npcName = \"Mirefin Warrior\" }, { npc = 4363, npcName = \"Mirefin Oracle\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Twisted Fire Totems\",\n\t\tnote = \"Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 42 },\n\t\t\t{ t = \"collect\", quest = 79361, title = \"Storm, Earth, and Fire\", item = 274044, itemName = \"Twisted Fire Totem\", count = 5, oi = 3, map = 1418, x = 66.15, y = 23.29, z = 244.3, f = \"e\", spotsPacked = \"66.1,23.4,244.3,57,8;51.1,66.6,241.8,61,9,,42;49.4,70.8,,55,6,,40;12.9,73.3,241.8,40,1\", spread = true, lvl = 37, fromNpcs = { { npc = 2906, npcName = \"Dustbelcher Warrior\" }, { npc = 2893, npcName = \"Stonevault Bonesnapper\" }, { npc = 2907, npcName = \"Dustbelcher Mystic\" }, { npc = 2945, npcName = \"Murdaloc\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Twisted Earth Totems\",\n\t\tnote = \"Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 43 },\n\t\t\t{ t = \"collect\", quest = 79361, title = \"Storm, Earth, and Fire\", item = 274045, itemName = \"Twisted Earth Totem\", count = 5, oi = 2, map = 1435, x = 57.81, y = 26.31, f = \"e\", spotsPacked = \"57.81,26.31,,65;54.95,30.07,,54;65.07,21.97,21.8,15,1,1,37\", from = \"Ongeku\", fromKind = \"npc\", fromId = 5622, fromNpcs = { { npc = 5622, npcName = \"Ongeku\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5905}\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 43 },\n\t\t\t{ t = \"turnin\", quest = 79361, title = \"Storm, Earth, and Fire\", npc = 5905, npcName = \"Prate Cloudseer\", map = 1441, x = 53.52, y = 42.66, z = -7.4 },\n\t\t\t{ t = \"accept\", quest = 79366, title = \"Heed My Call\", npc = 5905, npcName = \"Prate Cloudseer\", minLevel = 30, qlvl = 40, pre = { 79361 }, closedBy = { 96135 }, endNpcs = { 4722 }, xp = 3150, preTitles = { [79361] = \"Storm, Earth, and Fire\", [96135] = \"Heed My Call\" }, map = 1441, x = 53.52, y = 42.66, z = -7.4 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The steam pools\",\n\t\tnote = \"{npc:5905} hands you the {item:268582}. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 43 },\n\t\t\t{ t = \"collect\", item = 212792, itemName = \"Eye of the Tempest\", count = 1, map = 1441, x = 41.85, y = 37.57, f = \"e\", spotsPacked = \"41.3,37.4,,26,2;40.6,40.3,,15,2;39,37.8,,37,5;37.1,38.1,,52,14;39.2,45,,45,3;36.8,42.3,,66,16;34.4,43,,76,8,1\", lvl = 40, note = \"{item:212792}, from the {npc:216474}\", from = \"Ravaging Tempest\", fromKind = \"npc\", fromRank = 1, fromId = 216474, fromNpcs = { { npc = 216474, npcName = \"Ravaging Tempest\" } }, group = { kind = \"group\", size = 3 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:4722}\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 42 },\n\t\t\t{ t = \"turnin\", quest = 79366, title = \"Heed My Call\", npc = 4722, npcName = \"Rau Cliffrunner\", map = 1441, x = 46.06, y = 51.6, z = 89.4 },\n\t\t\t{ t = \"accept\", quest = 79442, title = \"The Tempest's Weapons\", npc = 4722, npcName = \"Rau Cliffrunner\", minLevel = 30, qlvl = 40, pre = { 79366, 96135 }, closedBy = { 96016 }, endNpcs = { 6176 }, xp = 3900, preTitles = { [79366] = \"Heed My Call\", [96016] = \"The Tempest's Weapons\", [96135] = \"Heed My Call\" }, map = 1441, x = 46.06, y = 51.6, z = 89.4 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6176}\",\n\t\tnote = \"{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}; the {item:280696} shield comes with it.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 79442, title = \"The Tempest's Weapons\", npc = 6176, npcName = \"Bath'rah the Windwatcher\", map = 1416, x = 80.32, y = 66.86, z = 55.4, spotsPacked = \"79.83,64.72,,46,1\", note = \"{npc:6176}: the {item:280696} and your weapon\", rewards = { choices = { { item = 280607, itemName = \"Lightning's Grasp\" }, { item = 280605, itemName = \"Tidebringer's Claw\" }, { item = 280604, itemName = \"Rage of the Storm\" } }, items = { { item = 280696, itemName = \"Elementalist's Guard\" } } } },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

