{ 5887 }, xp = 270, preTitles = { [1519] = \"Call of Earth\", [92466] = \"Call of Earth\" }, map = 1411, x = 42.39, y = 69.12, z = 38.2 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Felstalker Hooves\",\n\t\tnote = \"Felstalkers (level 3-4) prowl the slope below the {area:365}, the cave in the north of the valley, and just inside its mouth among the Vile Familiars. Nearly every {npc:3102} drops a hoof (four kills in five); they respawn in a little over three minutes.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1516, title = \"Call of Earth\", item = 6640, itemName = \"Felstalker Hoof\", count = 2, oi = 1, map = 1411, x = 43.01, y = 55.34, z = 58.3, f = \"e\", spotsPacked = \"44.1,54.8,64.9,61,5;42.9,53.2,,51,5;44.6,52.8,,26,3;45.4,55.5,66.9,15,2\", lvl = 4, from = \"Felstalker\", fromKind = \"npc\", fromId = 3102, fromNpcs = { { npc = 3102, npcName = \"Felstalker\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5887}\",\n\t\tnote = \"Back to {npc:5887} outside the Den. She hands you the {quest:1462}: do not drink it yet.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1516, title = \"Call of Earth\", npc = 5887, npcName = \"Canaga Earthcaller\", map = 1411, x = 42.39, y = 69.12, z = 38.2 },\n\t\t\t{ t = \"accept\", quest = 1517, title = \"Call of Earth\", npc = 5887, npcName = \"Canaga Earthcaller\", minLevel = 4, qlvl = 4, pre = { 1516, 1519 }, preTitles = { [1516] = \"Call of Earth\", [1519] = \"Call of Earth\" }, map = 1411, x = 42.39, y = 69.12, z = 38.2 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Lost the {quest:1463}?\",\n\t\tnote = \"Only if the {quest:1463} is gone from your bags (drunk away from the rock, or sold): {npc:5887} gives you another.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\twhen = { { k = \"onquest\", q = { 1517 } }, { k = \"has\", neg = true, n = 1, item = 6635 } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1463, title = \"Earth Sapta\", npc = 5887, npcName = \"Canaga Earthcaller\", minLevel = 4, qlvl = 4, map = 1411, x = 42.39, y = 69.12, z = 38.2, note = \"{npc:5887}: a new {quest:1463}\", direct = true },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{area:639}\",\n\t\tnote = \"{area:639} sits on a ledge in the hills just south of the Den. The {area:638} up starts at the foot of the hills south-west of the Den, between two idle peons; it climbs south-west into the hills, then bends back east to the rock. Stand right beside the stone and drink the {item:6635}: the {npc:5891} appears for a short while, so speak to it at once (walk almost under it if it does not answer). Coming back, you can drop down the ledge towards the Den instead of walking the path.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"use\", item = 6635, itemName = \"Earth Sapta\", map = 1411, x = 44.1, y = 76.4, f = \"e\", note = \"{item:6635}, beside {area:639}\" },\n\t\t\t{ t = \"turnin\", quest = 1517, title = \"Call of Earth\", npc = 5891, npcName = \"Minor Manifestation of Earth\", map = 1411, x = 43.97, y = 76.1, z = 72.7 },\n\t\t\t{ t = \"accept\", quest = 1518, title = \"Call of Earth\", npc = 5891, npcName = \"Minor Manifestation of Earth\", minLevel = 4, qlvl = 4, pre = { 1517 }, preTitles = { [1517] = \"Call of Earth\" }, map = 1411, x = 43.97, y = 76.1, z = 72.7, note = \"it hands you the {item:6656}: keep it\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5887}\",\n\t\tnote = \"Bring the {item:6656} back to {npc:5887} outside the Den. Keep the {item:5175} she gives you in your bags for good: every earth totem needs it.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1518, title = \"Call of Earth\", npc = 5887, npcName = \"Canaga Earthcaller\", map = 1411, x = 42.39, y = 69.12, z = 38.2, note = \"{npc:5887}: {spell:8071} and your {item:5175}\", rewards = { items = { { item = 5175, itemName = \"Earth Totem\" } } } },\n\t\t\t{ t = \"train\", class = true, zone = 1411, note = \"the level 4 shaman spells\", candidates = { candidateRecords[1], candidateRecords[2], candidateRecords[3], candidateRecords[4], { npc = 3031, npcName = \"Tigor Skychaser\", map = 1456, x = 23.32, y = 19.06, z = 138.1, faction = \"H\", classes = { \"SHAMAN\" } }, candidateRecords[5], candidateRecords[6], candidateRecords[7], candidateRecords[8], candidateRecords[9], candidateRecords[10] } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5888}\",\n\t\tnote = \"{npc:5888} stands in {area:221}. She may show no quest mark over her head: speak to her anyway. The quest opens at level 4.\",\n\t\tonly = { races = { \"Tauren\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 4 },\n\t\t\t{ t = \"accept\", quest = 1519, title = \"Call of Earth\", npc = 5888, npcName = \"Seer Ravenfeather\", minLevel = 4, qlvl = 4, closedBy = { 1516, 92466 }, endNpcs = { 5888 }, xp = 270, preTitles = { [1516] = \"Call of Earth\", [92466] = \"Call of Earth\" }, map = 1412, x = 44.3, y = 76.84, z = 54 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:6634}\",\n\t\tnote = \"The Bristleback Shamans (level 3-4) stand among the quilboar huts of {area:358}, east of the camp, and throw the odd {spell:403}. Four kills in five drop a salve; they respawn in about four minutes.\",\n\t\tonly = { races = { \"Tauren\" } },\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1519, title = \"Call of Earth\", item = 6634, itemName = \"Ritual Salve\", count = 2, oi = 1, map = 1412, x = 56.61, y = 78.3, z = 54.8, spotsPacked = \"57,76.3,55.6,17,3;60.1,81.6,,29,2;61.3,77.9,,71,5;56.6,78.3,54.8,15,1,1;58.4,76.7,88.6,15,1,1;60.3,79.8,66.1,15,1,1\", lvl = 4, from = \"Bristleback Shaman\", fromKind = \"npc\", fromId = 2953, fromNpcs = { { npc = 2953, npcName = \"Bristleback Shaman\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5888}\",\n\t\tnote = \"Back to the Seer in {area:221}. She hands you the {quest:1462}: do not drink it yet.\",\n\t\tonly = { races = { \"Tauren\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1519, title = \"Call of Earth\", npc = 5888, npcName = \"Seer Ravenfeather\", map = 1412, x = 44.3, y = 76.84, z = 54 },\n\t\t\t{ t = \"accept\", quest = 1520, title = \"Call of Earth\", npc = 5888, npcName = \"Seer Ravenfeather\", minLevel = 4, qlvl = 4, pre = { 1516, 1519 }, preTitles = { [1516] = \"Call of Earth\", [1519] = \"Call of Earth\" }, map = 1412, x = 44.3, y = 76.84, z = 54 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Lost the {quest:1462}?\",\n\t\tnote = \"Only if the {quest:1462} is gone from your bags: the Seer gives you another.\",\n\t\tonly = { races = { \"Tauren\" } },\n\t\twhen = { { k = \"onquest\", q = { 1520 } }, { k = \"has\", neg = true, n = 1, item = 6635 } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1462, title = \"Earth Sapta\", npc = 5888, npcName = \"Seer Ravenfeather\", minLevel = 4, qlvl = 4, map = 1412, x = 44.3, y = 76.84, z = 54, note = \"{npc:5888}: a new {quest:1462}\", direct = true },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{area:637}\",\n\t\tnote = \"{area:637} is a small pillar on a low mound due east of {npc:2991}'s well, east of the camp; it only shows from about fifteen yards away, and hostile boars graze around it. Stand beside it and drink the {item:6635}, then speak to the {npc:5891} before it fades (drink again if it does).\",\n\t\tonly = { races = { \"Tauren\" } },\n\t\tgoals = {\n\t\t\t{ t = \"use\", item = 6635, itemName = \"Earth Sapta\", map = 1412, x = 52, y = 80.1, f = \"e\", note = \"{item:6635}, beside {area:637}\" },\n\t\t\t{ t = \"turnin\", quest = 1520, title = \"Call of Earth\", npc = 5891, npcName = \"Minor Manifestation of Earth\", map = 1412, x = 51.85, y = 80.32, z = 44.9 },\n\t\t\t{ t = \"accept\", quest = 1521, title = \"Call of Earth\", npc = 5891, npcName = \"Minor Manifestation of Earth\", minLevel = 4, qlvl = 4, pre = { 1520 }, preTitles = { [1520] = \"Call of Earth\" }, map = 1412, x = 51.85, y = 80.32, z = 44.9, note = \"it hands you the {item:6656}: keep it\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5888}\",\n\t\tnote = \"Bring the {item:6656} back to the Seer. Keep the {item:5175} in your bags for good: every earth totem needs it.\",\n\t\tonly = { races = { \"Tauren\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1521, title = \"Call of Earth\", npc = 5888, npcName = \"Seer Ravenfeather\", map = 1412, x = 44.3, y = 76.84, z = 54, note = \"{npc:5888}: {spell:8071} and your {item:5175}\", rewards = { items = { { item = 5175, itemName = \"Earth Totem\" } } } },\n\t\t\t{ t = \"train\", class = true, zone = 1412, note = \"the level 4 shaman spells\", candidates = { candidateRecords[5], candidateRecords[4], candidateRecords[11], candidateRecords[6], candidateRecords[1], candidateRecords[2], { npc = 3403, npcName = \"Sian'tsu\", map = 1454, x = 37.95, y = 36.53, z = 42.2, faction = \"H\", classes = { \"SHAMAN\" } }, candidateRecords[7], candidateRecords[8], candidateRecords[9], candidateRecords[10] } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:251374}\",\n\t\tnote = \"{npc:251374}, the shaman trainer, stands in {area:16635}. The quest opens at level 3.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 3 },\n\t\t\t{ t = \"accept\", quest = 92466, title = \"Call of Earth\", npc = 251374, npcName = \"Windshaper Boro\", minLevel = 3, qlvl = 4, closedBy = { 1516, 1519 }, endNpcs = { 251374 }, xp = 270, preTitles = { [1516] = \"Call of Earth\", [1519] = \"Call of Earth\" }, map = 2521, x = 42.71, y = 23.56, z = 976.8 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:251924}\",\n\t\tnote = \"Any Al'Aketh cultist can carry the {item:251924}: the Converts (level 2-3) around the standing stones just east of the village, or the Brutes and Neophytes (level 4) in the camp beyond {npc:252095}, south-west of the village. Keep killing until one drops it.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 92466, title = \"Call of Earth\", item = 251924, itemName = \"Signet of Akir\", count = 1, oi = 1, map = 2521, x = 43.77, y = 24.09, spotsPacked = \"43.8,24.1,,40,1,,3;47.1,21.1,,52,7,,3;48.5,20.2,927.5,47,9,,3;46.6,17.8,939.7,40,2,,3;38.7,30.5,,40,4,,4;37.4,31.2,,71,13,,4;38.1,32.7,,43,13,,4;39,34.2,,40,4,,4;37.2,34.4,957.8,64,15,,4;36,33,,59,15,,4;48.9,54.3,781.3,40,2,,6;66.3,76.6,735.3,40,1;46.6,18.9,938,73,7,1,3\", spread = true, fromNpcs = { { npc = 251160, npcName = \"Al'Aketh Convert\" }, { npc = 251145, npcName = \"Al'Aketh Brute\" }, { npc = 251448, npcName = \"Al'Aketh Neophyte\" }, { npc = 252077, npcName = \"Skypriest Aanders\" }, { npc = 264712, npcName = \"High Priestess Lorthuna\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:251374}\",\n\t\tnote = \"Back to Boro in {area:16635}. He hands you the {quest:1462}: do not drink it yet.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 92466, title = \"Call of Earth\", npc = 251374, npcName = \"Windshaper Boro\", map = 2521, x = 42.71, y = 23.56, z = 976.8 },\n\t\t\t{ t = \"accept\", quest = 92467, title = \"Call of Earth\", npc = 251374, npcName = \"Windshaper Boro\", minLevel = 3, qlvl = 4, pre = { 1516, 1519, 92466 }, preTitles = { [1516] = \"Call of Earth\", [1519] = \"Call of Earth\", [92466] = \"Call of Earth\" }, map = 2521, x = 42.71, y = 23.56, z = 976.8 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {area:16988}\",\n\t\tnote = \"The {area:16988} is the hilltop shrine north-east of Boro: the path up starts on the hill just above the clearing where the flies were. Drink the {item:6635} beside the shrine and speak to the {npc:251166} before it fades.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"use\", item = 6635, itemName = \"Earth Sapta\", map = 2521, x = 49.7, y = 23.8, note = \"{item:6635}, beside the shrine\" },\n\t\t\t{ t = \"turnin\", quest = 92467, title = \"Call of Earth\", npc = 251166, npcName = \"Minor Manifestation of Earth\", map = 2521, x = 49.69, y = 23.93, z = 1023.2 },\n\t\t\t{ t = \"accept\", quest = 92468, title = \"Call of Earth\", npc = 251166, npcName = \"Minor Manifestation of Earth\", minLevel = 3, qlvl = 4, pre = { 92467 }, preTitles = { [92467] = \"Call of Earth\" }, map = 2521, x = 49.69, y = 23.93, z = 1023.2, note = \"it hands you the {item:6656}: keep it\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:251374}\",\n\t\tnote = \"Bring the {item:6656} back to Boro. Keep the {item:5175} in your bags for good: every earth totem needs it.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 92468, title = \"Call of Earth\", npc = 251374, npcName = \"Windshaper Boro\", map = 2521, x = 42.71, y = 23.56, z = 976.8, note = \"{npc:251374}: {spell:8071} and your {item:5175}\" },\n\t\t\t{ t = \"train\", class = true, zone = 2521, candidates = { candidateRecords[8], candidateRecords[10], candidateRecords[9], candidateRecords[1], candidateRecords[2], candidateRecords[5], candidateRecords[4], candidateRecords[6], candidateRecords[7], candidateRecords[3], candidateRecords[11] } },\n\t\t},\n\t},\n}",
		})
