			names = { ["area:16629"] = "Shrine of Akir", ["area:16638"] = "Valanaar", ["area:16663"] = "Windfield Orchard", ["area:1704"] = "Grol'dom Farm", ["area:17045"] = "Skywatcher Plateau", ["area:17675"] = "East Pylon Watchtower", ["area:222"] = "Bloodhoof Village", ["area:362"] = "Razor Hill", ["area:371"] = "Dustwind Cave", ["area:379"] = "Far Watch Post", ["area:817"] = "Skull Rock", ["item:263412"] = "Totem of Charged Flames", ["item:277329"] = "Torch of Eternal Flame", ["item:5026"] = "Fire Tar", ["item:5176"] = "Fire Totem", ["item:6636"] = "Fire Sapta", ["item:6652"] = "Reagent Pouch", ["item:6653"] = "Torch of the Dormant Flame", ["item:6655"] = "Glowing Ember", ["npc:251968"] = "Ayessa Dawnsinger", ["npc:252382"] = "Sessaria Skystride", ["npc:254082"] = "Aarnor Galestrike", ["npc:254588"] = "Windsong Crawler", ["npc:268592"] = "Olariaan Swiftburn", ["npc:268602"] = "Skypriest Faladiel", ["npc:268605"] = "Kuramaa", ["npc:268679"] = "Brazier of Eternal Flame", ["npc:268762"] = "Brazier of Offering", ["npc:3066"] = "Narm Skychaser", ["npc:3173"] = "Swart", ["npc:3199"] = "Burning Blade Cultist", ["npc:5892"] = "Searn Firewarder", ["npc:5893"] = "Minor Manifestation of Fire", ["npc:5900"] = "Telf Joolam", ["npc:5906"] = "Xanis Flameweaver", ["npc:5907"] = "Kranal Fiss", ["object:148418"] = "Eternal Flame", ["object:61934"] = "Brazier of the Dormant Flame", ["object:63674"] = "Shaman Shrine", ["object:660848"] = "Kuramaa's Stump", ["quest:1464"] = "Fire Sapta", ["quest:1522"] = "Call of Fire", ["quest:97243"] = "Call of Fire", ["spell:133"] = "Fireball", ["spell:348"] = "Immolate", ["spell:3599"] = "Searing Totem", ["spell:8017"] = "Rockbiter Weapon", ["spell:8042"] = "Earth Shock", ["spell:8050"] = "Flame Shock", ["zone:1411"] = "Durotar", ["zone:1413"] = "Barrens", ["zone:1440"] = "Ashenvale", ["zone:1454"] = "Orgrimmar", ["zone:1456"] = "Thunder Bluff" },
			written = { ["At 10 {npc:3066}, the shaman trainer in {area:222}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5906}'s letter from {zone:1456}? It goes to {npc:5907} too: skip Narm."] = "At 10 Narm Skychaser, the shaman trainer in Bloodhoof Village, sends you to Kranal Fiss in the Barrens. Already carry Xanis Flameweaver's letter from Thunder Bluff? It goes to Kranal too: skip Narm.", ["At 10 {npc:3173}, the shaman trainer on the east side of {area:362}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5892}'s letter from {zone:1454}? It goes to {npc:5907} too: skip {npc:3173}."] = "At 10 Swart, the shaman trainer on the east side of Razor Hill, sends you to Kranal Fiss in the Barrens. Already carry Searn Firewarder's letter from Orgrimmar? It goes to Kranal too: skip Swart.", ["Back to {npc:268592} at the Shrine of Flames."] = "Back to Olariaan at the Shrine of Flames.", ["Back to {npc:268592}. Accept the last quest, then wait by the {npc:268762} while he performs the ritual; when the fire spirits light the {object:148418}, hold the torch to it. From then you have six minutes: carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638}, with no detours or fights. Timer out? Abandon the quest and take it again from {npc:268592}."] = "Back to Olariaan. Accept the last quest, then wait by the Brazier of Offering while he performs the ritual; when the fire spirits light the Eternal Flame, hold the torch to it. From then you have six minutes: carry the flame straight to the Brazier of Eternal Flame beside Sessaria in Valanaar, with no detours or fights. Timer out? Abandon the quest and take it again from Olariaan.", ["Back up the trail to {npc:5900}. He makes the {quest:1464} from the tar and the pouch and hands it to you with the torch: keep both."] = "Back up the trail to Telf. He makes the Fire Sapta from the tar and the pouch and hands it to you with the torch: keep both.", ["Only if the {quest:1464} is gone from your bags: {npc:5900} gives you another."] = "Only if the Fire Sapta is gone from your bags: Telf gives you another.", ["{npc:5907} hands you the {item:6653}: keep it until the end of the chain."] = "Kranal hands you the Torch of the Dormant Flame: keep it until the end of the chain." },
			stepCount = 23,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:3173}\",\n\t\tnote = \"At 10 {npc:3173}, the shaman trainer on the east side of {area:362}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5892}'s letter from {zone:1454}? It goes to {npc:5907} too: skip {npc:3173}.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 2983, title = \"Call of Fire\", npc = 3173, npcName = \"Swart\", minLevel = 10, qlvl = 10, closedBy = { 1524, 1522, 1523, 2984 }, endNpcs = { 5907 }, xp = 420, preTitles = { [1522] = \"Call of Fire\", [1523] = \"Call of Fire\", [1524] = \"Call of Fire\", [2984] = \"Call of Fire\" }, map = 1411, x = 54.36, y = 42.55, z = 10.6, optional = true, note = \"{npc:3173}, {area:362}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:3066}\",\n\t\tnote = \"At 10 {npc:3066}, the shaman trainer in {area:222}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5906}'s letter from {zone:1456}? It goes to {npc:5907} too: skip Narm.\",\n\t\tonly = { races = { \"Tauren\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 2984, title = \"Call of Fire\", npc = 3066, npcName = \"Narm Skychaser\", minLevel = 10, qlvl = 10, closedBy = { 1524, 1522, 1523, 2983 }, endNpcs = { 5907 }, xp = 420, preTitles = { [1522] = \"Call of Fire\", [1523] = \"Call of Fire\", [1524] = \"Call of Fire\", [2983] = \"Call of Fire\" }, map = 1412, x = 47.39, y = 62.6, z = -5.4, optional = true, note = \"{npc:3066}, {area:222}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5907}\",\n\t\tnote = \"{npc:5907} is not in the Crossroads: take the road north from the Crossroads and fork east towards {zone:1411}; past {area:1704} he paces by a tall tower east of the road (from {zone:1411}: over the Southfury bridge, past {area:379}). If you reach {zone:1440} you went too far.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\" } },\n\t\tgoals = {\n\t\t\t{ t = \"goto\", text = \"{npc:5907}\", map = 1413, x = 56, y = 19.9, z = 97, f = \"e\" },\n\t\t},\n\t},\n\t{\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\" } },\n\t\twhen = { { k = \"onquest\", q = { 2983 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2983, title = \"Call of Fire\", npc = 5907, npcName = \"Kranal Fiss\", map = 1413, x = 55.88, y = 19.96, z = 97, note = \"{npc:5907}: {npc:3173}'s letter\" },\n\t\t},\n\t},\n\t{\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\" } },\n\t\twhen = { { k = \"onquest\", q = { 1522 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1522, title = \"Call of Fire\", npc = 5907, npcName = \"Kranal Fiss\", map = 1413, x = 55.88, y = 19.96, z = 97, note = \"{npc:5907}: {npc:5892}'s letter\" },\n\t\t},\n\t},\n\t{\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\" } },\n\t\twhen = { { k = \"onquest\", q = { 2984 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2984, title = \"Call of Fire\", npc = 5907, npcName = \"Kranal Fiss\", map = 1413, x = 55.88, y = 19.96, z = 97, note = \"{npc:5907}: {npc:3066}'s letter\" },\n\t\t},\n\t},\n\t{\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\" } },\n\t\twhen = { { k = \"onquest\", q = { 1523 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1523, title = \"Call of Fire\", npc = 5907, npcName = \"Kranal Fiss\", map = 1413, x = 55.88, y = 19.96, z = 97, note = \"{npc:5907}: {npc:5906}'s letter\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5907}\",\n\t\tnote = \"{npc:5907} hands you the {item:6653}: keep it until the end of the chain.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\" } },\n\t\tgoals = {\n\t\t\t{ t = \"accept\", quest = 1524, title = \"Call of Fire\", npc = 5907, npcName = \"Kranal Fiss\", minLevel = 10, qlvl = 11, closedBy = { 97243 }, endNpcs = { 5900 }, xp = 650, crumbs = { 1522, 1523, 2983, 2984 }, preTitles = { [1522] = \"Call of Fire\", [1523] = \"Call of Fire\", [2983] = \"Call of Fire\", [2984] = \"Call of Fire\", [97243] = \"Call of Fire\" }, map = 1413, x = 55.88, y = 19.96, z = 97 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5900}\",\n\t\tnote = \"Back east over the bridge, then south along the {zone:1411} bank of the river to where the mountains meet the water. The trail up starts at the foot of the mountain beside a small dark stone carved with symbols, near the quilboar camp; it is narrow, and a slip costs fall damage. {npc:5900} keeps the shrine at the top.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 11 },\n\t\t\t{ t = \"turnin\", quest = 1524, title = \"Call of Fire\", npc = 5900, npcName = \"Telf Joolam\", map = 1411, x = 38.51, y = 58.9, z = 168.2 },\n\t\t\t{ t = \"accept\", quest = 1525, title = \"Call of Fire\", npc = 5900, npcName = \"Telf Joolam\", minLevel = 10, qlvl = 12, pre = { 1524 }, preTitles = { [1524] = \"Call of Fire\" }, map = 1411, x = 38.51, y = 58.9, z = 168.2 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:5026}\",\n\t\tnote = \"The Razormane casters north-east of the Crossroads drop the {item:5026} three times in four: Water Seekers and Thornweavers (level 10-11), Geomancers (level 12-13, they throw Fireballs and run for help when hurt) and Mystics (level 13-14, they heal themselves at low health). Pull them one at a time.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 12 },\n\t\t\t{ t = \"collect\", quest = 1525, title = \"Call of Fire\", item = 5026, itemName = \"Fire Tar\", count = 1, oi = 1, map = 1413, x = 54.59, y = 25.93, f = \"e\", spotsPacked = \"54.4,25.3,,49,8;53.9,25.7,,40,3;53.4,24.8,,40,2;55.3,25.5,,40,2;55.4,26.8,91.8,72,11;57,25.3,92,52,3,,13;57.1,24.4,92.3,40,3,,13;59.1,24.4,91.8,45,6,,13;58.5,26.7,91.8,43,4,,14\", spread = true, lvl = 11, from = \"Razormane Water Seeker\", fromKind = \"npc\", fromAlso = \"Razormane Thornweaver\", fromId = 3267, fromAlsoId = 3268, fromNpcs = { { npc = 3267, npcName = \"Razormane Water Seeker\" }, { npc = 3268, npcName = \"Razormane Thornweaver\" }, { npc = 3269, npcName = \"Razormane Geomancer\" }, { npc = 3271, npcName = \"Razormane Mystic\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:6652}\",\n\t\tnote = \"The Burning Blade Cultists (level 10-11, they call imps and cast {spell:348}) live deep in {area:371} north of {area:362}: climb the ramp just north-east of town and stay on the high ground above the ravines. The orcs at the cave mouth are not cultists; the cultists are further in, off to the left. Three kills in four drop a pouch. {area:817} by {zone:1454} is the wrong cave.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 11 },\n\t\t\t{ t = \"collect\", quest = 1525, title = \"Call of Fire\", item = 6652, itemName = \"Reagent Pouch\", count = 1, oi = 2, map = 1411, x = 52.37, y = 25.53, f = \"e\", spotsPacked = \"52,25.9,23.8,44,5\", lvl = 11, from = \"Burning Blade Cultist\", fromKind = \"npc\", fromAlso = \"Stonesplinter Seer\", fromId = 3199, fromAlsoId = 1166, fromNpcs = { { npc = 3199, npcName = \"Burning Blade Cultist\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5900}\",\n\t\tnote = \"Back up the trail to {npc:5900}. He makes the {quest:1464} from the tar and the pouch and hands it to you with the torch: keep both.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 12 },\n\t\t\t{ t = \"turnin\", quest = 1525, title = \"Call of Fire\", npc = 5900, npcName = \"Telf Joolam\", map = 1411, x = 38.51, y = 58.9, z = 168.2 },\n\t\t\t{ t = \"accept\", quest = 1526, title = \"Call of Fire\", npc = 5900, npcName = \"Telf Joolam\", minLevel = 10, qlvl = 13, pre = { 1525 }, preTitles = { [1525] = \"Call of Fire\" }, map = 1411, x = 38.51, y = 58.9, z = 168.2 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Lost the {quest:1464}?\",\n\t\tnote = \"Only if the {quest:1464} is gone from your bags: {npc:5900} gives you another.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\" } },\n\t\twhen = { { k = \"onquest\", q = { 1526 } }, { k = \"has\", neg = true, n = 1, item = 6636 } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1464, title = \"Fire Sapta\", npc = 5900, npcName = \"Telf Joolam\", minLevel = 10, qlvl = 13, map = 1411, x = 38.51, y = 58.9, z = 168.2, note = \"{npc:5900}: a new {quest:1464}\", direct = true },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {npc:5893}\",\n\t\tnote = \"Drink the {item:6636} beside the {object:63674}, the big grey stone just below the summit, then climb to the plateau. Of the fire elementals there only the one in the middle can be attacked: it is level 12, immune to fire and grows stronger the longer the fight lasts, so open at once with {spell:8017} and {spell:8042} and leave the others alone. Its {item:6655} drops every time.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 13 },\n\t\t\t{ t = \"use\", quest = 1526, title = \"Call of Fire\", item = 6636, itemName = \"Fire Sapta\", oi = 1, map = 1411, x = 38.1, y = 58.5, f = \"e\", note = \"{item:6636}, beside the {object:63674}\" },\n\t\t\t{ t = \"collect\", quest = 1526, title = \"Call of Fire\", item = 6655, itemName = \"Glowing Ember\", count = 1, oi = 1, map = 1411, x = 38.72, y = 58.29, z = 187.3, f = \"e\", note = \"{item:6655}: {npc:5893}\", from = \"Minor Manifestation of Fire\", fromKind = \"npc\", fromId = 5893, fromNpcs = { { npc = 5893, npcName = \"Minor Manifestation of Fire\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {object:61934}\",\n\t\tnote = \"Click the {object:61934} on the plateau with the torch in your bags to place the ember, then click it a second time: the next quest does not open by itself. It gives you the lit {item:277329}.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 11 },\n\t\t\t{ t = \"turnin\", quest = 1526, title = \"Call of Fire\", object = 61934, objName = \"Brazier of the Dormant Flame\", map = 1411, x = 38.88, y = 58.2, z = 187.3 },\n\t\t\t{ t = \"accept\", quest = 1527, title = \"Call of Fire\", object = 61934, objName = \"Brazier of the Dormant Flame\", minLevel = 10, qlvl = 13, pre = { 1526 }, preTitles = { [1526] = \"Call of Fire\" }, map = 1411, x = 38.88, y = 58.2, z = 187.3 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5907}\",\n\t\tnote = \"Down the trail, back over the bridge to {npc:5907} by his tower. Keep the {item:5176} in your bags for good: every fire totem needs it.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1527, title = \"Call of Fire\", npc = 5907, npcName = \"Kranal Fiss\", map = 1413, x = 55.88, y = 19.96, z = 97, note = \"{npc:5907}: {spell:3599}, your {item:5176} and the {item:263412}\", rewards = { items = { { item = 5176, itemName = \"Fire Totem\" }, { item = 263412, itemName = \"Totem of Charged Flames\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:252382}\",\n\t\tnote = \"At 10 {npc:252382}, the shaman trainer beside {npc:251968} in {area:16638}, hands you the {item:6653} ({npc:254082} offers the same quest). Already left the isle? A {quest:97243} sends you back to them: take the skycutter from the cliffs south of {area:17045}, north of {zone:1456}. Learn {spell:8050} from her now: {npc:268605}, later in the chain, only takes fire damage.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 97243, title = \"Call of Fire\", npc = 252382, npcName = \"Sessaria Skystride\", minLevel = 10, qlvl = 10, closedBy = { 1524 }, endNpcs = { 268592 }, xp = 420, crumbs = { 98517 }, preTitles = { [1524] = \"Call of Fire\", [98517] = \"Call of Fire\" }, map = 2521, x = 58.23, y = 78.57, z = 656.8 },\n\t\t\t{ t = \"train\", class = true, zone = 2521, candidates = { { npc = 252382, npcName = \"Sessaria Skystride\", map = 2521, x = 58.23, y = 78.57, z = 656.8, faction = \"H\", classes = { \"SHAMAN\" } }, { npc = 254082, npcName = \"Aarnor Galestrike\", map = 2521, x = 43.45, y = 44.81, z = 823.8, faction = \"H\", classes = { \"SHAMAN\" } }, { npc = 251374, npcName = \"Windshaper Boro\", map = 2521, x = 42.71, y = 23.56, z = 976.8, faction = \"H\", classes = { \"SHAMAN\" } }, { npc = 3157, npcName = \"Shikrik\", map = 1411, x = 42.38, y = 68.9, z = 38.4, faction = \"H\", classes = { \"SHAMAN\" } }, { npc = 3173, npcName = \"Swart\", map = 1411, x = 54.36, y = 42.55, z = 10.6, faction = \"H\", classes = { \"SHAMAN\" } }, { npc = 3062, npcName = \"Meela Dawnstrider\", map = 1412, x = 44.58, y = 76.64, z = 54, faction = \"H\", classes = { \"SHAMAN\" } }, { npc = 3066, npcName = \"Narm Skychaser\", map = 1412, x = 47.39, y = 62.6, z = -5.4, faction = \"H\", classes = { \"SHAMAN\" } }, { npc = 262558, npcName = \"Palah Thunderhoof\", map = 1412, x = 33.56, y = 22.47, z = 187.2, faction = \"H\", classes = { \"SHAMAN\" } }, { npc = 986, npcName = \"Haromm\", map = 1435, x = 48.19, y = 57.94, z = 20.9, f = \"e\", faction = \"H\", classes = { \"SHAMAN\" } }, { npc = 3344, npcName = \"Kardris Dreamseeker\", map = 1454, x = 38.68, y = 36.64, z = 42.2, faction = \"H\", classes = { \"SHAMAN\" } }, { npc = 3030, npcName = \"Siln Skychaser\", map = 1456, x = 22.87, y = 20.47, z = 138.1, faction = \"H\", classes = { \"SHAMAN\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:268592}\",\n\t\tnote = \"The Shrine of Flames hides on the island's outer rim south-west of {area:16638}, just south-east of {area:16663}: {npc:268592} keeps it.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 13 },\n\t\t\t{ t = \"turnin\", quest = 97243, title = \"Call of Fire\", npc = 268592, npcName = \"Olariaan Swiftburn\", map = 2521, x = 51.18, y = 86.09, z = 656.5 },\n\t\t\t{ t = \"accept\", quest = 97244, title = \"Call of Fire\", npc = 268592, npcName = \"Olariaan Swiftburn\", minLevel = 10, qlvl = 10, pre = { 97243 }, preTitles = { [97243] = \"Call of Fire\" }, map = 2521, x = 51.18, y = 86.09, z = 656.5 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:268602}\",\n\t\tnote = \"{npc:268602} (level 10, a turncoat Windshaper with a single spawn) holds the farm north-east past {area:16638}, just south of the {area:16629}, on the hill west of the falls north of the {area:17675}. Kill him and take his heart.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 97244, title = \"Call of Fire\", item = 277267, itemName = \"Faladiel's Heart\", count = 1, oi = 1, map = 2521, x = 64.43, y = 63.71, z = 653.8, from = \"Skypriest Faladiel\", fromKind = \"npc\", fromId = 268602, fromNpcs = { { npc = 268602, npcName = \"Skypriest Faladiel\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:268592}\",\n\t\tnote = \"Back to {npc:268592} at the Shrine of Flames.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 13 },\n\t\t\t{ t = \"turnin\", quest = 97244, title = \"Call of Fire\", npc = 268592, npcName = \"Olariaan Swiftburn\", map = 2521, x = 51.18, y = 86.09, z = 656.5 },\n\t\t\t{ t = \"accept\", quest = 97245, title = \"Call of Fire\", npc = 268592, npcName = \"Olariaan Swiftburn\", minLevel = 10, qlvl = 10, pre = { 97244 }, preTitles = { [97244] = \"Call of Fire\" }, map = 2521, x = 51.18, y = 86.09, z = 656.5 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:268605}\",\n\t\tnote = \"{object:660848} is the twisted stump on the hilltop by the Shen'dar Highlands Anchor Pylon, west of {area:16638}, in the hills south of the Windsong Crawlers' lakes. Knock on it to call {npc:268605} (level 10). The spirit shrugs off most magic: only fire hurts it, so keep {spell:8050} on it. Take its wooden mask.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"interact\", object = 660848, objName = \"Kuramaa's Stump\", map = 2521, x = 42.35, y = 68.82, z = 794.3, note = \"{object:660848}: knock on the bark\" },\n\t\t\t{ t = \"collect\", quest = 97245, title = \"Call of Fire\", item = 277269, itemName = \"Kuramaa's Mask\", count = 1, oi = 1, map = 2521, x = 42.44, y = 68.75, from = \"Kuramaa\", fromKind = \"npc\", fromId = 268605, fromNpcs = { { npc = 268605, npcName = \"Kuramaa\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {object:148418}\",\n\t\tnote = \"Back to {npc:268592}. Accept the last quest, then wait by the {npc:268762} while he performs the ritual; when the fire spirits light the {object:148418}, hold the torch to it. From then you have six minutes: carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638}, with no detours or fights. Timer out? Abandon the quest and take it again from {npc:268592}.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 97245, title = \"Call of Fire\", npc = 268592, npcName = \"Olariaan Swiftburn\", map = 2521, x = 51.18, y = 86.09, z = 656.5 },\n\t\t\t{ t = \"accept\", quest = 97257, title = \"Call of Fire\", npc = 268592, npcName = \"Olariaan Swiftburn\", minLevel = 10, qlvl = 10, limit = 360, pre = { 97245 }, preTitles = { [97245] = \"Call of Fire\" }, map = 2521, x = 51.18, y = 86.09, z = 656.5 },\n\t\t\t{ t = \"goto\", text = \"{npc:268762}\", map = 2521, x = 51.2, y = 85.9 },\n\t\t\t{ t = \"complete\", quest = 97257, title = \"Call of Fire\", map = 2521, x = 58.4, y = 78.8, note = \"the ritual, then the {npc:268679} in {area:16638}\", objs = { { text = \"Brazier of Offering\", count = 1 }, { text = \"Brazier of Eternal Flame\", count = 1 } }, startItem = 277329, startItemName = \"Torch of Eternal Flame\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:252382}\",\n\t\tnote = \"Keep the {item:5176} in your bags for good: every fire totem needs it.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 97257, title = \"Call of Fire\", npc = 252382, npcName = \"Sessaria Skystride\", map = 2521, x = 58.23, y = 78.57, z = 656.8, note = \"{npc:252382}: {spell:3599}, your {item:5176} and the {item:263412}\", rewards = { items = { { item = 5176, itemName = \"Fire Totem\" }, { item = 263412, itemName = \"Totem of Charged Flames\" } } } },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

