			written = { ["At 50 {npc:3032}, a shaman trainer on {area:1640} in {zone:1456}, asks for the four elements for {npc:6176}. Skyborne: Forever's quest page lists {quest:8410} and {quest:8412} for Orcs, Tauren and Trolls only; if {npc:3032} has nothing for you, {npc:6176}'s own {quest:8411} is open to every Horde race, but {quest:8412} after it may still turn you away."] = "At 50 Beram Skychaser, a shaman trainer on Spirit Rise in Thunder Bluff, asks for the four elements for Bath'rah the Windwatcher. Skyborne: Forever's quest page lists Elemental Mastery and Spirit Totem for Orcs, Tauren and Trolls only; if Beram has nothing for you, Bath'rah's own Mastering the Elements is open to every Horde race, but Spirit Totem after it may still turn you away.", ["{npc:6176} camps in the ruins of the east of {zone:1416}: from {area:272} follow the river east of town north into the hills."] = "Bath'rah camps in the ruins of the east of Alterac Mountains: from Tarren Mill follow the river east of town north into the hills." },
			stepCount = 8,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:13417}\",\n\t\tnote = \"At 50 {npc:13417}, the shaman trainer in the {object:172957}, asks for the four elements for {npc:6176}.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 50 },\n\t\t\t{ t = \"accept\", quest = 8410, title = \"Elemental Mastery\", npc = 13417, npcName = \"Sagorne Creststrider\", minLevel = 50, qlvl = 50, closedBy = { 8411 }, endNpcs = { 6176 }, xp = 3800, preTitles = { [8411] = \"Mastering the Elements\" }, map = 1454, x = 38.58, y = 36.11, z = 42.2, spotsPacked = \"38.6,36.1,42.2,15,4\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:3032}\",\n\t\tnote = \"At 50 {npc:3032}, a shaman trainer on {area:1640} in {zone:1456}, asks for the four elements for {npc:6176}. Skyborne: Forever's quest page lists {quest:8410} and {quest:8412} for Orcs, Tauren and Trolls only; if {npc:3032} has nothing for you, {npc:6176}'s own {quest:8411} is open to every Horde race, but {quest:8412} after it may still turn you away.\",\n\t\tonly = { races = { \"Tauren\", \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 50 },\n\t\t\t{ t = \"accept\", quest = 8410, title = \"Elemental Mastery\", npc = 3032, npcName = \"Beram Skychaser\", minLevel = 50, qlvl = 50, closedBy = { 8411 }, endNpcs = { 6176 }, xp = 3800, preTitles = { [8411] = \"Mastering the Elements\" }, map = 1456, x = 22.19, y = 19.06, z = 138.1, spotsPacked = \"22.2,19.1,138.1,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The four elements\",\n\t\tnote = \"One each of {item:7069}, Fire, Earth and Water; all four trade, so the auction house is quickest. To farm them, {zone:1417} has the exiles at its stone circles (level 38-39, respawn under seven minutes): Thundering Exiles south-east of {area:320} (air), Rumbling Exiles south-west of it (earth) and Burning Exiles far to the north-west (fire), about one kill in eight to ten each, and Cresting Exiles at the {area:333} in the north-east (water, in about one in five of the corpses you can loot). Leave the {npc:2794} in the south-west alone: it is elite. Water also comes from the Patches of Elemental Water in {zone:1447} (two in five) or {npc:14269} by {area:69} in Redridge.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 8410, title = \"Elemental Mastery\", item = 7069, itemName = \"Elemental Air\", count = 1, oi = 1, map = 1417, x = 51.89, y = 50.62, z = 59.1, f = \"e\", spotsPacked = \"51.5,51.3,58.6,61,8;52.7,49.3,,43,4\", lvl = 39, note = \"{item:7069}: Thundering Exiles\", fromNpcs = { { npc = 2762, npcName = \"Thundering Exile\" } } },\n\t\t\t{ t = \"collect\", quest = 8410, title = \"Elemental Mastery\", item = 7068, itemName = \"Elemental Fire\", count = 1, oi = 2, map = 1417, x = 27.43, y = 31.39, z = 59.5, f = \"e\", spotsPacked = \"26.8,31.7,,25,3;25.3,30.1,40.4,69,11\", lvl = 39, note = \"{item:7068}: Burning Exiles\", fromNpcs = { { npc = 2760, npcName = \"Burning Exile\" } } },\n\t\t\t{ t = \"collect\", quest = 8410, title = \"Elemental Mastery\", item = 7067, itemName = \"Elemental Earth\", count = 1, oi = 3, map = 1417, x = 34.91, y = 55.92, z = 17.3, f = \"e\", spotsPacked = \"35.5,56.5,,36,5;35.5,60,23,44,5;37.2,58.4,,54,6\", lvl = 39, note = \"{item:7067}: Rumbling Exiles\", fromNpcs = { { npc = 2592, npcName = \"Rumbling Exile\" } } },\n\t\t\t{ t = \"collect\", quest = 8410, title = \"Elemental Mastery\", item = 7070, itemName = \"Elemental Water\", count = 1, oi = 4, map = 1417, x = 65, y = 30, f = \"e\", note = \"{item:7070}: Cresting Exiles, or {zone:1447}'s water patches\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6176}\",\n\t\tnote = \"{npc:6176} camps in the ruins of the east of {zone:1416}: from {area:272} follow the river east of town north into the hills.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 51 },\n\t\t\t{ t = \"turnin\", quest = 8410, title = \"Elemental Mastery\", npc = 6176, npcName = \"Bath'rah the Windwatcher\", map = 1416, x = 80.32, y = 66.86, z = 55.4, spotsPacked = \"79.83,64.72,,46,1\" },\n\t\t\t{ t = \"accept\", quest = 8412, title = \"Spirit Totem\", npc = 6176, npcName = \"Bath'rah the Windwatcher\", minLevel = 50, qlvl = 52, pre = { 8410, 8411 }, preTitles = { [8410] = \"Elemental Mastery\", [8411] = \"Mastering the Elements\" }, map = 1416, x = 80.32, y = 66.86, z = 55.4, spotsPacked = \"79.83,64.72,,46,1\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Spider eye and bear claw\",\n\t\tnote = \"Eight of each. Fly or ride to the {area:813} and on to the west edge of the {zone:1422}, north-west of {area:3197}: the Venom Mist Lurkers (level 50-51, they poison) give the {item:20610} and the Diseased Black Bears (level 51-52, {spell:3427}) the {item:20611}, one kill in five each; the two Carrion Vultures there drop either. The bigger Diseased Grizzlies and Plague Lurkers further east almost never drop them. A few bears and lurkers also roam south-east of {area:159} in Tirisfal.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 52 },\n\t\t\t{ t = \"collect\", quest = 8412, title = \"Spirit Totem\", item = 20610, itemName = \"Bloodshot Spider Eye\", count = 8, oi = 1, map = 1422, x = 31.08, y = 58.54, f = \"e\", spotsPacked = \"29.4,56.7,,74,4,,52;32,62.5,65.6,98,7,,52;33.9,58.3,,29,2;33.6,54.7,,28,2;35.2,64.42,,47,2;38.8,62.6,,55,3\", lvl = 51, fromNpcs = { { npc = 1809, npcName = \"Carrion Vulture\" }, { npc = 1822, npcName = \"Venom Mist Lurker\" } } },\n\t\t\t{ t = \"collect\", quest = 8412, title = \"Spirit Totem\", item = 20611, itemName = \"Thick Black Claw\", count = 8, oi = 2, map = 1422, x = 31.28, y = 60.13, z = 68.7, f = \"e\", spotsPacked = \"31.8,61.4,67.2,43,3;29,60.3,,43,2;32.6,56.4,,37,4;30.7,54.6,,44,4;34.55,64.86,,40;34.3,53.5,,29,2;34.8,58.8,66,15,1,1;38,62.8,70.5,70,5,1;36.9,66.5,70.3,53,4,1\", lvl = 52, fromNpcs = { { npc = 1815, npcName = \"Diseased Black Bear\" }, { npc = 1809, npcName = \"Carrion Vulture\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6176}\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 51 },\n\t\t\t{ t = \"turnin\", quest = 8412, title = \"Spirit Totem\", npc = 6176, npcName = \"Bath'rah the Windwatcher\", map = 1416, x = 80.32, y = 66.86, z = 55.4, spotsPacked = \"79.83,64.72,,46,1\" },\n\t\t\t{ t = \"accept\", quest = 8413, title = \"Da Voodoo\", npc = 6176, npcName = \"Bath'rah the Windwatcher\", minLevel = 50, qlvl = 52, pre = { 8412 }, preTitles = { [8412] = \"Spirit Totem\" }, map = 1416, x = 80.32, y = 66.86, z = 55.4, spotsPacked = \"79.83,64.72,,46,1\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {area:1417}\",\n\t\tnote = \"A five-player dungeon: needs a group of five, about level 50-55. Fly to {area:75} and ride east. The {area:1417} ({area:1477}) stands in the middle of the {area:74}: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. Two feathers of each colour, one from each of six elite troll mini-bosses (level 51-52) on the balconies around the temple's great round room, every kill, and each player on the quest loots their own: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Mijan heals the others ({spell:139}, a {npc:3560}): kill him first; Hukku summons guardians and throws Shadow Bolt Volleys.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 51 },\n\t\t\t{ t = \"collect\", quest = 8413, title = \"Da Voodoo\", item = 20606, itemName = \"Amber Voodoo Feather\", count = 2, oi = 1, map = 1435, x = 69.9, y = 53.6, f = \"e\", note = \"{item:20606}: Gasher, {npc:5716}\", group = { kind = \"group\", size = 5 } },\n\t\t\t{ t = \"collect\", quest = 8413, title = \"Da Voodoo\", item = 20607, itemName = \"Blue Voodoo Feather\", count = 2, oi = 2, map = 1435, x = 69.9, y = 53.6, f = \"e\", note = \"{item:20607}: Hukku, Mijan\", group = { kind = \"group\", size = 5 } },\n\t\t\t{ t = \"collect\", quest = 8413, title = \"Da Voodoo\", item = 20608, itemName = \"Green Voodoo Feather\", count = 2, oi = 3, map = 1435, x = 69.9, y = 53.6, f = \"e\", note = \"{item:20608}: Zolo, Loro\", group = { kind = \"group\", size = 5 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6176}\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 8413, title = \"Da Voodoo\", npc = 6176, npcName = \"Bath'rah the Windwatcher\", map = 1416, x = 80.32, y = 66.86, z = 55.4, spotsPacked = \"79.83,64.72,,46,1\", note = \"{npc:6176}: the old item choice may be gone, count on the experience\" },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

