	local function register()
		Polestar.RegisterGuide({
			id = "forever/class/warlock/felhunter-horde",
			pack = "guides",
			title = "Felhunter (Horde)",
			faction = "Horde",
			classes = { "WARLOCK" },
			minLevel = 30,
			maxLevel = 33,
			category = "Class",
			folder = "Warlock",
			keywords = { "Summon Felhunter", "Tome of the Cabal", "Seeking Strahad", "Strahad Farsan", "Jorah Annison", "Moldy Tome", "Tattered Manuscript", "Damaged Chest", "Rod of Channeling", "Reconstructed Tome", "Dragonmaw Bonewarder", "Dragonmaw Shadowwarder", "Angerfang Encampment", "The Binding", "Box of Souls", "Warlock", "class pet" },
			reward = { { spell = 691, spellName = "Summon Felhunter" }, { item = 22244, itemName = "Box of Souls" } },
			why = "The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards.",
			zone = 1413,
			zoneName = "The Barrens",
			author = "Polestar",
			version = 1,
			names = { ["area:1036"] = "Angerfang Encampment", ["area:271"] = "Southshore", ["area:287"] = "Hillsbrad", ["area:392"] = "Ratchet", ["area:484"] = "Freewind Post", ["area:881"] = "Thandol Span", ["item:22244"] = "Box of Souls", ["item:6931"] = "Moldy Tome", ["item:6997"] = "Tattered Manuscript", ["item:7006"] = "Reconstructed Tome", ["npc:5675"] = "Carendin Halgar", ["npc:5875"] = "Gan'rul Bloodeye", ["npc:6251"] = "Strahad Farsan", ["npc:6266"] = "Menara Voidrender", ["npc:6293"] = "Jorah Annison", ["object:172960"] = "Cleft of Shadow", ["object:172982"] = "Valley of Strength", ["object:36082"] = "Magic Quarter", ["object:92423"] = "Damaged Chest", ["quest:1795"] = "The Binding", ["quest:1801"] = "Tome of the Cabal", ["quest:1803"] = "Tome of the Cabal", ["quest:1804"] = "Tome of the Cabal", ["quest:2996"] = "Seeking Strahad", ["quest:3001"] = "Seeking Strahad", ["spell:691"] = "Summon Felhunter", ["zone:1411"] = "Durotar", ["zone:1417"] = "Arathi Highlands", ["zone:1420"] = "Tirisfal Glades", ["zone:1437"] = "Wetlands", ["zone:1441"] = "Thousand Needles", ["zone:1454"] = "Orgrimmar", ["zone:1458"] = "Undercity" },
			written = { ["At 30 {npc:5675}, in the {object:36082}, sends you to {npc:6251} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}. Take only one {quest:3001}: if {npc:6251} offers nothing, drop the duplicate from your log."] = "At 30 Carendin Halgar, in the Magic Quarter, sends you to Strahad Farsan in Ratchet. The zeppelin from Tirisfal Glades flies to Durotar. Take only one Seeking Strahad: if Strahad offers nothing, drop the duplicate from your log.", ["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "Back to Strahad in Ratchet. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the Tome of the Cabal on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon The Binding and take it again from Strahad. Keep the tome: Strahad takes it back.", ["Back to {npc:6293}"] = "Back to Jorah", ["{npc:6293} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods."] = "Jorah pieces the tome together and gives you the Reconstructed Tome: keep it, Strahad takes it with the rods." },
			stepCount = 9,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{quest:2996} ({zone:1454})\",\n\t\tnote = \"At 30 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:6251} in {area:392}.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 30 },\n\t\t\t{ t = \"accept\", quest = 2996, title = \"Seeking Strahad\", npc = 5875, npcName = \"Gan'rul Bloodeye\", minLevel = 30, qlvl = 30, closedBy = { 1801, 3001 }, endNpcs = { 6251 }, xp = 600, preTitles = { [1801] = \"Tome of the Cabal\", [3001] = \"Seeking Strahad\" }, map = 1454, x = 48.29, y = 45.5, z = -14.8, spotsPacked = \"48.3,45.5,-14.8,15,4\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:3001} ({zone:1458})\",\n\t\tnote = \"At 30 {npc:5675}, in the {object:36082}, sends you to {npc:6251} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}. Take only one {quest:3001}: if {npc:6251} offers nothing, drop the duplicate from your log.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 30 },\n\t\t\t{ t = \"accept\", quest = 3001, title = \"Seeking Strahad\", npc = 5675, npcName = \"Carendin Halgar\", minLevel = 30, qlvl = 30, closedBy = { 1801, 2996 }, endNpcs = { 6251 }, xp = 600, preTitles = { [1801] = \"Tome of the Cabal\", [2996] = \"Seeking Strahad\" }, map = 1458, x = 84.93, y = 26.02, z = -62.2, spotsPacked = \"84.9,26,-62.2,15,8\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6251}\",\n\t\tnote = \"{area:392}'s flight point is a short flight from {zone:1454}'s. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6293} in the {zone:1458}.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2996, title = \"Seeking Strahad\", npc = 6251, npcName = \"Strahad Farsan\", map = 1413, x = 62.58, y = 35.31, z = 40.5, only = { races = { \"Orc\", \"Troll\" } } },\n\t\t\t{ t = \"turnin\", quest = 3001, title = \"Seeking Strahad\", npc = 6251, npcName = \"Strahad Farsan\", map = 1413, x = 62.58, y = 35.31, z = 40.5, only = { races = { \"Scourge\" } } },\n\t\t\t{ t = \"accept\", quest = 1801, title = \"Tome of the Cabal\", npc = 6251, npcName = \"Strahad Farsan\", minLevel = 30, qlvl = 30, crumbs = { 2996, 3001 }, preTitles = { [2996] = \"Seeking Strahad\", [3001] = \"Seeking Strahad\" }, map = 1413, x = 62.58, y = 35.31, z = 40.5 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6293}\",\n\t\tnote = \"{npc:6293} is in the {object:36082} of the {zone:1458}. He wants two lost pieces of the {quest:1801}: one on the {area:287} coast, one in {zone:1441}.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1801, title = \"Tome of the Cabal\", npc = 6293, npcName = \"Jorah Annison\", map = 1458, x = 76.07, y = 37.52, z = -62.1, spotsPacked = \"76.1,37.5,-62.1,15,3\" },\n\t\t\t{ t = \"accept\", quest = 1803, title = \"Tome of the Cabal\", npc = 6293, npcName = \"Jorah Annison\", minLevel = 30, qlvl = 30, pre = { 1801 }, preTitles = { [1801] = \"Tome of the Cabal\" }, map = 1458, x = 75.96, y = 37.43, z = -62.1, spotsPacked = \"76.1,37.5,-62.1,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:6931}\",\n\t\tnote = \"The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1803, title = \"Tome of the Cabal\", item = 6931, itemName = \"Moldy Tome\", count = 1, oi = 1, map = 1424, x = 27.81, y = 72.79, z = 0.5, f = \"e\", spotsPacked = \"27.67,72.71,0.5,0;27.95,72.86,0.5,0\", note = \"{item:6931}, from the {quest:1803} on the sand\", from = \"Tome of the Cabal\", fromKind = \"object\", fromId = 92013 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:6997}\",\n\t\tnote = \"The centaur cave opens in the cliffs north of {area:484}. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1803, title = \"Tome of the Cabal\", item = 6997, itemName = \"Tattered Manuscript\", count = 1, oi = 2, map = 1441, x = 43.44, y = 32.61, z = -49.1, f = \"e\", note = \"{item:6997}, in the {object:92423}\", from = \"Damaged Chest\", fromKind = \"object\", fromId = 92423 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:6293}\",\n\t\tnote = \"{npc:6293} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1803, title = \"Tome of the Cabal\", npc = 6293, npcName = \"Jorah Annison\", map = 1458, x = 76.07, y = 37.52, z = -62.1, spotsPacked = \"76.1,37.5,-62.1,15,3\" },\n\t\t\t{ t = \"accept\", quest = 1805, title = \"Tome of the Cabal\", npc = 6293, npcName = \"Jorah Annison\", minLevel = 30, qlvl = 30, pre = { 1803 }, preTitles = { [1803] = \"Tome of the Cabal\" }, map = 1458, x = 75.96, y = 37.43, z = -62.1, spotsPacked = \"76.1,37.5,-62.1,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Rods of Channeling\",\n\t\tnote = \"The Dragonmaw hold {area:1036} in the hills east of the road through the {zone:1437}, south of the {area:881} you cross from {zone:1417}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1805, title = \"Tome of the Cabal\", item = 6930, itemName = \"Rod of Channeling\", count = 3, oi = 1, map = 1437, x = 52.38, y = 52.64, f = \"e\", spotsPacked = \"53.1,54.2,,32,4,,29;50.75,50.05,,30,1;51.7,49,54.3,18,2;48.9,46.41,52.3,29,3;46.1,46.4,,38,4;45.6,42.9,51.9,15,2\", lvl = 28, note = \"Rods of Channeling, from the Dragonmaw casters\", from = \"Dragonmaw Shadowwarder\", fromKind = \"npc\", fromAlso = \"Dragonmaw Bonewarder\", fromId = 1038, fromAlsoId = 1057, fromNpcs = { { npc = 1038, npcName = \"Dragonmaw Shadowwarder\" }, { npc = 1057, npcName = \"Dragonmaw Bonewarder\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1795}\",\n\t\tnote = \"Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1805, title = \"Tome of the Cabal\", npc = 6251, npcName = \"Strahad Farsan\", map = 1413, x = 62.58, y = 35.31, z = 40.5 },\n\t\t\t{ t = \"accept\", quest = 1795, title = \"The Binding\", npc = 6251, npcName = \"Strahad Farsan\", minLevel = 30, qlvl = 30, pre = { 1805, 1804 }, preTitles = { [1804] = \"Tome of the Cabal\", [1805] = \"Tome of the Cabal\" }, map = 1413, x = 62.58, y = 35.31, z = 40.5 },\n\t\t\t{ t = \"use\", item = 6999, itemName = \"Tome of the Cabal\", map = 1413, x = 62.6, y = 35.3, f = \"e\", note = \"{quest:1804}, on the circle\" },\n\t\t\t{ t = \"kill\", quest = 1795, title = \"The Binding\", target = \"Summoned Felhunter\", npc = 6268, count = 1, oi = 1, map = 1413, x = 62.6, y = 35.31, f = \"e\" },\n\t\t\t{ t = \"turnin\", quest = 1795, title = \"The Binding\", npc = 6251, npcName = \"Strahad Farsan\", map = 1413, x = 62.58, y = 35.31, z = 40.5, note = \"{npc:6251}: {spell:691}\" },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

-- Source: forever/class/warlock/imp-horde.guide
do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/class/warlock/imp-horde",
			pack = "guides",
			title = "Imp (Horde)",
			faction = "Horde",
			classes = { "WARLOCK" },
			minLevel = 1,
			maxLevel = 4,
			category = "Class",
			folder = "Warlock",
			keywords = { "Summon Imp", "Vile Familiars", "Piercing the Veil", "Ruzan", "Zureetha Fargaze", "Venya Marthand", "Vile Familiar Head", "Rattlecage Skull", "Burning Blade Coven", "Deathknell", "Tainted Parchment", "Tainted Tablet", "Tainted Scroll", "Primitive Hand Blade", "Primitive Walking Stick", "Warlock", "class pet" },
			reward = { { spell = 688, spellName = "Summon Imp" }, { item = 4925, itemName = "Primitive Hand Blade", choice = true }, { item = 5778, itemName = "Primitive Walking Stick", choice = true } },
			why = "Your first demon at level 1-4: the imp, with a starter blade or staff for Orcs and Trolls.",
			zone = 1411,
			zoneName = "Durotar",
			author = "Polestar",
			version = 1,
			names = { ["area:154"] = "Deathknell", ["area:363"] = "Valley of Trials", ["area:365"] = "Burning Blade Coven", ["item:282346"] = "Tainted Tablet", ["item:6281"] = "Rattlecage Skull", ["item:6487"] = "Vile Familiar Head", ["item:9578"] = "Tainted Scroll", ["item:9579"] = "Tainted Parchment", ["npc:1569"] = "Shadow Priest Sarvis", ["npc:1890"] = "Rattlecage Skeleton", ["npc:3145"] = "Zureetha Fargaze", ["npc:5667"] = "Venya Marthand", ["npc:5765"] = "Ruzan", ["quest:1485"] = "Vile Familiars", ["spell:688"] = "Summon Imp" },
			written = { ["{npc:5667} teaches you {spell:688} when you hand in the skulls: summon it right away, it costs nothing and fights beside you."] = "Venya teaches you Summon Imp when you hand in the skulls: summon it right away, it costs nothing and fights beside you." },
			stepCount = 6,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:5765} (Orcs and Trolls)\",\n\t\tnote = \"Your first letter ({item:9579} for Orcs, {item:282346} for Trolls, from Gornek after Cutting Teeth) points you to Nartok, the warlock trainer in the Den. {npc:5765} stands just outside the Den in the {area:363} and asks for six Vile Familiar Heads.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 3 },\n\t\t\t{ t = \"accept\", quest = 1485, title = \"Vile Familiars\", npc = 5765, npcName = \"Ruzan\", minLevel = 1, qlvl = 4, closedBy = { 1470 }, endNpcs = { 5765 }, xp = 360, preTitles = { [1470] = \"Piercing the Veil\" }, map = 1411, x = 42.56, y = 68.89, z = 38.2 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1485}\",\n\t\tnote = \"The {quest:1485} (level 3-4) swarm the {area:365}, the cave north of the Den, inside and around its mouth. Almost every kill drops a head (80%), so about eight kills does it; they throw small fireballs, so pull them one at a time. They respawn in just over three minutes. Other classes hunt the same imps for their own {quest:1485} quest.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 4 },\n\t\t\t{ t = \"collect\", quest = 1485, title = \"Vile Familiars\", item = 6487, itemName = \"Vile Familiar Head\", count = 6, oi = 1, map = 1411, x = 43.82, y = 58.29, z = 61.6, f = \"e\", spotsPacked = \"44.2,58.4,,21,2;44.7,57.1,68.3,44,6;45.5,55.8,67.1,37,4;46.1,57.3,,49,6;43.7,54.1,62.8,71,15\", lvl = 4, note = \"Vile Familiar Heads\", from = \"Vile Familiar\", fromKind = \"npc\", fromId = 3101, fromNpcs = { { npc = 3101, npcName = \"Vile Familiar\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{spell:688}\",\n\t\tnote = \"{npc:5765} teaches you {spell:688} when you hand in the heads: summon it right away, it costs nothing and fights beside you. Then speak with {npc:3145} a few steps away for a starter weapon.\",\n\t\tonly = { races = { \"Orc\", \"Troll\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1485, title = \"Vile Familiars\", npc = 5765, npcName = \"Ruzan\", map = 1411, x = 42.56, y = 68.89, z = 38.2, note = \"{npc:5765}: {spell:688}\" },\n\t\t\t{ t = \"accept\", quest = 1499, title = \"Vile Familiars\", npc = 5765, npcName = \"Ruzan\", minLevel = 1, qlvl = 4, pre = { 1470, 1485 }, preTitles = { [1470] = \"Piercing the Veil\", [1485] = \"Vile Familiars\" }, map = 1411, x = 42.56, y = 68.89, z = 38.2 },\n\t\t\t{ t = \"turnin\", quest = 1499, title = \"Vile Familiars\", npc = 3145, npcName = \"Zureetha Fargaze\", map = 1411, x = 42.76, y = 69.07, z = 38.2, rewards = { choices = { { item = 4925, itemName = \"Primitive Hand Blade\" }, { item = 5778, itemName = \"Primitive Walking Stick\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5667} (Undead)\",\n\t\tnote = \"Your first letter ({item:9578}, from {npc:1569} after The Mindless Ones) points you to Maximillion, the warlock trainer in {area:154}. {npc:5667} waits inside the building beside him and asks for three Rattlecage Skulls.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 2 },\n\t\t\t{ t = \"accept\", quest = 1470, title = \"Piercing the Veil\", npc = 5667, npcName = \"Venya Marthand\", minLevel = 1, qlvl = 3, closedBy = { 1485 }, endNpcs = { 5667 }, xp = 190, preTitles = { [1485] = \"Vile Familiars\" }, map = 1420, x = 30.95, y = 66.33, z = 97 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Rattlecage Skulls\",\n\t\tnote = \"The Rattlecage Skeletons (level 2-3) stand around the old smithy buildings just north of {area:154}, often right against the walls. Four kills in five drop a skull, so plan on about five; twenty of them spawn there and each comes back after five minutes.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 3 },\n\t\t\t{ t = \"collect\", quest = 1470, title = \"Piercing the Veil\", item = 6281, itemName = \"Rattlecage Skull\", count = 3, oi = 1, map = 1420, x = 32.98, y = 63, z = 90.2, f = \"e\", spotsPacked = \"33.5,62,87.2,44,7;34.4,64.7,88,15,3;32.2,60.4,74,55,9\", lvl = 3, note = \"Rattlecage Skulls\", from = \"Rattlecage Skeleton\", fromKind = \"npc\", fromId = 1890, fromNpcs = { { npc = 1890, npcName = \"Rattlecage Skeleton\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{spell:688}\",\n\t\tnote = \"{npc:5667} teaches you {spell:688} when you hand in the skulls: summon it right away, it costs nothing and fights beside you.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1470, title = \"Piercing the Veil\", npc = 5667, npcName = \"Venya Marthand\", map = 1420, x = 30.95, y = 66.33, z = 97, note = \"{npc:5667}: {spell:688}\" },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

-- Source: forever/class/warlock/incubus-horde.guide
do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/class/warlock/incubus-horde",
			pack = "guides",
			title = "Succubus and Incubus (Horde)",
			faction = "Horde",
			classes = { "WARLOCK" },
			minLevel = 20,
			maxLevel = 28,
			category = "Class",
			folder = "Warlock",
			keywords = { "Summon Succubus", "Summon Incubus", "sayaad", "Devourer of Souls", "Blind Cazul", "News of Dogran", "Ken'zigla's Draught", "Dogran's Captivity", "Love's Gift", "Hearts of the Pure", "Love Hurts", "Wish You Were Here", "Hearts of the Lovers", "The Binding", "Gan'rul Bloodeye", "Cazul", "Zankaja", "Gazrog", "Ken'zigla", "Malaka'jin", "Grunt Logmar", "Grunt Dogran", "Dogran's Pendant", "Magar", "Krilge", "Withered Scarf", "Fallen Sky Lake", "Carendin Halgar", "Godrick Farsan", "Dalin Forgewright", "Corma Villard", "Avelina Lilly", "Isaac Pearson", "Ambermill", "Ratchet", "Small Soul Pouch", "Warlock", "class pet" },
			reward = { { spell = 712, spellName = "Summon Succubus" }, { spell = 713, spellName = "Summon Incubus" }, { item = 22243, itemName = "Small Soul Pouch" } },
			why = "At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards.",
			zone = 1454,
			zoneName = "Orgrimmar",
			author = "Polestar",
			version = 1,
			names = { ["area:230"] = "Greymane Wall", ["area:233"] = "Ambermill", ["area:2539"] = "Malaka'jin", ["area:279"] = "Dalaran", ["area:287"] = "Hillsbrad", ["area:378"] = "Camp Taurajo", ["area:392"] = "Ratchet", ["area:422"] = "Fallen Sky Lake", ["area:431"] = "Splintertree Post", ["area:881"] = "Thandol Span", ["item:190181"] = "Lovers' Hearts", ["item:190232"] = "Withered Scarf", ["item:6286"] = "Pure Hearts", ["item:6626"] = "Dogran's Pendant", ["npc:185333"] = "Avelina Lilly", ["npc:185334"] = "Isaac Pearson", ["npc:185335"] = "Summoned Incubus", ["npc:3216"] = "Neeru Fireblade", ["npc:3363"] = "Magar", ["npc:3464"] = "Gazrog", ["npc:3782"] = "Shadethicket Stone Mover", ["npc:3931"] = "Shadethicket Oracle", ["npc:4197"] = "Ken'zigla", ["npc:5675"] = "Carendin Halgar", ["npc:5682"] = "Dalin Forgewright", ["npc:5693"] = "Godrick Farsan", ["npc:5875"] = "Gan'rul Bloodeye", ["npc:5908"] = "Grunt Dogran", ["npc:5909"] = "Cazul", ["npc:5910"] = "Zankaja", ["npc:5911"] = "Grunt Logmar", ["object:1661"] = "The Undercity", ["object:172960"] = "Cleft of Shadow", ["object:172982"] = "Valley of Strength", ["object:173018"] = "Magar's Cloth Goods", ["object:36082"] = "Magic Quarter", ["quest:1472"] = "Devourer of Souls", ["quest:1474"] = "The Binding", ["quest:1507"] = "Devourer of Souls", ["quest:1513"] = "The Binding", ["quest:65597"] = "The Binding", ["quest:65604"] = "The Binding", ["spell:712"] = "Summon Succubus", ["spell:713"] = "Summon Incubus", ["zone:1411"] = "Durotar", ["zone:1413"] = "Barrens", ["zone:1417"] = "Arathi Highlands", ["zone:1437"] = "Wetlands", ["zone:1440"] = "Ashenvale", ["zone:1442"] = "Stonetalon Mountains", ["zone:1454"] = "Orgrimmar", ["zone:1458"] = "Undercity" },
			written = { ["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers start these demons, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one; this guide follows whichever {quest:1507} you took. {npc:5909} offers both of {zone:1454}'s branches: take both."] = "At 20 Gan'rul Bloodeye, in the Cleft of Shadow under the Valley of Strength, sends you to Cazul a few steps away. Two trainers start these demons, Gan'rul here and Carendin Halgar in the Undercity, and you can take only one; this guide follows whichever Devourer of Souls you took. Cazul offers both of Orgrimmar's branches: take both.", ["Back to {npc:5675} with Dalin's and Corma's hearts. He hands you the {item:6286}: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, {npc:5675} takes them back."] = "Back to Carendin with Dalin's and Corma's hearts. He hands you the Pure Hearts: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, Carendin takes them back.", ["Back to {npc:5675} with the lovers' hearts, then place the {item:190181} on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: {npc:5675} takes them back."] = "Back to Carendin with the lovers' hearts, then place the Lovers' Hearts on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: Carendin takes them back.", ["Back to {npc:5875} with the pendant. He hands you {item:6626}: take it across the {object:172960} to {npc:3216}'s tent, stand on the purple circle and use it. Summon your voidwalker first and let it tank: the succubus (level 20, not elite) charms and lashes; keep your damage over time on her. If she wins, use the pendant again. Keep the pendant: {npc:5875} takes it back."] = "Back to Gan'rul with the pendant. He hands you Dogran's Pendant: take it across the Cleft of Shadow to Neeru Fireblade's tent, stand on the purple circle and use it. Summon your voidwalker first and let it tank: the succubus (level 20, not elite) charms and lashes; keep your damage over time on her. If she wins, use the pendant again. Keep the pendant: Gan'rul takes it back.", ["Back to {npc:5875} with the scarf, then use the {item:190232} on the same circle in Neeru's tent and defeat the incubus it calls (level 20, not elite) with your voidwalker tanking. Keep the scarf: {npc:5875} takes it back."] = "Back to Gan'rul with the scarf, then use the Withered Scarf on the same circle in Neeru's tent and defeat the incubus it calls (level 20, not elite) with your voidwalker tanking. Keep the scarf: Gan'rul takes it back.", ["{item:6286}, on the circle below {npc:5675}"] = "Pure Hearts, on the circle below Carendin", ["{npc:185335}, at the circle below {npc:5675}"] = "Summoned Incubus, at the circle below Carendin", ["{npc:5911} stands at {area:378}, south down the road from the Crossroads. He sends you north to the quilboar camp where Dogran is held: the camp with two huts side by side, north-west of a decoy camp whose huts stand apart. A rare level 22 elite quilboar sometimes guards the huts: send your voidwalker in, sacrifice it if you must, and talk to Dogran. He gives you a pendant for {npc:5875}. Keep it."] = "Grunt Logmar stands at Camp Taurajo, south down the road from the Crossroads. He sends you north to the quilboar camp where Dogran is held: the camp with two huts side by side, north-west of a decoy camp whose huts stand apart. A rare level 22 elite quilboar sometimes guards the huts: send your voidwalker in, sacrifice it if you must, and talk to Dogran. He gives you a pendant for Gan'rul. Keep it.", ["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} close by. {npc:5693} shows you an image of each quarry and offers both branches: take both."] = "The Undercity's version, for warlocks who took Carendin Halgar's Devourer of Souls instead of Gan'rul's. At 20 Carendin, in the Magic Quarter, sends you to Godrick Farsan close by. Godrick shows you an image of each quarry and offers both branches: take both." },
			stepCount = 15,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{quest:1507} ({zone:1454})\",\n\t\tnote = \"At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers start these demons, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one; this guide follows whichever {quest:1507} you took. {npc:5909} offers both of {zone:1454}'s branches: take both.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 20 },\n\t\t\t{ t = \"accept\", quest = 1507, title = \"Devourer of Souls\", npc = 5875, npcName = \"Gan'rul Bloodeye\", minLevel = 20, qlvl = 20, closedBy = { 1472 }, endNpcs = { 5909 }, xp = 160, preTitles = { [1472] = \"Devourer of Souls\" }, map = 1454, x = 48.29, y = 45.5, z = -14.8, spotsPacked = \"48.3,45.5,-14.8,15,4\" },\n\t\t\t{ t = \"turnin\", quest = 1507, title = \"Devourer of Souls\", npc = 5909, npcName = \"Cazul\", map = 1454, x = 47.36, y = 46.65, z = -15.4, spotsPacked = \"47.2,46.6,-15.4,15,2\" },\n\t\t\t{ t = \"accept\", quest = 1508, title = \"Blind Cazul\", npc = 5909, npcName = \"Cazul\", minLevel = 20, qlvl = 20, pre = { 1507 }, closedBy = { 1472 }, endNpcs = { 5910 }, xp = 390, preTitles = { [1472] = \"Devourer of Souls\", [1507] = \"Devourer of Souls\" }, map = 1454, x = 47.36, y = 46.65, z = -15.4, spotsPacked = \"47.2,46.6,-15.4,15,2\", note = \"the succubus\" },\n\t\t\t{ t = \"accept\", quest = 65601, title = \"Love Hurts\", npc = 5909, npcName = \"Cazul\", minLevel = 20, qlvl = 20, pre = { 1507 }, closedBy = { 1472 }, endNpcs = { 3363 }, xp = 390, preTitles = { [1472] = \"Devourer of Souls\", [1507] = \"Devourer of Souls\" }, map = 1454, x = 47.36, y = 46.65, z = -15.4, spotsPacked = \"47.2,46.6,-15.4,15,2\", note = \"the incubus\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5910}\",\n\t\tnote = \"{npc:5910} lives in a hut up on the cliffs on the west side of the city, above the {object:172982}: climb the wind rider tower, cross the bridge at its top to the west and turn right off it. She sends you to the Crossroads.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1508, title = \"Blind Cazul\", npc = 5910, npcName = \"Zankaja\", map = 1454, x = 37.08, y = 59.36, z = 51.7, spotsPacked = \"37.1,59.5,51.7,15,2\" },\n\t\t\t{ t = \"accept\", quest = 1509, title = \"News of Dogran\", npc = 5910, npcName = \"Zankaja\", minLevel = 20, qlvl = 20, pre = { 1508 }, closedBy = { 1472 }, endNpcs = { 3464 }, xp = 390, preTitles = { [1472] = \"Devourer of Souls\", [1508] = \"Blind Cazul\" }, map = 1454, x = 37.08, y = 59.36, z = 51.7, spotsPacked = \"37.1,59.5,51.7,15,2\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:3363}\",\n\t\tnote = \"{npc:3363} keeps {object:173018} on the main street east of the {object:172960}. He asks you to look for his mate Krilge in {zone:1440}.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 26 },\n\t\t\t{ t = \"turnin\", quest = 65601, title = \"Love Hurts\", npc = 3363, npcName = \"Magar\", map = 1454, x = 63.27, y = 50.01, z = 22.9, spotsPacked = \"63.4,50,22.9,15,4\" },\n\t\t\t{ t = \"accept\", quest = 65610, title = \"Wish You Were Here\", npc = 3363, npcName = \"Magar\", minLevel = 20, qlvl = 27, pre = { 65601 }, closedBy = { 1472 }, endNpcs = { 5875 }, xp = 2200, preTitles = { [1472] = \"Devourer of Souls\", [65601] = \"Love Hurts\" }, map = 1454, x = 63.27, y = 50.01, z = 22.9, spotsPacked = \"63.4,50,22.9,15,4\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:3464}\",\n\t\tnote = \"{npc:3464} waits in front of the inn at the Crossroads. He sends you on to {npc:4197} at {area:2539}, in {zone:1442}.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1509, title = \"News of Dogran\", npc = 3464, npcName = \"Gazrog\", map = 1413, x = 51.89, y = 30.31, z = 96.4 },\n\t\t\t{ t = \"accept\", quest = 1510, title = \"News of Dogran\", npc = 3464, npcName = \"Gazrog\", minLevel = 20, qlvl = 20, pre = { 1509 }, closedBy = { 1472 }, endNpcs = { 4197 }, xp = 775, preTitles = { [1472] = \"Devourer of Souls\", [1509] = \"News of Dogran\" }, map = 1413, x = 51.89, y = 30.31, z = 96.4 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:4197}\",\n\t\tnote = \"Take the road west from the Crossroads into {zone:1442} and, just past the border, the faint trail up to the left (south): {area:2539} cannot be reached from the main road. {npc:4197} hands you her draught for {npc:5911}.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1510, title = \"News of Dogran\", npc = 4197, npcName = \"Ken'zigla\", map = 1442, x = 73.17, y = 95.06, z = 9.8, note = \"{npc:4197}, {area:2539}\" },\n\t\t\t{ t = \"accept\", quest = 1511, title = \"Ken'zigla's Draught\", npc = 4197, npcName = \"Ken'zigla\", minLevel = 20, qlvl = 20, pre = { 1510 }, closedBy = { 1472 }, endNpcs = { 5911 }, xp = 1550, preTitles = { [1472] = \"Devourer of Souls\", [1510] = \"News of Dogran\" }, map = 1442, x = 73.17, y = 95.06, z = 9.8 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5908}\",\n\t\tnote = \"{npc:5911} stands at {area:378}, south down the road from the Crossroads. He sends you north to the quilboar camp where Dogran is held: the camp with two huts side by side, north-west of a decoy camp whose huts stand apart. A rare level 22 elite quilboar sometimes guards the huts: send your voidwalker in, sacrifice it if you must, and talk to Dogran. He gives you a pendant for {npc:5875}. Keep it.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1511, title = \"Ken'zigla's Draught\", npc = 5911, npcName = \"Grunt Logmar\", map = 1413, x = 44.58, y = 59.22, z = 96, note = \"{npc:5911}, {area:378}\" },\n\t\t\t{ t = \"accept\", quest = 1515, title = \"Dogran's Captivity\", npc = 5911, npcName = \"Grunt Logmar\", minLevel = 20, qlvl = 20, pre = { 1511 }, closedBy = { 1472 }, endNpcs = { 5908 }, xp = 1150, preTitles = { [1472] = \"Devourer of Souls\", [1511] = \"Ken'zigla's Draught\" }, map = 1413, x = 44.58, y = 59.22, z = 96 },\n\t\t\t{ t = \"turnin\", quest = 1515, title = \"Dogran's Captivity\", npc = 5908, npcName = \"Grunt Dogran\", map = 1413, x = 43.31, y = 47.88, z = 91.8 },\n\t\t\t{ t = \"accept\", quest = 1512, title = \"Love's Gift\", npc = 5908, npcName = \"Grunt Dogran\", minLevel = 20, qlvl = 20, pre = { 1515 }, closedBy = { 1472 }, endNpcs = { 5875 }, xp = 390, preTitles = { [1472] = \"Devourer of Souls\", [1515] = \"Dogran's Captivity\" }, map = 1413, x = 43.31, y = 47.88, z = 91.8 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1513}: succubus ({zone:1454})\",\n\t\tnote = \"Back to {npc:5875} with the pendant. He hands you {item:6626}: take it across the {object:172960} to {npc:3216}'s tent, stand on the purple circle and use it. Summon your voidwalker first and let it tank: the succubus (level 20, not elite) charms and lashes; keep your damage over time on her. If she wins, use the pendant again. Keep the pendant: {npc:5875} takes it back.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1512, title = \"Love's Gift\", npc = 5875, npcName = \"Gan'rul Bloodeye\", map = 1454, x = 48.29, y = 45.5, z = -14.8, spotsPacked = \"48.3,45.5,-14.8,15,4\" },\n\t\t\t{ t = \"accept\", quest = 1513, title = \"The Binding\", npc = 5875, npcName = \"Gan'rul Bloodeye\", minLevel = 20, qlvl = 20, pre = { 1512 }, closedBy = { 1472 }, endNpcs = { 5875 }, xp = 1150, preTitles = { [1472] = \"Devourer of Souls\", [1512] = \"Love's Gift\" }, map = 1454, x = 48.25, y = 45.34, z = -14.8, spotsPacked = \"48.3,45.5,-14.8,15,4\" },\n\t\t\t{ t = \"use\", item = 6626, itemName = \"Dogran's Pendant\", map = 1454, x = 49.4, y = 50, f = \"e\", note = \"{item:6626}, on the circle in Neeru's tent\" },\n\t\t\t{ t = \"kill\", quest = 1513, title = \"The Binding\", target = \"Summoned Succubus\", npc = 5677, count = 1, oi = 1, map = 1454, x = 49.43, y = 50.04, f = \"e\" },\n\t\t\t{ t = \"turnin\", quest = 1513, title = \"The Binding\", npc = 5875, npcName = \"Gan'rul Bloodeye\", map = 1454, x = 48.22, y = 45.87, z = -14.8, spotsPacked = \"48.3,45.5,-14.8,15,4\", note = \"{npc:5875}: {spell:712}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{area:422}\",\n\t\tnote = \"{area:422} lies in southern {zone:1440}, south-west of {area:431}. The Shadethicket Stone Movers and Bark Rippers (level 25-27) around the lake drop the {item:190232} about one time in twenty, and the lone {npc:3931} (30) can drop it too: plan on a good number of kills, so the guide waits for level 27 first (Forever made this quest level 27); with the succubus already bound you can leave it for your 20s leveling in {zone:1440}. They respawn in five minutes.\",\n\t\twhen = { { k = \"onquest\", q = { 65610 } } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 27 },\n\t\t\t{ t = \"collect\", quest = 65610, title = \"Wish You Were Here\", item = 190232, itemName = \"Withered Scarf\", count = 1, oi = 1, map = 1440, x = 72.4, y = 68.06, f = \"e\", spotsPacked = \"68.6,62.9,97.6,49,1,,26;65,66.5,,50,2,,26;63,71.6,84.6,49,1;59.5,78.9,,49,5;66.8,84,92.1,49,2;79.6,72.4,,90,4;79.2,65.6,,49,2;79,57.9,138.3,49,1,,26;78.7,53.5,158.5,49,1,,26;74.7,46.5,217.6,49,1;71.3,55.3,,53,3;85.6,68.3,75.5,49,4;66.6,64.4,93.6,49,1,1,26;69.8,59.1,,49,2,1;78.4,61.3,124.3,64,3,1,26;81.4,63.4,106.5,63,3,1;66.4,80.9,,74,11,1;84.1,64.9,89.9,49,1,1;61.4,75.8,,49,2,1\", spread = true, lvl = 27, fromNpcs = { { npc = 3782, npcName = \"Shadethicket Stone Mover\" }, { npc = 3784, npcName = \"Shadethicket Bark Ripper\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:65604}: incubus ({zone:1454})\",\n\t\tnote = \"Back to {npc:5875} with the scarf, then use the {item:190232} on the same circle in Neeru's tent and defeat the incubus it calls (level 20, not elite) with your voidwalker tanking. Keep the scarf: {npc:5875} takes it back.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 65610, title = \"Wish You Were Here\", npc = 5875, npcName = \"Gan'rul Bloodeye\", map = 1454, x = 48.29, y = 45.5, z = -14.8, spotsPacked = \"48.3,45.5,-14.8,15,4\" },\n\t\t\t{ t = \"accept\", quest = 65604, title = \"The Binding\", npc = 5875, npcName = \"Gan'rul Bloodeye\", minLevel = 20, qlvl = 20, pre = { 65610 }, closedBy = { 1472 }, endNpcs = { 5875 }, xp = 1150, preTitles = { [1472] = \"Devourer of Souls\", [65610] = \"Wish You Were Here\" }, map = 1454, x = 48.25, y = 45.34, z = -14.8, spotsPacked = \"48.3,45.5,-14.8,15,4\" },\n\t\t\t{ t = \"kill\", quest = 65604, title = \"The Binding\", target = \"Summoned Incubus\", npc = 185335, count = 1, oi = 1, map = 1454, x = 49.43, y = 50.04, f = \"e\", note = \"{npc:185335}, at the circle in Neeru's tent\" },\n\t\t\t{ t = \"turnin\", quest = 65604, title = \"The Binding\", npc = 5875, npcName = \"Gan'rul Bloodeye\", map = 1454, x = 48.22, y = 45.87, z = -14.8, spotsPacked = \"48.3,45.5,-14.8,15,4\", note = \"{npc:5875}: {spell:713}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1472} ({zone:1458})\",\n\t\tnote = \"{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} close by. {npc:5693} shows you an image of each quarry and offers both branches: take both.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 20 },\n\t\t\t{ t = \"accept\", quest = 1472, title = \"Devourer of Souls\", npc = 5675, npcName = \"Carendin Halgar\", minLevel = 20, qlvl = 20, closedBy = { 1507 }, endNpcs = { 5693 }, xp = 160, preTitles = { [1507] = \"Devourer of Souls\" }, map = 1458, x = 84.93, y = 26.02, z = -62.2, spotsPacked = \"84.9,26,-62.2,15,8\" },\n\t\t\t{ t = \"turnin\", quest = 1472, title = \"Devourer of Souls\", npc = 5693, npcName = \"Godrick Farsan\", map = 1458, x = 84.87, y = 15.03, z = -61.4, spotsPacked = \"85,14.7,-61.4,15,3\" },\n\t\t\t{ t = \"accept\", quest = 1476, title = \"Hearts of the Pure\", npc = 5693, npcName = \"Godrick Farsan\", minLevel = 20, qlvl = 20, pre = { 1472 }, closedBy = { 1507 }, endNpcs = { 5675 }, xp = 1550, preTitles = { [1472] = \"Devourer of Souls\", [1507] = \"Devourer of Souls\" }, map = 1458, x = 84.87, y = 15.03, z = -61.4, spotsPacked = \"85,14.7,-61.4,15,3\", note = \"the succubus\" },\n\t\t\t{ t = \"accept\", quest = 65593, title = \"Hearts of the Lovers\", npc = 5693, npcName = \"Godrick Farsan\", minLevel = 20, qlvl = 20, pre = { 1472 }, closedBy = { 1507 }, endNpcs = { 5675 }, xp = 1550, preTitles = { [1472] = \"Devourer of Souls\", [1507] = \"Devourer of Souls\" }, map = 1458, x = 84.87, y = 15.03, z = -61.4, spotsPacked = \"85,14.7,-61.4,15,3\", note = \"the incubus\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Silverpine hearts\",\n\t\tnote = \"{npc:185333} (level 22) works as a tailor for the {area:279} wizards at {area:233}, in eastern Silverpine: the wizards around her are hostile. {npc:5682} (level 20, not elite) patrols near the {area:230} in the far south. Both are Alliance-friendly humans: attacking them can flag you for PvP. Each drops her or his heart.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 22 },\n\t\t\t{ t = \"collect\", quest = 65593, title = \"Hearts of the Lovers\", item = 190179, itemName = \"Avelina's Heart\", count = 1, oi = 1, map = 1421, x = 62.54, y = 64.86, f = \"e\", spotsPacked = \"62.8,64.3,,64,9;61.8,66.7,,21,3\", lvl = 22, from = \"Avelina Lilly\", fromKind = \"npc\", fromFaction = \"A\", fromId = 185333, fromNpcs = { { npc = 185333, npcName = \"Avelina Lilly\" } } },\n\t\t\t{ t = \"collect\", quest = 1476, title = \"Hearts of the Pure\", item = 6312, itemName = \"Dalin's Heart\", count = 1, oi = 1, map = 1421, x = 45.6, y = 84.91, f = \"e\", spotsPacked = \"45.6,84.91,,24;47.6,85.65,15.1,15,1,1,20\", from = \"Dalin Forgewright\", fromKind = \"npc\", fromFaction = \"A\", fromId = 5682, fromNpcs = { { npc = 5682, npcName = \"Dalin Forgewright\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Corma Villard\",\n\t\tnote = \"Corma Villard (level 22, not elite; Comar in older records) wanders the north of the {zone:1437} just past the {area:881}, to the right as you come off the bridge. From the {zone:1458} head through {area:287} and {zone:1417}, where the mobs are 30 and up. Attacking her flags you for PvP.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 22 },\n\t\t\t{ t = \"collect\", quest = 1476, title = \"Hearts of the Pure\", item = 6313, itemName = \"Corma's Heart\", count = 1, oi = 2, map = 1437, x = 49.93, y = 12.55, z = 79.3, f = \"e\", from = \"Comar Villard\", fromKind = \"npc\", fromFaction = \"A\", fromId = 5683, fromNpcs = { { npc = 5683, npcName = \"Comar Villard\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1474}: succubus ({zone:1458})\",\n\t\tnote = \"Back to {npc:5675} with Dalin's and Corma's hearts. He hands you the {item:6286}: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, {npc:5675} takes them back.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1476, title = \"Hearts of the Pure\", npc = 5675, npcName = \"Carendin Halgar\", map = 1458, x = 84.93, y = 26.02, z = -62.2, spotsPacked = \"84.9,26,-62.2,15,8\" },\n\t\t\t{ t = \"accept\", quest = 1474, title = \"The Binding\", npc = 5675, npcName = \"Carendin Halgar\", minLevel = 20, qlvl = 20, pre = { 1476 }, closedBy = { 1507 }, endNpcs = { 5675 }, xp = 1550, preTitles = { [1476] = \"Hearts of the Pure\", [1507] = \"Devourer of Souls\" }, map = 1458, x = 84.88, y = 26.23, z = -62.2, spotsPacked = \"84.9,26,-62.2,15,8\" },\n\t\t\t{ t = \"use\", item = 6286, itemName = \"Pure Hearts\", map = 1458, x = 86.6, y = 27.1, f = \"e\", note = \"{item:6286}, on the circle below {npc:5675}\" },\n\t\t\t{ t = \"kill\", quest = 1474, title = \"The Binding\", target = \"Summoned Succubus\", npc = 5677, count = 1, oi = 1, map = 1458, x = 86.62, y = 27.05, f = \"e\" },\n\t\t\t{ t = \"turnin\", quest = 1474, title = \"The Binding\", npc = 5675, npcName = \"Carendin Halgar\", map = 1458, x = 85.17, y = 26.11, z = -62.2, spotsPacked = \"84.9,26,-62.2,15,8\", note = \"{npc:5675}: {spell:712}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:185334}\",\n\t\tnote = \"{npc:185334} (level 22) works in {area:392}, on the {zone:1413} coast, at one of two spots in town: take the zeppelin to {zone:1411} and head south, or fly from {zone:1454}. He is an Alliance-friendly human: attacking him can flag you for PvP.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 22 },\n\t\t\t{ t = \"collect\", quest = 65593, title = \"Hearts of the Lovers\", item = 190180, itemName = \"Isaac's Heart\", count = 1, oi = 2, map = 1413, x = 62.03, y = 38.26, f = \"e\", spotsPacked = \"62.1,38.5,,36,3;62.8,37.5,,15,1;61.1,38.3,,15,1\", lvl = 22, from = \"Isaac Pearson\", fromKind = \"npc\", fromFaction = \"A\", fromId = 185334, fromNpcs = { { npc = 185334, npcName = \"Isaac Pearson\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:65597}: incubus ({zone:1458})\",\n\t\tnote = \"Back to {npc:5675} with the lovers' hearts, then place the {item:190181} on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: {npc:5675} takes them back.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 65593, title = \"Hearts of the Lovers\", npc = 5675, npcName = \"Carendin Halgar\", map = 1458, x = 84.93, y = 26.02, z = -62.2, spotsPacked = \"84.9,26,-62.2,15,8\" },\n\t\t\t{ t = \"accept\", quest = 65597, title = \"The Binding\", npc = 5675, npcName = \"Carendin Halgar\", minLevel = 20, qlvl = 20, pre = { 65593 }, closedBy = { 1507 }, endNpcs = { 5675 }, xp = 1550, preTitles = { [1507] = \"Devourer of Souls\", [65593] = \"Hearts of the Lovers\" }, map = 1458, x = 84.88, y = 26.23, z = -62.2, spotsPacked = \"84.9,26,-62.2,15,8\" },\n\t\t\t{ t = \"kill\", quest = 65597, title = \"The Binding\", target = \"Summoned Incubus\", npc = 185335, count = 1, oi = 1, map = 1458, x = 86.62, y = 27.05, f = \"e\", note = \"{npc:185335}, at the circle below {npc:5675}\" },\n\t\t\t{ t = \"turnin\", quest = 65597, title = \"The Binding\", npc = 5675, npcName = \"Carendin Halgar\", map = 1458, x = 85.17, y = 26.11, z = -62.2, spotsPacked = \"84.9,26,-62.2,15,8\", note = \"{npc:5675}: {spell:713}\" },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

