			why = "{spell:71} at 10 and a one-hand weapon of your choice: {npc:5810}'s road, {area:159}'s crypt, or the Skybreaker shield.",
			zone = 1413,
			zoneName = "The Barrens",
			author = "Polestar",
			version = 1,
			names = { ["area:157"] = "Agamand Mills", ["area:158"] = "Agamand Family Crypt", ["area:159"] = "Brill", ["area:16629"] = "Shrine of Akir", ["area:16638"] = "Valanaar", ["area:1699"] = "Thorn Hill", ["area:2119"] = "Gallows' End Tavern", ["area:222"] = "Bloodhoof Village", ["area:362"] = "Razor Hill", ["area:369"] = "Thunder Ridge", ["area:379"] = "Far Watch Post", ["item:263993"] = "Skybreaker Bulwark", ["item:275290"] = "Stormforged Protector", ["item:6486"] = "Singed Scale", ["item:6534"] = "Forged Steel Bars", ["npc:1496"] = "Deathguard Dillinger", ["npc:1500"] = "Coleman Farthing", ["npc:2131"] = "Austil de Mon", ["npc:252377"] = "Seena Skybreaker", ["npc:257196"] = "Zaal Stormshield", ["npc:3041"] = "Torm Ragetotem", ["npc:3063"] = "Krang Stonehoof", ["npc:3130"] = "Thunder Lizard", ["npc:3131"] = "Lightning Hide", ["npc:3169"] = "Tarshaw Jaggedscar", ["npc:5810"] = "Uzzek", ["npc:5878"] = "Thun'grim Firegaze", ["npc:6390"] = "Ulag the Cleaver", ["object:105169"] = "Agamand Weapon Rack", ["object:172958"] = "Valley of Honor", ["object:58369"] = "Stolen Iron Chest", ["quest:1498"] = "Path of Defense", ["quest:1502"] = "Thun'grim Firegaze", ["quest:1503"] = "Forged Steel", ["quest:1505"] = "Veteran Uzzek", ["quest:1818"] = "Speak with Dillinger", ["quest:1819"] = "Ulag the Cleaver", ["quest:94003"] = "The Skybreaker Bulwark", ["spell:5401"] = "Lizard Bolt", ["spell:71"] = "Defensive Stance", ["zone:1411"] = "Durotar", ["zone:1412"] = "Mulgore", ["zone:1413"] = "Barrens", ["zone:1420"] = "Tirisfal Glades", ["zone:1454"] = "Orgrimmar", ["zone:1456"] = "Thunder Bluff" },
			written = { ["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:5810}'s road below still gives a weapon later, once you reach Kalimdor."] = "Back to Seena in Valanaar. She teaches Defensive Stance and gives you the Stormforged Protector, a shield to use it with. Uzzek's road below still gives a weapon later, once you reach Kalimdor.", ["The {object:58369} stands by a broken wagon in the Razormane camp north-west of {npc:5878}, north-east of the Crossroads. Two Razormanes guard it and their hunters pull more quilboar: clear them one at a time, then open the chest (it refills within seconds, so a friend can loot it too)."] = "The Stolen Iron Chest stands by a broken wagon in the Razormane camp north-west of Thun'grim, north-east of the Crossroads. Two Razormanes guard it and their hunters pull more quilboar: clear them one at a time, then open the chest (it refills within seconds, so a friend can loot it too).", ["{npc:5878}'s hut sits on top of {area:1699}, east of the Crossroads. Most slopes are too steep: climb the broad ridge on the north or east side."] = "Thun'grim's hut sits on top of Thorn Hill, east of the Crossroads. Most slopes are too steep: climb the broad ridge on the north or east side.", ["{npc:6390} sleeps in the mausoleum in the graveyard just north of Dillinger. To wake him, click the flat skull plaque on the ground, left of the path to the mausoleum door; the seal lifts and {npc:6390} (level 11, not elite) walks out. Start at full health."] = "Ulag sleeps in the mausoleum in the graveyard just north of Dillinger. To wake him, click the flat skull plaque on the ground, left of the path to the mausoleum door; the seal lifts and Ulag (level 11, not elite) walks out. Start at full health." },
			stepCount = 16,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:252377} in {area:16638}\",\n\t\tnote = \"At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 94003, title = \"The Skybreaker Bulwark\", npc = 252377, npcName = \"Seena Skybreaker\", minLevel = 10, qlvl = 10, map = 2521, x = 59.82, y = 72.85, z = 675.3 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:257196}\",\n\t\tnote = \"Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"kill\", target = \"Zaal Stormshield\", npc = 257196, map = 2521, x = 56.66, y = 50.4, z = 772.3 },\n\t\t\t{ t = \"collect\", quest = 94003, title = \"The Skybreaker Bulwark\", item = 263993, itemName = \"Skybreaker Bulwark\", count = 1, oi = 1, map = 2521, x = 56.66, y = 50.4, z = 772.3, note = \"{item:263993}, from {npc:257196}\", from = \"Zaal Stormshield\", fromKind = \"npc\", fromId = 257196, fromNpcs = { { npc = 257196, npcName = \"Zaal Stormshield\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:94003}\",\n\t\tnote = \"Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:5810}'s road below still gives a weapon later, once you reach Kalimdor.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 94003, title = \"The Skybreaker Bulwark\", npc = 252377, npcName = \"Seena Skybreaker\", map = 2521, x = 59.82, y = 72.85, z = 675.3, note = \"{npc:252377}: {spell:71}\", rewards = { items = { { item = 275290, itemName = \"Stormforged Protector\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1505} ({area:362})\",\n\t\tnote = \"At 10, {npc:3169}, the warrior trainer in the barracks of {area:362}, sends you to {npc:5810} in the {zone:1413}. Sorek in {zone:1454}'s {object:172958} offers it too. Any Horde warrior may take one of the two roads, never both: heading to {zone:1420} at 10 anyway? {npc:2131} in {area:159}'s inn offers the other: one fight by {area:159}'s graveyard for the same stance, then the Agamand crypt for an heirloom weapon.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 1505, title = \"Veteran Uzzek\", npc = 3169, npcName = \"Tarshaw Jaggedscar\", minLevel = 10, qlvl = 10, closedBy = { 1498, 1818, 1819 }, endNpcs = { 5810 }, xp = 85, preTitles = { [1498] = \"Path of Defense\", [1818] = \"Speak with Dillinger\", [1819] = \"Ulag the Cleaver\" }, map = 1411, x = 54.12, y = 42.42, z = 9.7 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1505} ({zone:1412})\",\n\t\tnote = \"At 10, {npc:3063}, the warrior trainer of {area:222}, sends you to {npc:5810} in the {zone:1413}. {npc:3041} in {zone:1456} offers it too.\",\n\t\tonly = { races = { \"Tauren\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 1505, title = \"Veteran Uzzek\", npc = 3063, npcName = \"Krang Stonehoof\", minLevel = 10, qlvl = 10, closedBy = { 1498, 1818, 1819 }, endNpcs = { 5810 }, xp = 85, preTitles = { [1498] = \"Path of Defense\", [1818] = \"Speak with Dillinger\", [1819] = \"Ulag the Cleaver\" }, map = 1412, x = 48.25, y = 63.76, z = -9 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5810} at {area:379}\",\n\t\tnote = \"{npc:5810} is easy to miss: he stands under a small canopy by a large tree just west of {area:379}, below the road's south side, with the post in sight to his east. Going straight south from the post does not lead to him. From {zone:1411} cross the bridge west; from {zone:1412} head north past the Crossroads.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\", \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1505, title = \"Veteran Uzzek\", npc = 5810, npcName = \"Uzzek\", map = 1413, x = 61.36, y = 21.07, z = 27.3 },\n\t\t\t{ t = \"accept\", quest = 1498, title = \"Path of Defense\", npc = 5810, npcName = \"Uzzek\", minLevel = 10, qlvl = 10, closedBy = { 1819 }, endNpcs = { 5810 }, xp = 625, crumbs = { 1505 }, preTitles = { [1505] = \"Veteran Uzzek\", [1819] = \"Ulag the Cleaver\" }, map = 1413, x = 61.36, y = 21.07, z = 27.3 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Singed Scales in {area:369}\",\n\t\tnote = \"You need five Singed Scales. Thunder Lizards (level 9-10) and Lightning Hides (10-11) live down in the {area:369} crevasse in north-west {zone:1411}, south of {zone:1454}: from the {zone:1413} bridge turn left and follow the river north into it. Both drop a scale about four kills in five; both cast {spell:5401}.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\", \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1498, title = \"Path of Defense\", item = 6486, itemName = \"Singed Scale\", count = 5, oi = 1, map = 1411, x = 41.29, y = 24.35, z = -9, f = \"e\", spotsPacked = \"40.4,24.1,-11.4,54,4;42.8,24.2,,44,5;39.2,25.6,,36,3;40.3,29,-9.4,48,5,,10;39.1,30,-6.6,53,5,,10\", lvl = 11, note = \"{item:6486}, from the lizards\", from = \"Lightning Hide\", fromKind = \"npc\", fromAlso = \"Thunder Lizard\", fromId = 3131, fromAlsoId = 3130, fromNpcs = { { npc = 3131, npcName = \"Lightning Hide\" }, { npc = 3130, npcName = \"Thunder Lizard\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1498}\",\n\t\tnote = \"Back to {npc:5810} under his tree west of {area:379}.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\", \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1498, title = \"Path of Defense\", npc = 5810, npcName = \"Uzzek\", map = 1413, x = 61.36, y = 21.07, z = 27.3, note = \"{npc:5810}: {spell:71}\" },\n\t\t\t{ t = \"accept\", quest = 1502, title = \"Thun'grim Firegaze\", npc = 5810, npcName = \"Uzzek\", minLevel = 10, qlvl = 10, pre = { 1498, 1819 }, preTitles = { [1498] = \"Path of Defense\", [1819] = \"Ulag the Cleaver\" }, map = 1413, x = 61.36, y = 21.07, z = 27.3 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1502}\",\n\t\tnote = \"{npc:5878}'s hut sits on top of {area:1699}, east of the Crossroads. Most slopes are too steep: climb the broad ridge on the north or east side.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\", \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1502, title = \"Thun'grim Firegaze\", npc = 5878, npcName = \"Thun'grim Firegaze\", map = 1413, x = 57.19, y = 30.29, z = 211.4 },\n\t\t\t{ t = \"accept\", quest = 1503, title = \"Forged Steel\", npc = 5878, npcName = \"Thun'grim Firegaze\", minLevel = 10, qlvl = 10, pre = { 1502 }, preTitles = { [1502] = \"Thun'grim Firegaze\" }, map = 1413, x = 57.19, y = 30.29, z = 211.4 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1503}\",\n\t\tnote = \"The {object:58369} stands by a broken wagon in the Razormane camp north-west of {npc:5878}, north-east of the Crossroads. Two Razormanes guard it and their hunters pull more quilboar: clear them one at a time, then open the chest (it refills within seconds, so a friend can loot it too).\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Tauren\", \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1503, title = \"Forged Steel\", item = 6534, itemName = \"Forged Steel Bars\", count = 1, oi = 1, map = 1413, x = 55.01, y = 26.58, z = 91.7, f = \"e\", note = \"{item:6534}, from the {object:58369}\", from = \"Stolen Iron Chest\", fromKind = \"object\", fromId = 58369 },\n\t\t\t{ t = \"turnin\", quest = 1503, title = \"Forged Steel\", npc = 5878, npcName = \"Thun'grim Firegaze\", map = 1413, x = 57.19, y = 30.29, z = 211.4, rewards = { choices = { { item = 7326, itemName = \"Thun'grim's Axe\" }, { item = 7328, itemName = \"Thun'grim's Mace\" }, { item = 7327, itemName = \"Thun'grim's Dagger\" }, { item = 7329, itemName = \"Thun'grim's Sword\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1818}\",\n\t\tnote = \"At 10, {npc:2131}, the warrior trainer inside the inn of {area:159}, sends you to {npc:1496} by the graveyard on {area:159}'s west edge. This road and {npc:5810}'s exclude each other: drop {quest:1505} or {quest:1498} from your log if you hold one.\",\n\t\tonly = { races = { \"Scourge\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 1818, title = \"Speak with Dillinger\", npc = 2131, npcName = \"Austil de Mon\", minLevel = 10, qlvl = 10, closedBy = { 1819, 1505, 1498 }, endNpcs = { 1496 }, xp = 85, preTitles = { [1498] = \"Path of Defense\", [1505] = \"Veteran Uzzek\", [1819] = \"Ulag the Cleaver\" }, map = 1420, x = 61.77, y = 52.4, z = 33.7 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:1496}\",\n\t\tnote = \"Dillinger stands by the graveyard on {area:159}'s west edge. An Orc, Troll, Tauren or Skyborne who took {quest:1818} from {npc:2131} instead of {npc:5810}'s road is led through {area:159} from here.\",\n\t\twhen = { { k = \"turnedin\", neg = true, q = 1505 } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1818, title = \"Speak with Dillinger\", npc = 1496, npcName = \"Deathguard Dillinger\", map = 1420, x = 58.1, y = 51.52, z = 34 },\n\t\t\t{ t = \"accept\", quest = 1819, title = \"Ulag the Cleaver\", npc = 1496, npcName = \"Deathguard Dillinger\", minLevel = 10, qlvl = 10, closedBy = { 1498 }, endNpcs = { 1496 }, xp = 850, crumbs = { 1818 }, preTitles = { [1498] = \"Path of Defense\", [1818] = \"Speak with Dillinger\" }, map = 1420, x = 58.1, y = 51.52, z = 34 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1819}\",\n\t\tnote = \"{npc:6390} sleeps in the mausoleum in the graveyard just north of Dillinger. To wake him, click the flat skull plaque on the ground, left of the path to the mausoleum door; the seal lifts and {npc:6390} (level 11, not elite) walks out. Start at full health.\",\n\t\twhen = { { k = \"turnedin\", neg = true, q = 1505 } },\n\t\tgoals = {\n\t\t\t{ t = \"kill\", quest = 1819, title = \"Ulag the Cleaver\", target = \"Ulag the Cleaver\", npc = 6390, count = 1, oi = 1, map = 1420, x = 59.47, y = 48.28, f = \"e\" },\n\t\t\t{ t = \"turnin\", quest = 1819, title = \"Ulag the Cleaver\", npc = 1496, npcName = \"Deathguard Dillinger\", map = 1420, x = 58.1, y = 51.52, z = 34, note = \"{npc:1496}: {spell:71}\" },\n\t\t\t{ t = \"accept\", quest = 1820, title = \"Speak with Coleman\", npc = 1496, npcName = \"Deathguard Dillinger\", minLevel = 10, qlvl = 10, pre = { 1498, 1819 }, closedBy = { 1821 }, endNpcs = { 1500 }, xp = 210, preTitles = { [1498] = \"Path of Defense\", [1819] = \"Ulag the Cleaver\", [1821] = \"Agamand Heirlooms\" }, map = 1420, x = 58.1, y = 51.52, z = 34 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:1500}\",\n\t\tnote = \"{npc:1500} is in the {area:2119}, the inn on {area:159}'s east side.\",\n\t\twhen = { { k = \"turnedin\", neg = true, q = 1505 } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1820, title = \"Speak with Coleman\", npc = 1500, npcName = \"Coleman Farthing\", map = 1420, x = 61.71, y = 52.27, z = 33.7 },\n\t\t\t{ t = \"accept\", quest = 1821, title = \"Agamand Heirlooms\", npc = 1500, npcName = \"Coleman Farthing\", minLevel = 10, qlvl = 11, pre = { 1498, 1819 }, crumbs = { 1820 }, preTitles = { [1498] = \"Path of Defense\", [1819] = \"Ulag the Cleaver\", [1820] = \"Speak with Coleman\" }, map = 1420, x = 61.71, y = 52.27, z = 33.7 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {area:158}\",\n\t\tnote = \"The four Agamand Weapon Racks are inside the {area:158} at the north end of {area:157}, north of {area:159}, one rack per room: one in the lowest room, two in the pair of rooms up the stairs, one in the room above those. The axe rack stands in a dark corner. The crypt's undead come in packs of three or more and return quickly; the ones in the top room are not linked. The axe, dagger and mace racks take 15 minutes to refill after someone loots them.\",\n\t\twhen = { { k = \"turnedin\", neg = true, q = 1505 } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 11 },\n\t\t\t{ t = \"collect\", quest = 1821, title = \"Agamand Heirlooms\", item = 7567, itemName = \"Agamand Family Axe\", count = 1, oi = 1, map = 1420, x = 51.68, y = 25.69, z = 66.5, f = \"e\", from = \"Agamand Weapon Rack\", fromKind = \"object\", fromId = 105170 },\n\t\t\t{ t = \"collect\", quest = 1821, title = \"Agamand Heirlooms\", item = 7568, itemName = \"Agamand Family Dagger\", count = 1, oi = 2, map = 1420, x = 51.88, y = 27.14, z = 66.5, f = \"e\", spotsPacked = \"51.88,27.14,66.5,0;52.66,27.04,,0\", from = \"Agamand Weapon Rack\", fromKind = \"object\", fromId = 105171 },\n\t\t\t{ t = \"collect\", quest = 1821, title = \"Agamand Heirlooms\", item = 7569, itemName = \"Agamand Family Mace\", count = 1, oi = 3, map = 1420, x = 51.88, y = 27.14, z = 66.5, f = \"e\", spotsPacked = \"51.88,27.14,66.5,0;52.66,27.04,,0\", from = \"Agamand Weapon Rack\", fromKind = \"object\", fromId = 105171 },\n\t\t\t{ t = \"collect\", quest = 1821, title = \"Agamand Heirlooms\", item = 7566, itemName = \"Agamand Family Sword\", count = 1, oi = 4, map = 1420, x = 52.66, y = 25.85, z = 58.1, f = \"e\", from = \"Agamand Weapon Rack\", fromKind = \"object\", fromId = 105169 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:1500}\",\n\t\twhen = { { k = \"turnedin\", neg = true, q = 1505 } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1821, title = \"Agamand Heirlooms\", npc = 1500, npcName = \"Coleman Farthing\", map = 1420, x = 61.71, y = 52.27, z = 33.7 },\n\t\t\t{ t = \"accept\", quest = 1822, title = \"Heirloom Weapon\", npc = 1500, npcName = \"Coleman Farthing\", minLevel = 10, qlvl = 11, pre = { 1821 }, preTitles = { [1821] = \"Agamand Heirlooms\" }, map = 1420, x = 61.71, y = 52.27, z = 33.7 },\n\t\t\t{ t = \"turnin\", quest = 1822, title = \"Heirloom Weapon\", npc = 1500, npcName = \"Coleman Farthing\", map = 1420, x = 61.71, y = 52.27, z = 33.7, rewards = { choices = { { item = 7115, itemName = \"Heirloom Axe\" }, { item = 7117, itemName = \"Heirloom Hammer\" }, { item = 7116, itemName = \"Heirloom Dagger\" }, { item = 7118, itemName = \"Heirloom Sword\" } } } },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

