-- Source: forever/collectibles/mounts/horde/great-kodo.guide
do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/collectibles/mounts/horde/great-kodo",
			pack = "guides",
			title = "Great Kodo",
			faction = "Horde",
			minLevel = 60,
			maxLevel = 60,
			category = "Collectibles",
			folder = "Mounts · Level 60",
			keywords = { "Great White Kodo", "Great Brown Kodo", "Great Gray Kodo", "Swift Kodo", "Tauren", "Bloodhoof Village", "Harb Clawhoof", "Kar Stormsinger", "Riding" },
			collects = { 18793, 18794, 18795 },
			zone = 1412,
			zoneName = "Mulgore",
			author = "Polestar",
			version = 1,
			names = { ["area:222"] = "Bloodhoof Village", ["faction:81"] = "Thunder Bluff", ["item:18793"] = "Great White Kodo", ["item:18794"] = "Great Brown Kodo", ["item:18795"] = "Great Gray Kodo", ["npc:3685"] = "Harb Clawhoof", ["npc:3690"] = "Kar Stormsinger", ["skill:762"] = "Riding", ["spell:18995"] = "Kodo Riding", ["zone:1412"] = "Mulgore" },
			stepCount = 3,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"Journeyman {skill:762}\",\n\t\tnote = \"{npc:3690} and {npc:3685}'s kodos are in {area:222}, {zone:1412}. At 60 {npc:3690} teaches Journeyman {skill:762} to Tauren for 1,000g (10% less at Honored with {faction:81}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each great kodo costs 200g here.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 60 },\n\t\t\t{ t = \"train\", npc = 3690, npcName = \"Kar Stormsinger\", map = 1412, x = 46.75, y = 61.92, z = -9.3, only = { races = { \"Tauren\" } }, note = \"{npc:3690}, riding trainer\" },\n\t\t\t{ t = \"skill\", skill = \"Riding\", skillLine = 762, level = 150 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{spell:18995} for other races\",\n\t\tnote = \"Any Horde race can buy these kodos, but riding one also takes {spell:18995}, which only Tauren get with {skill:762}. {npc:3690} teaches it to other races once they are Exalted with {faction:81} (the Thunder Bluff Reputation guide shows the way). Until then, don't buy a kodo for this character.\",\n\t\tonly = { races = { \"Orc\", \"Troll\", \"Scourge\", \"Skyborne\" } },\n\t\twhen = { { k = \"knows\", neg = true, spell = 18995 } },\n\t\tgoals = {\n\t\t\t{ t = \"rep\", faction = 81, factionName = \"Thunder Bluff\", standing = 8 },\n\t\t\t{ t = \"train\", npc = 3690, npcName = \"Kar Stormsinger\", map = 1412, x = 46.75, y = 61.92, z = -9.3, note = \"{npc:3690}, {spell:18995}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Pick a colour\",\n\t\tnote = \"{npc:3685} sells the other colours (200g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like.\",\n\t\tgoals = {\n\t\t\t{ t = \"vendor\", npc = 3685, npcName = \"Harb Clawhoof\", map = 1412, x = 46.58, y = 62.01, z = -9.3 },\n\t\t\t{ t = \"buy\", npc = 3685, npcName = \"Harb Clawhoof\", item = 18793, itemName = \"Great White Kodo\", map = 1412, x = 46.58, y = 62.01, z = -9.3, optional = true, note = \"{item:18793}, 200g\" },\n\t\t\t{ t = \"buy\", npc = 3685, npcName = \"Harb Clawhoof\", item = 18794, itemName = \"Great Brown Kodo\", map = 1412, x = 46.58, y = 62.01, z = -9.3, optional = true, note = \"{item:18794}, 200g\" },\n\t\t\t{ t = \"buy\", npc = 3685, npcName = \"Harb Clawhoof\", item = 18795, itemName = \"Great Gray Kodo\", map = 1412, x = 46.58, y = 62.01, z = -9.3, optional = true, note = \"{item:18795}, 200g\" },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

