 = "Crane Operator Bigglefuzz", ["npc:3995"] = "Witch Doctor Jin'Zil", ["npc:4016"] = "Fey Dragon", ["npc:4018"] = "Antlered Courser", ["npc:4020"] = "Sap Beast", ["npc:4038"] = "Burning Destroyer", ["npc:4041"] = "Scorched Basilisk", ["npc:4049"] = "Seereth Stonebreak", ["npc:4067"] = "Twilight Runner", ["npc:4073"] = "XT:4", ["npc:4074"] = "XT:9", ["npc:4128"] = "Hecklefang Stalker", ["npc:4198"] = "Braelyn Firehand", ["npc:4201"] = "Ziz Fizziks", ["npc:4202"] = "Gerenzo Wrenchwhistle", ["npc:4721"] = "Zangen Stonehoof", ["npc:5859"] = "Hagg Taurenbane", ["npc:5899"] = "Brine", ["npc:5911"] = "Grunt Logmar", ["object:177929"] = "Gaea Dirt Mound", ["object:19594"] = "Venture Co. Copter Pad", ["object:3685"] = "Silithid Mound", ["object:667362"] = "Mirkweed", ["object:667364"] = "Dried Mirkweed Pile", ["quest:1068"] = "Shredding Machines", ["quest:1086"] = "The Flying Machine Airport", ["quest:1094"] = "Further Instructions", ["quest:1096"] = "Gerenzo Wrenchwhistle", ["quest:873"] = "Isha Awak", ["quest:874"] = "Mahren Skyseer", ["quest:885"] = "Washte Pawne", ["quest:97250"] = "Wrongly Blamed, Justly Corrected", ["quest:98093"] = "Field to Clear", ["spell:1752"] = "Sinister Strike", ["zone:1412"] = "Mulgore", ["zone:1413"] = "The Barrens", ["zone:1440"] = "Ashenvale", ["zone:1441"] = "Thousand Needles", ["zone:1442"] = "Stonetalon Mountains", ["zone:1456"] = "Thunder Bluff" },
			written = { ["East along the road from {area:2539} to {npc:4049}'s camp."] = "East along the road from Malaka'jin to Seereth's camp.", ["Follow the road on west past {npc:4049}'s camp into Stonetalon: {npc:3995} waits below ground in {area:2539}, at the foot of the {area:1076}."] = "Follow the road on west past Seereth's camp into Stonetalon: Witch Doctor Jin'Zil waits below ground in Malaka'jin, at the foot of the Webwinder Path.", ["Keep {npc:4202} (27) and {npc:4049}'s robots: {area:461} comes in one trip on the way back down from Sun Rock."] = "Keep Gerenzo (27) and Seereth's robots: Windshear Crag comes in one trip on the way back down from Sun Rock.", ["On the way back east to {npc:3341}: Hecklefang Stalkers and {npc:3238} lizards roam the plain between the ridge and his camp. Careful: Qiraji Lieutenants (28, elite) sometimes stand on that plain: give them a wide berth."] = "On the way back east to Gann: Hecklefang Stalkers and Stormhide lizards roam the plain between the ridge and his camp. Careful: Qiraji Lieutenants (28, elite) sometimes stand on that plain: give them a wide berth.", ["South of Camp Taurajo, on the road to {npc:3341}, the Silithid Mounds dot the {area:390}; the eggs lie in them, and Silithid Swarmers come out to defend them.\nCareful: Silithid Swarmers in the area release many tiny adds that interrupt spells; damage shields such as Thorns kill them in one hit."] = "South of Camp Taurajo, on the road to Gann, the Silithid Mounds dot the Field of Giants; the eggs lie in them, and Silithid Swarmers come out to defend them.\nCareful: Silithid Swarmers in the area release many tiny adds that interrupt spells; damage shields such as Thorns kill them in one hit.", ["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south. Careful: the Burning Destroyers, Scorched Basilisks and Bloodfury Storm Witches here are level 27 and the valley floor is crowded: pull one at a time and keep to its edges."] = "South-west of Sun Rock lies the burned Charred Vale. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop Incendrites. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south. Careful: the Burning Destroyers, Scorched Basilisks and Bloodfury Storm Witches here are level 27 and the valley floor is crowded: pull one at a time and keep to its edges.", ["The dwarves' flying machine sits on its platform inside the dig site. Use the {item:5021} that {npc:3341} gave you on it."] = "The dwarves' flying machine sits on its platform inside the dig site. Use the Explosive Stick of Gann that Gann gave you on it.", ["The road west past {npc:4049}'s camp"] = "The road west past Seereth's camp", ["The {object:19594} is the platform just south-east of {npc:4202}'s tower: place Zamah's {item:5638} on it. Zamah takes it back on the next guide's {zone:1456} stop."] = "The Venture Co. Copter Pad is the platform just south-east of Gerenzo's tower: place Zamah's Toxic Fogger on it. Zamah takes it back on the next guide's Thunder Bluff stop.", ["{area:718} quests still in your log: {npc:3446} stands beside the WANTED poster, Bigglefuzz on the dock by the flight master."] = "Wailing Caverns quests still in your log: Mebok stands beside the WANTED poster, Bigglefuzz on the dock by the flight master.", ["{npc:14242}, up in the tree just east of {npc:3341}"] = "Sulhasa, up in the tree just east of Gann", ["{npc:3341} walks the road south toward {area:359}, between about 46,75 and 46,81: if he isn't at the arrow, follow the road until you meet him. {npc:14242} sits up in the tree just east of the road at 47.9,77.5."] = "Gann walks the road south toward Bael Modan, between about 46,75 and 46,81: if he isn't at the arrow, follow the road until you meet him. Sulhasa sits up in the tree just east of the road at 47.9,77.5.", ["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "Braelyn's next quest, Ordanus, is on the Alliance side of Ashenvale. Skip it.", ["{npc:4201}: {npc:4202}, at the top of the Venture Co. tower on {area:461}"] = "Ziz Fizziks: Gerenzo, at the top of the Venture Co. tower on Windshear Crag", ["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "Isha Awak, a big threshadon, swims in the shallows off the Merchant Coast, east of Mahren." },
