2995"] = "Tal", ["npc:3033"] = "Turak Runetotem", ["npc:3034"] = "Sheal Runetotem", ["npc:3401"] = "Shenthul", ["npc:3419"] = "Apothecary Zamah", ["npc:3809"] = "Ashenvale Bear", ["npc:3817"] = "Shadowhorn Stag", ["npc:4046"] = "Magatha Grimtotem", ["npc:5875"] = "Gan'rul Bloodeye", ["npc:6389"] = "Deathguard Podrig", ["npc:7233"] = "Taskmaster Fizzule", ["npc:7825"] = "Oran Snakewrithe", ["npc:8582"] = "Kadrak", ["object:172960"] = "Cleft of Shadow", ["object:177844"] = "Strange Lockbox", ["object:36126"] = "Royal Quarter", ["object:645153"] = "Offering Stone", ["quest:1063"] = "The Elder Crone", ["quest:1064"] = "Forsaken Aid", ["quest:1513"] = "The Binding", ["quest:2478"] = "Mission: Possible But Not Probable", ["quest:516"] = "Beren's Peril", ["quest:6503"] = "Ashenvale Outrunners", ["quest:6641"] = "Vorsha the Lasher", ["quest:92421"] = "Light's Justice", ["quest:95883"] = "The Tortured Soul", ["quest:95885"] = "The Offering of Blood", ["quest:98252"] = "A Void Path", ["zone:1412"] = "Mulgore", ["zone:1413"] = "Barrens", ["zone:1421"] = "Silverpine Forest", ["zone:1440"] = "Ashenvale", ["zone:1454"] = "Orgrimmar", ["zone:1456"] = "Thunder Bluff", ["zone:1458"] = "Undercity" },
			written = { ["Down the road through Silverpine to the {area:228}: from the zeppelin towers, south through Tirisfal; from the {object:177844}, south-east from the coast to the road. {npc:2121} and {npc:1937} stand by the crypt entrance."] = "Down the road through Silverpine to the Sepulcher: from the zeppelin towers, south through Tirisfal; from the Strange Lockbox, south-east from the coast to the road. Shadow Priest Allister and Apothecary Renferrel stand by the crypt entrance.", ["From the zeppelin towers, run south into Silverpine and west past the {area:240} to the coast: the {object:177844} lies at the bottom of very deep water there, beside an air fissure where you can breathe. Watch your breath on the way down. It holds the {item:15882} for Trial of the Sea Lion. Then on to the {area:228}."] = "From the zeppelin towers, run south into Silverpine and west past the Dead Field to the coast: the Strange Lockbox lies at the bottom of very deep water there, beside an air fissure where you can breathe. Watch your breath on the way down. It holds the Half Pendant of Aquatic Endurance for Trial of the Sea Lion. Then on to the Sepulcher.", ["Out of the ruins, take the road south through Tirisfal into {zone:1421} and on to the {area:228}."] = "Out of the ruins, take the road south through Tirisfal into Silverpine Forest and on to the Sepulcher.", ["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "Steer Va'xug's Eye of Kilrogg out of the ravine to the main road within four minutes; if the channel breaks, ask Va'xug again.", ["The {area:153} is a dungeon for a group of five, about levels 15 to 22, in the ruined city above the {zone:1458}: its portal is in the ruins you walked through.\nInside: every undead can drop {item:268580} for {npc:266484}, so clear as you go. {npc:250660} can drop an {item:280438}, which starts a quest for {npc:2055}, and a {npc:256102} found inside starts one for {npc:7825}: both are in the {zone:1458}, on this route's next stop there."] = "The Ruins of Lordaeron is a dungeon for a group of five, about levels 15 to 22, in the ruined city above the Undercity: its portal is in the ruins you walked through.\nInside: every undead can drop Intact Limbs for Morbin, so clear as you go. The Baron can drop an Abominable Head, which starts a quest for Master Apothecary Faranell, and a Crest of Lordaeron found inside starts one for Oran Snakewrithe: both are in the Undercity, on this route's next stop there.", ["{npc:12696}'s hunt targets Ursangous and Shadumbra are for the next {zone:1440} visit, at 26; Sharptalon (31) only from level 30."] = "Senani's hunt targets Ursangous and Shadumbra are for the next Ashenvale visit, at 26; Sharptalon (31) only from level 30.", ["{npc:12717} walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until {npc:12940} is dead; the Wrathtail naga drop the heads {npc:12719} wants."] = "Muglash walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead; the Wrathtail naga drop the heads Marukai wants.", ["{quest:1063} first: fly to {area:1638} from the {area:2897} flight master. {npc:4046} and {npc:3419} send you to {npc:2216} in {area:272}, the next guide's base, and {area:1638}'s flight path takes you on to {zone:1454}."] = "The Elder Crone first: fly to Thunder Bluff from the Zoram'gar Outpost flight master. Magatha and Apothecary Zamah send you to Apothecary Lydon in Tarren Mill, the next guide's base, and Thunder Bluff's flight path takes you on to Orgrimmar.", ["{quest:1063} first: fly to {area:378} from the {area:2897} flight master and walk on to {zone:1456}. {npc:4046} and {npc:3419} send you to {npc:2216} in {area:272}, the next guide's base, and {zone:1456}'s flight path takes you on to {zone:1454}."] = "The Elder Crone first: fly to Camp Taurajo from the Zoram'gar Outpost flight master and walk on to Thunder Bluff. Magatha and Apothecary Zamah send you to Apothecary Lydon in Tarren Mill, the next guide's base, and Thunder Bluff's flight path takes you on to Orgrimmar." },
