bject:176091"] = "Deadwood Cauldron", ["object:176150"] = "Musty Tome", ["object:177464"] = "Large Termite Mound", ["object:92525"] = "Argent Dawn", ["quest:1000"] = "The New Frontier", ["quest:1123"] = "Rabine Saturna", ["quest:4972"] = "Counting Out Time", ["quest:5086"] = "Toxic Horrors", ["quest:5149"] = "Pamela's Doll", ["quest:5152"] = "Auntie Marlene", ["quest:5154"] = "The Annals of Darrowshire", ["quest:5165"] = "Dousing the Flames of Protection", ["quest:5202"] = "A Strange Red Key", ["quest:5203"] = "Rescue From Jaedenar", ["quest:5211"] = "Defenders of Darrowshire", ["quest:5232"] = "Return to the Bulwark", ["quest:5233"] = "Target: Writhing Haunt", ["quest:5235"] = "Target: Gahrron's Withering", ["quest:5242"] = "A Final Blow", ["quest:5281"] = "The Restless Souls", ["quest:5510"] = "Minion's Scourgestones", ["quest:5527"] = "A Reliquary of Purity", ["quest:6021"] = "Zaeldarr the Outcast", ["quest:838"] = "Scholomance", ["quest:8471"] = "Winterfall Ritual Totem", ["quest:964"] = "Skeletal Fragments", ["spell:10228"] = "Greater Invisibility", ["spell:437801"] = "Light's Hope", ["zone:1413"] = "Barrens", ["zone:1420"] = "Tirisfal Glades", ["zone:1422"] = "Western Plaguelands", ["zone:1423"] = "Eastern Plaguelands", ["zone:1440"] = "Ashenvale", ["zone:1448"] = "Felwood", ["zone:1450"] = "Moonglade", ["zone:1451"] = "Silithus", ["zone:1452"] = "Winterspring", ["zone:1454"] = "Orgrimmar", ["zone:1456"] = "Thunder Bluff", ["zone:2482"] = "Mount Hyjal" },
			written = { ["Back north-east to the {area:192}: knights and magi work the camp, the medics and hunters camp south of it. Set {npc:11615}'s termite barrel down in the middle of the lumber mill while you are there.\nCareful: a {npc:10996}, a level 58-59 elite, can stand at the lumber camp, as at many other spots of the {zone:1422}: give it room."] = "Back north-east to the Northridge Lumber Camp: knights and magi work the camp, the medics and hunters camp south of it. Set Mickey's termite barrel down in the middle of the lumber mill while you are there.\nCareful: a Fallen Hero, a level 58-59 elite, can stand at the lumber camp, as at many other spots of the Western Plaguelands: give it room.", ["Back north-west to {npc:1855}'s hut."] = "Back north-west to Tirion's hut.", ["Back south to the Sanctuary: {npc:9529} takes the shards on the west side of the camp."] = "Back south to the Sanctuary: Maybess takes the shards on the west side of the camp.", ["Back west along the road from {area:199} to the {area:152}: {npc:11055} takes the cauldron's report."] = "Back west along the road from Felstone Field to the Bulwark: Shadow Priestess Vandis takes the cauldron's report.", ["Corrupted Soul Shards from the cultists, for {npc:9529}' Salve via Hunting"] = "Corrupted Soul Shards from the cultists, for Maybess' Salve via Hunting", ["Derrington's {quest:838} is offered from level 55: still under 55 here, the next {area:152} stop offers it again."] = "Derrington's Scholomance is offered from level 55: still under 55 here, the next Bulwark stop offers it again.", ["Go through {area:1769} and take the {zone:1450} branch of the tunnel. {npc:11801} is in {area:2361}.\n{npc:11801} offers {quest:5527} only after you have been inside {area:2577} once: if he doesn't offer it, carry on without it."] = "Go through Timbermaw Hold and take the Moonglade branch of the tunnel. Rabine is in Nighthaven.\nRabine offers A Reliquary of Purity only after you have been inside Dire Maul once: if he doesn't offer it, carry on without it.", ["Hearth to {zone:1454} from the {area:152}: the Hearthstone is still bound there from the previous guide's {zone:1454} stop (Mages teleport). Then the flight master."] = "Hearth to Orgrimmar from the Bulwark: the Hearthstone is still bound there from the previous guide's Orgrimmar stop (Mages teleport). Then the flight master.", ["Hearth to {zone:1454} from the {area:152}: the Hearthstone is still bound there from the previous guide's {zone:1454} stop (Mages teleport). Train before the flight."] = "Hearth to Orgrimmar from the Bulwark: the Hearthstone is still bound there from the previous guide's Orgrimmar stop (Mages teleport). Train before the flight.", ["Hearth to {zone:1454} from the {area:152}: the Hearthstone is still bound there from the previous guide's {zone:1454} stop. Then the flight master."] = "Hearth to Orgrimmar from the Bulwark: the Hearthstone is still bound there from the previous guide's Orgrimmar stop. Then the flight master.", ["Her Scarlets wait until {npc:11615} has given you the termite barrel at the {area:152}: the barrel goes down in the same lumber mill."] = "Her Scarlets wait until Mickey has given you the termite barrel at the Bulwark: the barrel goes down in the same lumber mill.", ["Keep the termites: {npc:11615} at the {area:152} takes them on this guide's ride back west."] = "Keep the termites: Mickey Levine at the Bulwark takes them on this guide's ride back west.", ["Keep {quest:5152}: {npc:10927} lives at {area:197} in the {zone:1422}."] = "Keep Auntie Marlene: Marlene lives at Sorrow Hill in the Western Plaguelands.", ["On west to the {area:152}."] = "On west to the Bulwark.", ["Ride east along the road into the {zone:1423}. {npc:1855} lives in a small house by the {area:2619}, just north of the road at the border; his three hunts are on this guide's ground."] = "Ride east along the road into the Eastern Plaguelands. Tirion lives in a small house by the Thondroril River, just north of the road at the border; his three hunts are on this guide's ground.", ["Ride north up the road from {area:272}. {npc:10927}'s house stands by the road at {area:197}, and {npc:10936}'s monument is in the graveyard behind it."] = "Ride north up the road from Tarren Mill. Marlene's house stands by the road at Sorrow Hill, and Joseph Redpath's monument is in the graveyard behind it.", ["Ride north-west to {npc:1855}'s hut by the {area:2619} and hear him out."] = "Ride north-west to Tirion's hut by the Thondroril River and hear him out.", ["Ride south to {area:2264}, on the road. {item:15447} spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the {item:15454} at once.\nCareful: Unseen Servants call for help within 25 yd once they drop to 40% health. Out of combat they also turn invisible with {spell:10228}. If a call for help happens inside the town, a large number of mobs can join the fight. Fighting near the outskirts lowers this risk.\nWith {quest:5211} in your log (from {npc:11063} at the start of this guide), the Scourge around the town leave Darrowshire Spirits: talk to each one to free it. Free them before you start on the {item:15447}."] = "Ride south to Corin's Crossing, on the road. Living Rot spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the Mortar and Pestle at once.\nCareful: Unseen Servants call for help within 25 yd once they drop to 40% health. Out of combat they also turn invisible with Greater Invisibility. If a call for help happens inside the town, a large number of mobs can join the fight. Fighting near the outskirts lowers this risk.\nWith Defenders of Darrowshire in your log (from Carlin at the start of this guide), the Scourge around the town leave Darrowshire Spirits: talk to each one to free it. Free them before you start on the Living Rot.", ["Ride west from {npc:1855}'s hut into the {zone:1422}: {npc:11610} hides on the hill north-east of the {area:192}, on the way to the {area:152}."] = "Ride west from Tirion's hut into the Western Plaguelands: Kirsta hides on the hill north-east of the Northridge Lumber Camp, on the way to the Bulwark.", ["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "The doll's head and its two sides lie in the houses around Pamela; join them from your bags.", ["The skeletons on the fields east of the {area:152} drop the fragments: take them on the ride east."] = "The skeletons on the fields east of the Bulwark drop the fragments: take them on the ride east.", ["Under 55 on the first {area:152} stop? Derrington's {quest:838} is offered now: Dithers' {quest:964} come from the skeletons on the ride back west from {area:201}."] = "Under 55 on the first Bulwark stop? Derrington's Scholomance is offered now: Dithers' Skeletal Fragments come from the skeletons on the ride back west from Gahrron's Withering.", ["West to the {area:152} one last time."] = "West to the Bulwark one last time.", ["West to the {area:152}."] = "West to the Bulwark.", ["a message for {npc:11063} at {area:2268}"] = "a message for Carlin at Light's Hope Chapel", ["from the cauldron, for {npc:11055} at the {area:152}: on the way back west, after the {zone:1423}"] = "from the cauldron, for Shadow Priestess Vandis at the Bulwark: on the way back west, after the Eastern Plaguelands", ["{area:202}"] = "The Writhing Haunt", ["{area:2261}"] = "The Undercroft", ["{npc:10739} camps by the {area:202}, beside the cauldron; his bears roam the hills north and east of it."] = "Mulgris camps by the Writhing Haunt, beside the cauldron; his bears roam the hills north and east of it.", ["{npc:10926}'s ghost stands in the ruins of {area:2262}, in the south-west."] = "Pamela's ghost stands in the ruins of Darrowshire, in the south-west.", ["{npc:11063}'s Heroes of Darrowshire needs a group in {area:190} and a ride back here at the end: leave it."] = "Carlin's Heroes of Darrowshire needs a group in Hearthglen and a ride back here at the end: leave it.", ["{npc:11610}'s last errand looks over {area:190}, among Scarlets of 58-60: leave it."] = "Kirsta's last errand looks over Hearthglen, among Scarlets of 58-60: leave it.", ["{npc:11613} stands east of the lumber camp; {npc:11611} guards the road north-east of {npc:11610}, toward {area:190}.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight."] = "Huntsman Radley stands east of the lumber camp; Cavalier Durgen guards the road north-east of Kirsta, toward Hearthglen.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight.", ["{npc:12384}, inside"] = "Augustus, inside", ["{npc:1855}'s next errand, Of Lost Honor, leads into the Mossflayer trolls (57-59) of the far north-east: leave it."] = "Tirion's next errand, Of Lost Honor, leads into the Mossflayer trolls (57-59) of the far north-east: leave it." },
