			written = { ["Back north-west to {area:362}: {npc:3139} first, then {npc:3147} in the watchtower, then {npc:3142} and {npc:266940} on the way out east to the shore."] = "Back north-west to Razor Hill: Gar'Thok first, then Furl in the watchtower, then Orgnil and Turroc on the way out east to the shore.", ["Back over the bridge and south along the {zone:1411} bank of the river to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "Back over the bridge and south along the Durotar bank of the river to where a narrow trail climbs the mountain: Telf keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail.", ["Back to {area:362}: {npc:3139}, then {npc:3142}."] = "Back to Razor Hill: Gar'Thok, then Orgnil.", ["Back to {area:362}: {npc:3171}'s next beast and {npc:5810}'s road to {area:379} start here. Everyone else hands {quest:99051} to {npc:3142} when the {zone:1413} guide passes {area:362} on its way out."] = "Back to Razor Hill: Thotar's next beast and Uzzek's road to Far Watch Post start here. Everyone else hands Threat from Below to Orgnil when the Barrens guide passes Razor Hill on its way out.", ["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Inside the cave, keep to the right wall all the way round, over the stream: Yarrog waits at the end.", ["North-east to the beach below {area:370}, north of {npc:275657}: Spitelash Scouts and Attendants hold it. Hunters: tame a {npc:3107} on the beach."] = "North-east to the beach below Drygulch Ravine, north of Heglan: Spitelash Scouts and Attendants hold it. Hunters: tame a Surf Crawler on the beach.", ["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "Heglan stands on the shore east of Razor Hill. The trident, banner and dagger lie on the beach around him.", ["{npc:3294}, by the inn: for {npc:5875} in {zone:1454}"] = "Ophek, by the inn: for Gan'rul in Orgrimmar", ["{npc:3336}: {npc:3337} is on the way to {npc:5907}"] = "Takrin Pathseeker: Kargal is on the way to Kranal Fiss", ["{npc:3336}: {npc:3337} stands at {area:379}, on the {zone:1413} guide's road"] = "Takrin Pathseeker: Kargal stands at Far Watch Post, on the Barrens guide's road", ["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "Canaga stands outside the Den. Spirit Rock is the hill just south of it: drink the Earth Sapta there to see the Minor Manifestation of Earth, then take the Rough Quartz back to Canaga.", ["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "Orgrimmar's main gate is just west of Skull Rock. Gan'rul stands in the Cleft of Shadow, the canyon under the Valley of Strength." },
