			stepCount = 7,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:205729}\",\n\t\tnote = \"{npc:205729} hides in stealth on the main mesa of {zone:1456}, south of its pool: walk to where the arrow points until his outline shows. He hands you the {item:206159}. The quest opens at level 4, but the mine holds Venture Co. Workers (level 8-9), Supervisors (9-10) and {npc:3051} (12): go at 9 or 10.\",\n\t\tgoals = {\n\t\t\t{ t = \"accept\", quest = 76156, title = \"Stalk With The Earthmother\", npc = 205729, npcName = \"Boarton Shadetotem\", minLevel = 4, qlvl = 10, map = 1456, x = 39.51, y = 65.59, z = 131.3, spotsPacked = \"39.5,65.6,131.3,15,5\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{area:360}\",\n\t\tnote = \"Ride down the lift and south-east across {zone:1412} to the {area:360}. Put on the disguise, then open the carts of {object:403041} inside the mine and on the slope outside it; stay on the upper levels where you can, the lower tunnels are packed. Five charges.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 76156, title = \"Stalk With The Earthmother\", item = 206157, itemName = \"Seaforium Mining Charge\", count = 5, oi = 1, map = 1412, x = 58.77, y = 47.41, spotsPacked = \"58.61,47.57,,46,2;60.03,46.34,,33,1;59.8,49.49,,32,2;58.05,44.8,,38;57.4,48.8,,0,,1;56.79,43.26,148.2,0,,1\", note = \"{item:206157}, from the {object:403041}\", from = \"Blasting Supplies\", fromKind = \"object\", fromId = 403041 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:205729}\",\n\t\tnote = \"Back to {npc:205729} in {zone:1456}. He gives you the {item:206176} for his next test.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 76156, title = \"Stalk With The Earthmother\", npc = 205729, npcName = \"Boarton Shadetotem\", map = 1456, x = 39.51, y = 65.59, z = 131.3, spotsPacked = \"39.5,65.6,131.3,15,5\" },\n\t\t\t{ t = \"accept\", quest = 76160, title = \"Stalk With The Earthmother\", npc = 205729, npcName = \"Boarton Shadetotem\", minLevel = 4, qlvl = 11, pre = { 76156 }, preTitles = { [76156] = \"Stalk With The Earthmother\" }, map = 1456, x = 39.4, y = 65.57, z = 131.3, spotsPacked = \"39.5,65.6,131.3,15,5\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Windfury Cones\",\n\t\tnote = \"Windfury Cones lie on the ground under the harpies' nest trees on {area:819}, north-west of {zone:1456}; the harpies do not drop them. The Windfury Sorceresses (level 9-10) and Matriarchs (10-11) there stand close together: pick the cones from the edges. Once you have eight, use the {item:206176} to grind them.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", item = 206170, itemName = \"Windfury Cone\", count = 8, map = 1412, x = 31.9, y = 32, spotsPacked = \"30.9,30.8,,0;31.3,32.8,,0;31.8,35.2,,0;32.8,32.2,21.9,0;37.2,23.7,51.7,0;37.3,22.5,43.9,0;38.1,21.6,32.4,0;38.1,23.3,19.4,0;38.4,21.4,32.4,0;38.77,19.39,46.7,0;38.8,21.7,17.4,0;39.4,20.3,28.6,0;50.7,17.8,,0;51.2,20.7,,0;51.5,21.1,,0;52,21.6,,0;52.7,26.7,-2.8,0;53.1,22.7,,0;54.41,25.58,26.3,0\", optional = true, note = \"the mortar takes all eight\", from = \"Windfury Cone\", fromKind = \"object\", fromId = 403105 },\n\t\t\t{ t = \"use\", quest = 76160, title = \"Stalk With The Earthmother\", item = 206176, itemName = \"Mortar and Pestle\", oi = 1, map = 1412, x = 31.9, y = 32, note = \"grind the eight cones into the {item:206175}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:205729}\",\n\t\tnote = \"Back to {npc:205729}. He hands you the {item:206344} for the last test.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 76160, title = \"Stalk With The Earthmother\", npc = 205729, npcName = \"Boarton Shadetotem\", map = 1456, x = 39.51, y = 65.59, z = 131.3, spotsPacked = \"39.5,65.6,131.3,15,5\" },\n\t\t\t{ t = \"accept\", quest = 76240, title = \"Stalk With The Earthmother\", npc = 205729, npcName = \"Boarton Shadetotem\", minLevel = 4, qlvl = 11, pre = { 76160 }, preTitles = { [76160] = \"Stalk With The Earthmother\" }, map = 1456, x = 39.4, y = 65.57, z = 131.3, spotsPacked = \"39.5,65.6,131.3,15,5\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:6291}\",\n\t\tnote = \"Buy a {item:6291} at the Auction House ({npc:8674}, north of the pool), or fish one yourself: {npc:3028} trains {skill:356} and {npc:3029} beside him sells the {item:6256} and a {item:6529}; the pool on the main mesa gives smallfish at any skill. Then use the {item:206344} on it, wherever you are.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", item = 6291, itemName = \"Raw Brilliant Smallfish\", count = 1, map = 1456, x = 40.4, y = 51.8, f = \"e\", optional = true, note = \"{item:6291}: the Auction House, or the pool; the knife takes it\" },\n\t\t\t{ t = \"use\", quest = 76240, title = \"Stalk With The Earthmother\", item = 206344, itemName = \"Knife Set\", oi = 1, map = 1456, x = 41.7, y = 59.9, f = \"e\", note = \"fillet the smallfish into {item:206345} (where players did it, on the way back to {npc:205729})\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:205729}\",\n\t\tnote = \"Take your weapon from {npc:205729}: the {item:277988} or the {item:278002}.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 76240, title = \"Stalk With The Earthmother\", npc = 205729, npcName = \"Boarton Shadetotem\", map = 1456, x = 39.46, y = 65.13, z = 131.3, spotsPacked = \"39.5,65.6,131.3,15,5\", rewards = { choices = { { item = 277988, itemName = \"Hoof-Holstered Blade\" }, { item = 278002, itemName = \"Valley Cosh\" } } } },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

