			written = { ["Fly to {area:1237} in western {zone:1447}: on Forever, {quest:3505} starts with {npc:8576} there, with no letter from {npc:4485} first. The {quest:3505} quests are level 53 and pay in full at 60 too, as every quest does in Forever. {npc:8576} sends you north-east to the blood elf camp on the bluffs of the northern peninsula."] = "Fly to Valormok in western Azshara: on Forever, Betrayed starts with Ag'tor Bloodfist there, with no letter from Belgrom Rockmaul first. The Betrayed quests are level 53 and pay in full at 60 too, as every quest does in Forever. Ag'tor sends you north-east to the blood elf camp on the bluffs of the northern peninsula.", ["From here it is cloth. Wool, Silk and Mageweave must all be handed in before {npc:14726} offers the {item:14047} donation, and {quest:7832} needs the {item:14047} donation. Buy cloth at the Auction House, or farm it: humanoids drop it, Wool from level 15 to 25, Silk 25 to 40, Mageweave 40 to 50, {item:14047} 50 and up. At 60 farm mobs of level 52 or more: lower ones are grey."] = "From here it is cloth. Wool, Silk and Mageweave must all be handed in before Rashona offers the Runecloth donation, and Additional Runecloth needs the Runecloth donation. Buy cloth at the Auction House, or farm it: humanoids drop it, Wool from level 15 to 25, Silk 25 to 40, Mageweave 40 to 50, Runecloth 50 and up. At 60 farm mobs of level 52 or more: lower ones are grey.", ["Prowlers, {npc:3452} and {quest:881}"] = "Prowlers, Serena and Echeyakee", ["Savannah Prowlers lie west and north of the Crossroads. {quest:876} leads the Witchwing harpies in the far north-west. Then {npc:3338} gives you the {item:10327}: blow it beside the kodo bones at {object:147524}, north of the town, and kill the white lion."] = "Savannah Prowlers lie west and north of the Crossroads. Serena Bloodfeather leads the Witchwing harpies in the far north-west. Then Sergra gives you the Horn of Echeyakee: blow it beside the kodo bones at Echeyakee's Lair, north of the town, and kill the white lion.", ["{area:362}: {npc:3142}"] = "Razor Hill: Orgnil", ["{faction:76}: {npc:3216} and {npc:3230}"] = "Orgrimmar: Neeru and Nazgrel", ["{faction:76}: {npc:4949} and {npc:3216}"] = "Orgrimmar: Thrall and Neeru" },
			stepCount = 60,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{faction:76}: how it works\",\n\t\tnote = \"{faction:76} reputation comes from quests and cloth. {npc:14726}, the cloth quartermaster, stands in the Drag beside the cloth and leather armor shop. She takes four one-time donations of 60 cloth (150 each) and then {quest:7832}, 20 {item:14047} for 50, as often as you like. Every point you earn with {faction:76} also gives a quarter as much to {zone:1456}, the {zone:1458} and the Darkspear Trolls. While you level, do {faction:76}'s quests within 5 levels of them: {zone:1411} at 5 to 12, the Crossroads at 12 to 20, {npc:4949}'s {quest:5726} at 12 to 16. The Legacy perk Diplomat adds up to 10%. Rewards: at Honored Orgrimmar's merchants sell to you for 10% less (the Classic rule), the wolf vendor included; at Exalted other races can buy the wolves: 20 gold for a level 40 wolf, 200 gold for a swift wolf at level 60, once you have mount training. {faction:76} has no tabard or other reward.\",\n\t\tgoals = {\n\t\t\t{ t = \"goto\", text = \"{npc:14726}\", map = 1454, x = 63.6, y = 51.2, f = \"e\", note = \"her donations are handed in from her window and never enter the log\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{area:363} (optional hub)\",\n\t\tnote = \"Forever pays these old quests in full at any level. The {area:363} is the best of them: about 1,400 {faction:76} and 1,400 Darkspear reputation in 25 minutes. {npc:3143} waits in the Den, the big hut; {npc:10176} stands outside it.\",\n\t\tlabel = \"valley\",\n\t\tgoals = {\n\t\t\t{ t = \"accept\", quest = 787, title = \"The New Horde\", npc = 3144, npcName = \"Eitrigg\", minLevel = 1, qlvl = 1, map = 1454, x = 34.47, y = 39.18, z = 41, spotsPacked = \"34.3,39.1,41,15,3\", note = \"{npc:3144}, in {faction:76}: {quest:787}, +50\" },\n\t\t\t{ t = \"turnin\", quest = 787, title = \"The New Horde\", npc = 3143, npcName = \"Gornek\", map = 1411, x = 41.97, y = 68.36, z = 41.3 },\n\t\t\t{ t = \"accept\", quest = 4641, title = \"Your Place in the World\", npc = 10176, npcName = \"Kaltunk\", minLevel = 1, qlvl = 1, closedBy = { 788 }, endNpcs = { 3143 }, xp = 40, preTitles = { [788] = \"Cutting Teeth\" }, map = 1411, x = 43.22, y = 68.55, z = 39, note = \"{npc:10176}: {quest:4641}, +50\" },\n\t\t\t{ t = \"turnin\", quest = 4641, title = \"Your Place in the World\", npc = 3143, npcName = \"Gornek\", map = 1411, x = 41.97, y = 68.36, z = 41.3 },\n\t\t\t{ t = \"accept\", quest = 788, title = \"Cutting Teeth\", npc = 3143, npcName = \"Gornek\", minLevel = 1, qlvl = 2, crumbs = { 4641 }, preTitles = { [4641] = \"Your Place in the World\" }, map = 1411, x = 41.97, y = 68.36, z = 41.3, note = \"{quest:788}, +100\" },\n\t\t\t{ t = \"accept\", quest = 97279, title = \"Wayward Weapons\", npc = 3143, npcName = \"Gornek\", minLevel = 1, qlvl = 2, map = 1411, x = 41.97, y = 68.36, z = 41.3, note = \"{quest:97279}, +100\" },\n\t\t\t{ t = \"accept\", quest = 5441, title = \"Lazy Peons\", npc = 11378, npcName = \"Foreman Thazz'ril\", minLevel = 3, qlvl = 4, map = 1411, x = 44.53, y = 68.65, z = 40.1, note = \"{npc:11378}: {quest:5441}, +150\" },\n\t\t\t{ t = \"accept\", quest = 792, title = \"Vile Familiars\", npc = 3145, npcName = \"Zureetha Fargaze\", minLevel = 2, qlvl = 4, map = 1411, x = 42.76, y = 69.07, z = 38.2, only = { classes = { \"WARRIOR\", \"PALADIN\", \"HUNTER\", \"ROGUE\", \"PRIEST\", \"SHAMAN\", \"MAGE\", \"DRUID\" } }, note = \"{npc:3145}: {quest:792}, +150\" },\n\t\t\t{ t = \"accept\", quest = 1485, title = \"Vile Familiars\", npc = 5765, npcName = \"Ruzan\", minLevel = 1, qlvl = 4, closedBy = { 1470 }, endNpcs = { 5765 }, xp = 360, preTitles = { [1470] = \"Piercing the Veil\" }, map = 1411, x = 42.56, y = 68.89, z = 38.2, only = { classes = { \"WARLOCK\" } }, note = \"{npc:5765}: {quest:792}, warlocks only\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Boars, weapons and peons\",\n\t\tnote = \"The training weapons lie on the ground in the Den and among the boars to the north. For the peons: target a sleeping {npc:10556} and use the {item:16114} on it.\",\n\t\twhen = { { k = \"done\", label = \"valley\" } },\n\t\tgoals = {\n\t\t\t{ t = \"kill\", quest = 788, title = \"Cutting Teeth\", target = \"Mottled Boar\", npc = 3098, count = 10, oi = 1, map = 1411, x = 42.72, y = 71.58, z = 40.3, f = \"e\", spotsPacked = \"42.4,72.1,,56,6;44.3,71.2,,54,6;46.1,69,,53,4;45,65.7,38.3,56,8;46.2,66.6,,27,3;42.4,64.3,,67,8;42.7,61.2,60.2,51,7;44.5,60.7,54.8,51,7;44.2,63.6,,50,7,1;46.8,64.6,,25,2,1;45.7,62.6,40.1,55,6,1\", lvl = 2 },\n\t\t\t{ t = \"collect\", quest = 97279, title = \"Wayward Weapons\", item = 277653, itemName = \"Abandoned Training Weapon\", count = 6, oi = 1, map = 1411, x = 43.09, y = 71.65, z = 41.3, f = \"e\", spotsPacked = \"43.1,72.3,42.4,33,6;44.4,71.2,41.6,49,7;41.3,71.5,30,39,3;44.18,66.21,37.8,50,11;42.3,64.4,52.3,15,1;43.7,62.7,51,49,4;41.4,62.8,,53,6;46.2,61.2,53,54,4,1;44.8,59,,35,2,1\", from = \"Abandoned Training Weapon\", fromKind = \"object\", fromId = 673476 },\n\t\t\t{ t = \"kill\", quest = 5441, title = \"Lazy Peons\", target = \"Lazy Peon\", npc = 10556, count = 5, oi = 1, text = \"Wake {npc:10556}\", map = 1411, x = 42.34, y = 73.25, z = 45.3, f = \"e\", spotsPacked = \"41.82,72.93,,30,1;44.61,72.9,45.6,15,1;44.96,69.09,41.8,15,1;45.66,65.72,46.4,15,1;47.34,65.64,51.1,15,1;47.51,69.31,46.4,15,1;46.75,60.68,54.8,15,1;47.07,57.9,63.9,15,1;43.85,57.74,65.2,55,1;41.13,59.66,,29,2\", spread = true, lvl = 4, note = \"{npc:10556}: hit it with the {item:16114}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{area:364}: hand in\",\n\t\twhen = { { k = \"done\", label = \"valley\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 788, title = \"Cutting Teeth\", npc = 3143, npcName = \"Gornek\", map = 1411, x = 41.97, y = 68.36, z = 41.3 },\n\t\t\t{ t = \"accept\", quest = 789, title = \"Sting of the Scorpid\", npc = 3143, npcName = \"Gornek\", minLevel = 1, qlvl = 3, pre = { 788 }, preTitles = { [788] = \"Cutting Teeth\" }, map = 1411, x = 41.97, y = 68.36, z = 41.3