\n\t{\n\t\ttitle = \"Blackrock Mountain, with a group\",\n\t\tnote = \"{area:340} in the {zone:1418} hands out {faction:76} quests for {area:1584} and {area:1583}, all level 58 to 60 and paid in full: Precarious Predicament and Operation: Death to Angerforge (150 each), {quest:4724} and {item:12652} (100 each), {quest:4903} (150), {npc:3144}'s Wisdom (100) and For The Horde! (Rend's head, 200 to every Horde city). These are dungeon quests: take them when your group goes.\",\n\t\tgoals = {\n\t\t\t{ t = \"accept\", quest = 4903, title = \"Warlord's Command\", npc = 9077, npcName = \"Warlord Goretooth\", minLevel = 55, qlvl = 60, pre = { 98325 }, preTitles = { [98325] = \"Blood and Thunder\" }, map = 1418, x = 5.83, y = 47.53, z = 278.6, spotsPacked = \"5.8,47.5,278.6,15,2\", optional = true, note = \"{npc:9077}: {quest:4903}, +150, a group of five\", group = { kind = \"dungeon\", map = 229, name = \"Blackrock Spire\" } },\n\t\t\t{ t = \"accept\", quest = 4724, title = \"The Pack Mistress\", npc = 9081, npcName = \"Galamav the Marksman\", minLevel = 55, qlvl = 59, map = 1418, x = 5.85, y = 47.68, z = 278.6, optional = true, note = \"{npc:9081}: {quest:4724}, +100, a group of five\", group = { kind = \"dungeon\", map = 229, name = \"Blackrock Spire\" } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:7832} to Honored\",\n\t\tnote = \"{quest:7832}: 20 {item:14047} for 50 reputation, as often as you like. Friendly to Honored is 6,000: 120 hand-ins, 2,400 {item:14047}, less what the quests gave you (an orc starts at Friendly 1,000: 100 hand-ins; an Undead or Skyborne starts at Neutral 2,000 and first needs 20 hand-ins, 400 {item:14047}, to reach Friendly). Hand in every 20 you carry, one after another.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", item = 14047, itemName = \"Runecloth\", count = 20, map = 1423, x = 68, y = 69.5, optional = true, note = \"{item:14047}: the Scarlet outside {area:2266}\" },\n\t\t\t{ t = \"turnin\", quest = 7832, title = \"Additional Runecloth\", npc = 14726, npcName = \"Rashona Straglash\", minLevel = 50, qlvl = 60, pre = { 7824 }, map = 1454, x = 63.41, y = 51.02, z = 22.9, spotsPacked = \"63.4,51,22.9,15,2\", optional = true, note = \"{npc:14726}: {quest:7832}, +50\", direct = true },\n\t\t\t{ t = \"rep\", faction = 76, factionName = \"Orgrimmar\", standing = 6 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:7832} to Revered\",\n\t\tnote = \"Honored to Revered is 12,000: 240 hand-ins, 4,800 {item:14047}. The Auction House price of a stack decides whether to farm or buy.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", item = 14047, itemName = \"Runecloth\", count = 20, map = 1423, x = 68, y = 69.5, optional = true },\n\t\t\t{ t = \"turnin\", quest = 7832, title = \"Additional Runecloth\", npc = 14726, npcName = \"Rashona Straglash\", minLevel = 50, qlvl = 60, pre = { 7824 }, map = 1454, x = 63.41, y = 51.02, z = 22.9, spotsPacked = \"63.4,51,22.9,15,2\", optional = true, note = \"{quest:7832}, +50\", direct = true },\n\t\t\t{ t = \"rep\", faction = 76, factionName = \"Orgrimmar\", standing = 7 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:7832} to Exalted\",\n\t\tnote = \"Revered to Exalted is 21,000: 420 hand-ins, 8,400 {item:14047}. Raid heads pay too: The Lord of Blackrock (Nefarian) 200 to every Horde city and Victory for the Horde (Onyxia) 400 to {faction:76}. At Exalted, {npc:3362} in the {object:172958} sells the wolves to every Horde race: 20 gold for a level 40 wolf, 200 gold for a swift wolf at level 60 (Forever's prices); in Classic other races needed Exalted to buy them.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", item = 14047, itemName = \"Runecloth\", count = 20, map = 1423, x = 68, y = 69.5, optional = true },\n\t\t\t{ t = \"turnin\", quest = 7832, title = \"Additional Runecloth\", npc = 14726, npcName = \"Rashona Straglash\", minLevel = 50, qlvl = 60, pre = { 7824 }, map = 1454, x = 63.41, y = 51.02, z = 22.9, spotsPacked = \"63.4,51,22.9,15,2\", optional = true, note = \"{quest:7832}, +50\", direct = true },\n\t\t\t{ t = \"rep\", faction = 76, factionName = \"Orgrimmar\", standing = 8 },\n\t\t\t{ t = \"talk\", npc = 3362, npcName = \"Ogunaro Wolfrunner\", map = 1454, x = 69.39, y = 12.7, z = 49.7, spotsPacked = \"69.4,12.4,49.7,15,3\", optional = true, note = \"{npc:3362}: the wolves\" },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

