\t\t{ t = \"turnin\", quest = 3761, title = \"Un'Goro Soil\", npc = 9076, npcName = \"Ghede\", map = 1456, x = 77.26, y = 22.24, z = 159.4, spotsPacked = \"77.3,22.2,159.4,15,3\" },\n\t\t\t{ t = \"accept\", quest = 3782, title = \"Morrowgrain Research\", npc = 5769, npcName = \"Arch Druid Hamuul Runetotem\", minLevel = 47, qlvl = 50, pre = { 3761 }, preTitles = { [3761] = \"Un'Goro Soil\" }, map = 1456, x = 78.46, y = 28.19, z = 159.1, spotsPacked = \"78.3,28.7,159.1,15,8\", note = \"{npc:5769}: {quest:3782}\" },\n\t\t\t{ t = \"turnin\", quest = 3782, title = \"Morrowgrain Research\", npc = 9087, npcName = \"Bashana Runetotem\", map = 1456, x = 71.09, y = 33.82, z = 159.3, spotsPacked = \"70.8,33.9,159.3,15,5\" },\n\t\t\t{ t = \"accept\", quest = 3786, title = \"Morrowgrain Research\", npc = 9087, npcName = \"Bashana Runetotem\", minLevel = 47, qlvl = 50, pre = { 3782 }, preTitles = { [3782] = \"Morrowgrain Research\" }, map = 1456, x = 71.09, y = 33.82, z = 159.3, spotsPacked = \"70.8,33.9,159.3,15,5\", note = \"{quest:3782}, +100\" },\n\t\t\t{ t = \"buy\", npc = 9087, npcName = \"Bashana Runetotem\", item = 11020, itemName = \"Evergreen Pouch\", map = 1456, x = 71.09, y = 33.82, z = 159.3, spotsPacked = \"70.8,33.9,159.3,15,5\", note = \"{item:11020}, 1 gold\" },\n\t\t\t{ t = \"buy\", npc = 9087, npcName = \"Bashana Runetotem\", item = 11022, itemName = \"Packet of Tharlendris Seeds\", count = 10, map = 1456, x = 71.09, y = 33.82, z = 159.3, spotsPacked = \"70.8,33.9,159.3,15,5\", note = \"{item:11022}, 10 silver each\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:11040} as you go\",\n\t\twhen = { { k = \"done\", label = \"morrowgrain\" } },\n\t\talong = \"morrowgrain-in\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 3786, title = \"Morrowgrain Research\", item = 11040, itemName = \"Morrowgrain\", count = 10, oi = 1, map = 1456, x = 71.1, y = 34.2, f = \"e\", note = \"{item:11040}: use the pouch every 10 minutes and open the casings; {npc:9087} takes it\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:9087}: {quest:3786}\",\n\t\tnote = \"{npc:9087} stands on {area:1639}. If your 10 {item:11040} are not ready yet, skip this step and go on with the cloth: the cloth steps below list the {item:11040} hand-in too.\",\n\t\tlabel = \"morrowgrain-in\",\n\t\twhen = { { k = \"done\", label = \"morrowgrain\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 3786, title = \"Morrowgrain Research\", npc = 9087, npcName = \"Bashana Runetotem\", map = 1456, x = 71.09, y = 33.82, z = 159.3, spotsPacked = \"70.8,33.9,159.3,15,5\" },\n\t\t\t{ t = \"collect\", item = 11040, itemName = \"Morrowgrain\", count = 10, map = 1456, x = 71.1, y = 34.2, f = \"e\", optional = true },\n\t\t\t{ t = \"turnin\", quest = 3804, title = \"Morrowgrain to Thunder Bluff\", npc = 9087, npcName = \"Bashana Runetotem\", minLevel = 47, qlvl = 55, pre = { 3786 }, map = 1456, x = 71.09, y = 33.82, z = 159.3, spotsPacked = \"70.8,33.9,159.3,15,5\", optional = true, note = \"{quest:3804}, +50\", direct = true },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:7825} to Honored\",\n\t\tnote = \"{quest:7825}: 20 {item:14047} for 50 reputation, as often as you like. Friendly to Honored is 6,000: 120 hand-ins, 2,400 {item:14047}, less what the quests gave you (a tauren starts at Friendly 1,000: 100 hand-ins; an Undead at Neutral 500 first needs 50 more to reach Friendly). Hand in every 20 you carry, one after another.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", item = 14047, itemName = \"Runecloth\", count = 20, map = 1423, x = 68, y = 69.5, optional = true, note = \"{item:14047}: the Scarlet outside {area:2266}\" },\n\t\t\t{ t = \"turnin\", quest = 7825, title = \"Additional Runecloth\", npc = 14728, npcName = \"Rumstag Proudstrider\", minLevel = 50, qlvl = 60, pre = { 7823 }, map = 1456, x = 43.09, y = 42.96, z = 145.9, spotsPacked = \"43.1,43,145.9,15,6\", optional = true, note = \"{npc:14728}: {quest:7825}, +50\", direct = true },\n\t\t\t{ t = \"collect\", item = 11040, itemName = \"Morrowgrain\", count = 10, map = 1456, x = 71.1, y = 34.2, f = \"e\", optional = true, note = \"{item:11040}, if you grow it: {npc:9087} takes it\" },\n\t\t\t{ t = \"turnin\", quest = 3804, title = \"Morrowgrain to Thunder Bluff\", npc = 9087, npcName = \"Bashana Runetotem\", minLevel = 47, qlvl = 55, pre = { 3786 }, map = 1456, x = 71.09, y = 33.82, z = 159.3, spotsPacked = \"70.8,33.9,159.3,15,5\", optional = true, note = \"{npc:9087}: {quest:3804}, +50\", direct = true },\n\t\t\t{ t = \"rep\", faction = 81, factionName = \"Thunder Bluff\", standing = 6 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:7825} to Revered\",\n\t\tnote = \"Honored to Revered is 12,000: 240 hand-ins, 4,800 {item:14047}, fewer if you also hand in {item:11040}. {area:1584} pays too: Disharmony of Flame and Disharmony of Fire from Thunderheart at {area:340} ({npc:9017}, 150 in full).\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", item = 14047, itemName = \"Runecloth\", count = 20, map = 1423, x = 68, y = 69.5, optional = true },\n\t\t\t{ t = \"turnin\", quest = 7825, title = \"Additional Runecloth\", npc = 14728, npcName = \"Rumstag Proudstrider\", minLevel = 50, qlvl = 60, pre = { 7823 }, map = 1456, x = 43.09, y = 42.96, z = 145.9, spotsPacked = \"43.1,43,145.9,15,6\", optional = true, note = \"{quest:7825}, +50\", direct = true },\n\t\t\t{ t = \"collect\", item = 11040, itemName = \"Morrowgrain\", count = 10, map = 1456, x = 71.1, y = 34.2, f = \"e\", optional = true, note = \"{item:11040}, if you grow it\" },\n\t\t\t{ t = \"turnin\", quest = 3804, title = \"Morrowgrain to Thunder Bluff\", npc = 9087, npcName = \"Bashana Runetotem\", minLevel = 47, qlvl = 55, pre = { 3786 }, map = 1456, x = 71.09, y = 33.82, z = 159.3, spotsPacked = \"70.8,33.9,159.3,15,5\", optional = true, note = \"{quest:3804}, +50\", direct = true },\n\t\t\t{ t = \"rep\", faction = 81, factionName = \"Thunder Bluff\", standing = 7 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:7825} to Exalted\",\n\t\tnote = \"Revered to Exalted is 21,000: 420 hand-ins, 8,400 {item:14047}. For The Horde! (Rend's head) and The Lord of Blackrock (Nefarian's head) pay 200 to every Horde city. At Exalted, {npc:3685} in {area:222} sells the kodos to every Horde race: 20 gold for a level 40 kodo, 200 gold for a great kodo at level 60 (Forever's prices); in Classic other races needed Exalted to buy them.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", item = 14047, itemName = \"Runecloth\", count = 20, map = 1423, x = 68, y = 69.5, optional = true },\n\t\t\t{ t = \"turnin\", quest = 7825, title = \"Additional Runecloth\", npc = 14728, npcName = \"Rumstag Proudstrider\", minLevel = 50, qlvl = 60, pre = { 7823 }, map = 1456, x = 43.09, y = 42.96, z = 145.9, spotsPacked = \"43.1,43,145.9,15,6\", optional = true, note = \"{quest:7825}, +50\", direct = true },\n\t\t\t{ t = \"collect\", item = 11040, itemName = \"Morrowgrain\", count = 10, map = 1456, x = 71.1, y = 34.2, f = \"e\", optional = true, note = \"{item:11040}, if you grow it\" },\n\t\t\t{ t = \"turnin\", quest = 3804, title = \"Morrowgrain to Thunder Bluff\", npc = 9087, npcName = \"Bashana Runetotem\", minLevel = 47, qlvl = 55, pre = { 3786 }, map = 1456, x = 71.09, y = 33.82, z = 159.3, spotsPacked = \"70.8,33.9,159.3,15,5\", optional = true, note = \"{quest:3804}, +50\", direct = true },\n\t\t\t{ t = \"rep\", faction = 81, factionName = \"Thunder Bluff\", standing = 8 },\n\t\t\t{ t = \"talk\", npc = 3685, npcName = \"Harb Clawhoof\", map = 1412, x = 46.58, y = 62.01, z = -9.3, optional = true, note = \"{npc:3685}: the kodos\" },\n\t\t},\n\t},\n}",
		})
	end
